        private static void WriteSelfTestDiagnostic(string text)
        {
            try
            {
                string diagnosticPath = Environment.GetEnvironmentVariable("YOMI_SELFTEST_DIAGNOSTIC");
                if (!String.IsNullOrWhiteSpace(diagnosticPath))
                    File.WriteAllText(diagnosticPath, text ?? "", new UTF8Encoding(false));
            }
            catch { }
        }

        private static int StagedSelfTestFailure(string detail)
        {
            string message =
                "YOMI staged WPF self-test failed" + Environment.NewLine +
                "exit_code=3" + Environment.NewLine +
                "phase=post-xaml-load-semantic-probe" + Environment.NewLine +
                "detail=" + (detail ?? "");
            WriteSelfTestDiagnostic(message);
            return 3;
        }

        private static int StartupSelfTestFailure(int code, string testName, ControllerHost controller)
        {
            string detail = "";
            try { detail = controller == null ? "" : controller.SelfTestFailureDetail; } catch { }
            string message =
                "YOMI startup self-test failed" + Environment.NewLine +
                "exit_code=" + code.ToString(CultureInfo.InvariantCulture) + Environment.NewLine +
                "test=" + (testName ?? "") + Environment.NewLine +
                "detail=" + (detail ?? "");
            WriteSelfTestDiagnostic(message);
            return code;
        }

