                            report.AppendLine("revision=R61.96");
                            WriteSelfTestDiagnostic(report.ToString().TrimEnd());
                            for (int i = 0; i < tests.Length; i++)
                            {
                                report.AppendLine("running_test=" + names[i]);
                                WriteSelfTestDiagnostic(report.ToString().TrimEnd());
                                bool passed = false;
                                string detail = "";
                                try
                                {
                                    passed = tests[i]();
                                    if (!passed) detail = controller.SelfTestFailureDetail ?? "";
                                }
                                catch (Exception ex)
                                {
                                    passed = false;
                                    detail = ex.GetType().Name + ": " + ex.Message;
                                }
                                report.AppendLine("test=" + names[i] + "|exit_code=" + codes[i].ToString(CultureInfo.InvariantCulture) + "|result=" + (passed ? "PASS" : "FAIL") + "|detail=" + detail.Replace("\r", " ").Replace("\n", " "));
                                if (!passed) failures.Add(codes[i]);
                                report.AppendLine("completed_test=" + names[i]);
                                WriteSelfTestDiagnostic(report.ToString().TrimEnd());
                            }
                            report.AppendLine("summary=" + (failures.Count == 0 ? "PASS" : "FAIL"));
                            report.AppendLine("failure_count=" + failures.Count.ToString(CultureInfo.InvariantCulture));
                            if (failures.Count != 0) report.AppendLine("failure_codes=" + String.Join(",", failures.Select(v => v.ToString(CultureInfo.InvariantCulture)).ToArray()));
                            WriteSelfTestDiagnostic(report.ToString().TrimEnd());
                            if (failures.Count != 0)
                            {
                                controller.Dispose();
                                try { window.Close(); } catch { }
                                return 17;
                            }
                        }
                        else
                        {
                            if (!controller.SelfTestSettingsHierarchy()) return StartupSelfTestFailure(7, "settings-hierarchy", controller);
                            if (!controller.SelfTestQueueConfidence()) return StartupSelfTestFailure(8, "queue-confidence", controller);
                            if (!controller.SelfTestSystemActivitySummary()) return StartupSelfTestFailure(9, "system-activity-summary", controller);
                            if (!controller.SelfTestSurfaceLanguage()) return StartupSelfTestFailure(10, "surface-language", controller);
                            if (!controller.SelfTestVisualRhythm()) return StartupSelfTestFailure(11, "visual-rhythm", controller);
                            if (!controller.SelfTestShellFidelity()) return StartupSelfTestFailure(12, "shell-fidelity", controller);
                            if (!controller.SelfTestTransportFidelity()) return StartupSelfTestFailure(13, "transport-fidelity", controller);
                            if (!controller.SelfTestLibraryFidelity()) return StartupSelfTestFailure(14, "library-fidelity", controller);
                            if (!controller.SelfTestCohesionFidelity()) return StartupSelfTestFailure(15, "cohesion-fidelity", controller);
                            if (!controller.SelfTestWindowStateFidelity()) return StartupSelfTestFailure(16, "window-state-fidelity", controller);
                            if (!controller.SelfTestPlaylistPoolMixing()) return StartupSelfTestFailure(18, "playlist-pool-mixing", controller);
                            if (!controller.SelfTestSessionSlots()) return StartupSelfTestFailure(19, "session-slots", controller);
                        }
                        var smokeTimer = new DispatcherTimer { Interval = TimeSpan.FromMilliseconds(1800) };
                        smokeTimer.Tick += delegate { smokeTimer.Stop(); try { app.Shutdown(0); } catch { } };
                        smokeTimer.Start();
                        int runCode = app.Run();
                        controller.Dispose();
                        try { window.Close(); } catch { }
                        return dispatcherFailure != 0 ? 1 : runCode;
                    }
                    controller.Initialize();
                    if (args != null && args.Any(a => String.Equals(a, "--settings", StringComparison.OrdinalIgnoreCase)))
                        controller.OpenSettingsInitial();
                    app.Run();
                    controller.Dispose();
                    return 0;
                }
                catch (Exception ex)
                {
                    if (anySelfTest)
                    {
                        try
                        {
                            string diagnosticPath = Environment.GetEnvironmentVariable("YOMI_SELFTEST_DIAGNOSTIC");
                            if (!String.IsNullOrWhiteSpace(diagnosticPath))
                                File.WriteAllText(diagnosticPath, ex.ToString(), new UTF8Encoding(false));
                        }
                        catch { }
                        return 1;
                    }
                    try
                    {
                        string crashRoot = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "YOMI");
                        Directory.CreateDirectory(crashRoot);
                        File.WriteAllText(Path.Combine(crashRoot, "controller-startup-error.log"), DateTime.Now.ToString("O", CultureInfo.InvariantCulture) + Environment.NewLine + ex, new UTF8Encoding(false));
                    }
                    catch { }
                    try
                    {
                        MessageBox.Show(
                            "YOMI could not start.\r\n\r\n" + ex,
                            "YOMI",
                            MessageBoxButton.OK,
                            MessageBoxImage.Error
                        );
                    }
                    catch { }
                    return 1;
                }
            }
        }
    }

