        private void BuildHostedPanels()
        {
            // R61.94: native H.264 composition is primary for real video. The visualizer's
            // MediaElement remains only as an inert compatibility object; no live visualizer
            // route uses it because the binary-color contract requires raw quantized frames.
            ConfigurePreviewElement(_videoHost, false);
            ConfigurePreviewElement(_visualizerHost, true);
            if (_videoHost != null) _videoHost.Visibility = Visibility.Collapsed;
            if (_visualizerHost != null) _visualizerHost.Visibility = Visibility.Collapsed;
            if (_videoFrameHost != null) _videoFrameHost.Visibility = Visibility.Collapsed;
            if (_visualizerFrameHost != null) _visualizerFrameHost.Visibility = Visibility.Collapsed;
        }

        private void ConfigurePreviewElement(MediaElement media, bool visualizer)
        {
            if (media == null) return;
            media.LoadedBehavior = MediaState.Manual;
            media.UnloadedBehavior = MediaState.Manual;
            media.IsMuted = true;
            media.ScrubbingEnabled = true;
            media.MediaOpened += delegate
            {
                string expected = visualizer ? _visualizerNativePreviewFile : _videoNativePreviewFile;
                if (!NativeMediaSourceMatches(media, expected)) return;
                double start = visualizer ? _visualizerPreviewStartSeconds : _videoPreviewStartSeconds;
                SetPreviewPosition(media, start);
                bool paused = _pauseIntentPending ? _pauseIntentState : (_paused || _previewPauseState);
                try { if (paused) media.Pause(); else media.Play(); } catch { }

                if (visualizer)
                {
                    _visualizerNativePreviewActive = true;
                    _visualizerPreviewBackend = "native-media";
                    _visualizerPreviewFailed = false; _visualizerPreviewFailure = ""; _visualizerPreviewReady = true;
                    _visualizerNativeOpenedMs = _clock.ElapsedMilliseconds;
                    if (_visualizerFramePreview != null) { try { _visualizerFramePreview.Dispose(); } catch { } _visualizerFramePreview = null; }
                    if (_visualizerFrameHost != null) { _visualizerFrameHost.Source = null; _visualizerFrameHost.Visibility = Visibility.Collapsed; }
                    if (_visualizerWaitingOverlay != null) _visualizerWaitingOverlay.Visibility = Visibility.Collapsed;
                    media.Visibility = Visibility.Visible;
                    WritePreviewRendererLog("VISUALIZER NATIVE OPEN " + expected + " @ " + start.ToString("0.###", CultureInfo.InvariantCulture));
                    WritePreviewRendererLog("VISUALIZER NATIVE CLOCK FREE-RUN edge-synchronized");
                    SchedulePresentationStatusWrite(true);
                    return;
                }

                // R61.94: MediaOpened means the codec opened, not that the post-seek frame is stable.
                // Keep native video hidden through the seek/play edge and reveal it only after a short
                // generation-guarded settling window. This removes the frame-0 flash/disappear/reappear.
                _videoNativePreviewActive = true;
                _videoPreviewBackend = "native-settling";
                _videoPreviewFailed = false; _videoPreviewFailure = ""; _videoPreviewReady = false;
                _videoNativeOpenedMs = _clock.ElapsedMilliseconds;
                if (_videoFramePreview != null) { try { _videoFramePreview.Dispose(); } catch { } _videoFramePreview = null; }
                if (_videoFrameHost != null) { _videoFrameHost.Source = null; _videoFrameHost.Visibility = Visibility.Collapsed; }
                media.Visibility = Visibility.Collapsed;
                int revealGeneration = _videoNativePreviewGeneration;
                ScheduleNativeVideoStableReveal(media, expected, revealGeneration, 90, 2);
            };
            media.MediaEnded += delegate
            {
                try
                {
                    media.Position = TimeSpan.Zero;
                    bool paused = _pauseIntentPending ? _pauseIntentState : (_paused || _previewPauseState);
                    if (!paused) media.Play();
                }
                catch { }
            };
            media.MediaFailed += delegate(object sender, ExceptionRoutedEventArgs e)
            {
                string detail = e != null && e.ErrorException != null ? e.ErrorException.Message : "Windows media pipeline could not decode the cached preview.";
                int generation = visualizer ? _visualizerNativePreviewGeneration : _videoNativePreviewGeneration;
                FallbackNativePreview(visualizer, generation, "MediaFailed: " + detail);
            };
        }

        private void ScheduleNativeVideoStableReveal(MediaElement media, string expected, int generation, int delayMs, int remainingSeekSettles)
        {
            ThreadPool.QueueUserWorkItem(delegate(object ignored)
            {
                Thread.Sleep(Math.Max(0, delayMs));
                try
                {
                    _window.Dispatcher.BeginInvoke(DispatcherPriority.Render, new Action(delegate
                    {
                        if (_disposed || generation != _videoNativePreviewGeneration || !NativeMediaSourceMatches(media, expected)) return;
                        double target = Math.Max(0, _timePosition);
                        double drift = 0;
                        try { drift = media.Position.TotalSeconds - target; } catch { }
                        if (remainingSeekSettles > 0 && Math.Abs(drift) > 0.30)
                        {
                            // Seek while still hidden, then give MediaElement a render edge to commit the
                            // post-seek frame. Never expose frame zero merely because MediaOpened fired.
                            SetPreviewPosition(media, target);
                            ScheduleNativeVideoStableReveal(media, expected, generation, 70, remainingSeekSettles - 1);
                            return;
                        }
                        bool paused = _pauseIntentPending ? _pauseIntentState : (_paused || _previewPauseState);
                        try { if (paused) media.Pause(); else media.Play(); } catch { }
                        _videoPreviewBackend = "native-media";
                        _videoPreviewReady = true;
                        if (_videoPlaceholder != null) _videoPlaceholder.Visibility = Visibility.Collapsed;
                        media.Visibility = Visibility.Visible;
                        WritePreviewRendererLog("VIDEO NATIVE STABLE REVEAL " + expected + " @ " + target.ToString("0.###", CultureInfo.InvariantCulture) + " drift=" + drift.ToString("0.###", CultureInfo.InvariantCulture));
                        SyncHostedMediaAirspace();
                        SchedulePresentationStatusWrite(true);
                    }));
                }
                catch { }
            });
        }

        private static bool NativeMediaSourceMatches(MediaElement media, string expectedFile)
        {
            if (media == null || media.Source == null || String.IsNullOrWhiteSpace(expectedFile)) return false;
            try
            {
                string actual = media.Source.IsFile ? media.Source.LocalPath : media.Source.ToString();
                return String.Equals(Path.GetFullPath(actual), Path.GetFullPath(expectedFile), StringComparison.OrdinalIgnoreCase);
            }
            catch { return false; }
        }

        private static double PreviewPositionWithinMedia(MediaElement media, double requested)
        {
            double value = Math.Max(0, requested);
            try
            {
                if (media != null && media.NaturalDuration.HasTimeSpan)
                {
                    double duration = media.NaturalDuration.TimeSpan.TotalSeconds;
                    if (duration > 0.25 && value >= duration) value %= duration;
                }
            }
            catch { }
            return value;
        }

        private static void SetPreviewPosition(MediaElement media, double requested)
        {
            if (media == null) return;
            try { media.Position = TimeSpan.FromSeconds(PreviewPositionWithinMedia(media, requested)); } catch { }
        }

        private bool HasModalWpfOverlay()
        {
            return (_settingsOverlay != null && _settingsOverlay.Visibility == Visibility.Visible) ||
                   (_slotsOverlay != null && _slotsOverlay.Visibility == Visibility.Visible) ||
                   (_poolOverlay != null && _poolOverlay.Visibility == Visibility.Visible) ||
                   (_playlistEditorOverlay != null && _playlistEditorOverlay.Visibility == Visibility.Visible) ||
                   (_commandPaletteOverlay != null && _commandPaletteOverlay.Visibility == Visibility.Visible) ||
                   (_operatorDeckOverlay != null && _operatorDeckOverlay.Visibility == Visibility.Visible) ||
                   (_intentFabricOverlay != null && _intentFabricOverlay.Visibility == Visibility.Visible);
        }

        private void SyncHostedMediaAirspace()
        {
            bool videoNative = _videoNativePreviewActive && _videoPreviewReady;
            bool vizNative = _visualizerNativePreviewActive && _visualizerPreviewReady && _visualizerEnabled;
            if (_videoHost != null) _videoHost.Visibility = videoNative ? Visibility.Visible : Visibility.Collapsed;
            if (_visualizerHost != null) _visualizerHost.Visibility = vizNative ? Visibility.Visible : Visibility.Collapsed;
            if (_videoFrameHost != null) _videoFrameHost.Visibility = (!videoNative && _videoPreviewReady && _videoFramePreview != null) ? Visibility.Visible : Visibility.Collapsed;
            if (_visualizerFrameHost != null) _visualizerFrameHost.Visibility = (!vizNative && _visualizerEnabled && _visualizerPreviewReady && _visualizerFramePreview != null) ? Visibility.Visible : Visibility.Collapsed;
        }

        private bool TrySwitchListeningSlotShortcut(Key key)
        {
            int index = -1;
            int keyValue = (int)key;
            if (keyValue >= (int)Key.D1 && keyValue <= (int)Key.D9) index = keyValue - (int)Key.D1;
            else if (keyValue >= (int)Key.NumPad1 && keyValue <= (int)Key.NumPad9) index = keyValue - (int)Key.NumPad1;
            if (index < 0 || index >= _slotItems.Count || _slotSwitchActive) return false;
            SlotRecord target = _slotItems[index];
            if (target == null) return false;
            if (String.Equals(target.Id, _activeSlotId, StringComparison.OrdinalIgnoreCase))
            {
                ShowToast("Listening slot", target.Name + " is already active.");
                return true;
            }
            SwitchListeningSlot(target.Id, "shortcut " + (index + 1).ToString(CultureInfo.InvariantCulture));
            return true;
        }

        private void WireWindow()
        {
            _window.SourceInitialized += delegate
            {
                TryEnableModernWindowChrome();
                ConstrainWindowToVisibleWorkArea();
                try
                {
                    _windowSource = HwndSource.FromHwnd(new WindowInteropHelper(_window).Handle);
                    if (_windowSource != null) _windowSource.AddHook(WindowMessageHook);
                    SyncWindowCompositionBackground();
                }
                catch { _windowSource = null; }
            };

            Button menuRestore = _window.FindName("MenuRestoreButton") as Button;
            if (menuRestore != null) menuRestore.Click += delegate { SetMenuBarVisible(true, true); };

            _minimizeButton.Click += delegate { _window.WindowState = WindowState.Minimized; };
            _maximizeButton.Click += delegate { ToggleMaximize(); };
            _closeButton.Click += delegate { StopYomiAndExit(); };

            _window.StateChanged += delegate
            {
                WindowState previous = _lastWindowState;
                WindowState current = _window.WindowState;
                UpdateMaximizeGlyph();

                if (current == WindowState.Minimized)
                {
                    // Minimize is presentation suspension only. Preserve whether the user
                    // came from maximized state and stop only the child preview HWNDs.
                    StopPreviewProcesses();
                }
                else
                {
                    if (current == WindowState.Maximized)
                        _restoreMaximized = true;
                    else if (current == WindowState.Normal)
                        _restoreMaximized = false;

                    // R61: maximize/restore does not restart healthy previews. Only a real
                    // return from minimized state needs the hosted preview surfaces rebuilt.
                    if (previous == WindowState.Minimized)
                    {
                        if (current == WindowState.Normal)
                            RestoreLogicalNormalGeometry();
                        _lastMediaOccurrence = 0;
                        _window.Dispatcher.BeginInvoke(DispatcherPriority.Background, new Action(delegate { SafeRefresh(true); }));
                    }
                    else if (previous == WindowState.Maximized && current == WindowState.Normal)
                    {
                        RestoreLogicalNormalGeometry();
                    }

                    // R61.67: a maximized desktop window is an information workspace, not a
                    // monitor-sized enlargement of the transport card. Enter Queue-first by
                    // default so the session list consumes the work plane. The operator may
                    // still close Queue explicitly while maximized; this only applies on entry.
                    if (current == WindowState.Maximized && previous == WindowState.Normal && !_miniMode && !_performanceWorkspace && !_queueOpen)
                        SetQueueOpen(true, false);
                }

                _lastWindowState = current;
                ApplyQueueCanvasLayout(true);
                UpdateControllerCadence();
                SaveUiState();
            };

            _window.Activated += delegate { ApplyInstrumentActivity(true); UpdateControllerCadence(); QueueControllerWakeRefresh(); };
            _window.Deactivated += delegate { ApplyInstrumentActivity(false); UpdateControllerCadence(); };

            _window.IsVisibleChanged += delegate
            {
                if (!_window.IsVisible)
                    StopPreviewProcesses();
                else
                {
                    _lastMediaOccurrence = 0;
                    QueueControllerWakeRefresh();
                }
                UpdateControllerCadence();
            };

            _window.Closing += delegate(object sender, CancelEventArgs e)
            {
                SaveUiState();
                if (!_controllerOnlyClose && !_shutdownRequested)
                {
                    _shutdownRequested = true;
                    try
                    {
                        FinalizeListeningVisit(true, true);
                        SlotRecord activeSlot;
                        if (_slotsById.TryGetValue(_activeSlotId ?? "", out activeSlot) && activeSlot != null) CaptureLiveSlotBookmark(activeSlot);
                    }
                    catch { }
                    if (!StopOwnedYomiRuntime())
                    {
                        _shutdownRequested = false;
                        e.Cancel = true;
                        ReportShutdownOwnershipFailure();
                    }
                    else
                    {
                        try { PersistActiveSlotState(false); } catch { }
                    }
                }
            };

            _window.Closed += delegate
            {
                _timer.Stop();
                _queueSearchDebounce.Stop();
                try { if (_windowSource != null) _windowSource.RemoveHook(WindowMessageHook); } catch { }
                _windowSource = null;
                StopPreviewProcesses();
                if (_tray != null)
                    _tray.Visible = false;
                _app.Shutdown();
            };

            _window.SizeChanged += delegate
            {
                ApplyAutomaticScaleTier();
                ApplyCompactLayoutForSize();
                if (!_liveResize && !_windowStateTransition) CaptureNormalWindowGeometry();
                ApplyAdaptiveLayout(false);
                ApplyQueueCanvasLayout(false);
                if (_queueCanvasActive) _window.Dispatcher.BeginInvoke(DispatcherPriority.Background, new Action(ApplyQueuePlayerCompressionForCurrentHeight));
                ApplyQueueTableColumnFit();
                UpdateProgressVisual();
            };
            _window.LocationChanged += delegate { if (!_liveResize && !_windowStateTransition) CaptureNormalWindowGeometry(); };
            _window.PreviewMouseMove += WindowPreviewMouseMoveStatus;
            _window.MouseLeave += delegate { _lastHoverStatusSource = null; if (_hoverStatusText != null) _hoverStatusText.Text = ""; };
            _window.PreviewKeyDown += WindowPreviewKeyDown;
        }

        private static WorkspaceProfile ResolveAutomaticScaleProfile(double width, double height, WorkspaceProfile fullProfile)
        {
            // R61.95: a short window is the normal Queue-closed controller, not Micro.
            // Micro is reserved for genuinely narrow appliance geometry.
            if (width <= AutomaticMicroEnterWidth) return WorkspaceProfile.Micro;
            return IsContextWorkspace(fullProfile) ? fullProfile : WorkspaceProfile.Player;
        }

        private void ApplyAutomaticScaleTier()
        {
            // R61.97: never swap workspace/profile state in the middle of a native drag.
            // The old path could restore a remembered Queue workbench rectangle for one frame,
            // producing the near-fullscreen flash seen in the field recorder. Layout transitions
            // happen after WM_EXITSIZEMOVE, against the rectangle the operator actually chose.
            if (_liveResize || _automaticScaleApplying || _window.WindowState != WindowState.Normal || _applyingWorkspaceProfile || _internalGeometryChange || _overlayExpandedCompactHost) return;
            double width = _window.ActualWidth > 0 ? _window.ActualWidth : _window.Width;
            double height = _window.ActualHeight > 0 ? _window.ActualHeight : _window.Height;
            WorkspaceProfile target = ResolveAutomaticScaleProfile(width, height, _lastFullWorkspaceProfile);
            if ((target == WorkspaceProfile.Micro && _microMode) || (IsContextWorkspace(target) && !_miniMode && _workspaceProfile == target)) return;
            _automaticScaleApplying = true;
            try { ApplyWorkspaceProfile(target, false); }
            finally { _automaticScaleApplying = false; }
        }

        private void ApplyCompactLayoutForSize()
        {
            if (!_miniMode)
            {
                bool compactController = !_queueOpen && !_overlayExpandedCompactHost;
                if (_statusBarSurface != null) _statusBarSurface.Visibility = compactController ? Visibility.Collapsed : Visibility.Visible;
                if (_statusBarRow != null) _statusBarRow.Height = compactController ? new GridLength(0) : new GridLength(23);
                if (_microTitleRow != null) _microTitleRow.Height = GridLength.Auto;
                if (_microTitleGapRow != null) _microTitleGapRow.Height = new GridLength(3);
                return;
            }

            // R61.77 compact appliances spend vertical space on playback before auxiliary chrome.
            // The classic menu remains governed solely by the user's menu preference.
            if (_statusBarSurface != null) _statusBarSurface.Visibility = Visibility.Collapsed;
            if (_statusBarRow != null) _statusBarRow.Height = new GridLength(0);

            double height = _window.ActualHeight > 0 ? _window.ActualHeight : _window.Height;
            bool ultraShortMicro = _microMode && height < 116.0;
            if (_microTitleRow != null) _microTitleRow.Height = ultraShortMicro ? new GridLength(0) : GridLength.Auto;
            if (_microTitleGapRow != null) _microTitleGapRow.Height = ultraShortMicro ? new GridLength(0) : new GridLength(2);
        }

        private void WindowPreviewMouseMoveStatus(object sender, MouseEventArgs e)
        {
            if (_hoverStatusText == null) return;
            DependencyObject current = e.OriginalSource as DependencyObject;
            FrameworkElement candidate = null;
            while (current != null)
            {
                var fe = current as FrameworkElement;
                if (fe != null)
                {
                    object tip = ToolTipService.GetToolTip(fe);
                    string text = tip as string;
                    if (!String.IsNullOrWhiteSpace(text)) { candidate = fe; break; }
                    string automation = System.Windows.Automation.AutomationProperties.GetName(fe);
                    if (!String.IsNullOrWhiteSpace(automation) && (fe is Button || fe is ToggleButton || fe is Slider || fe is ComboBox || fe is TextBox)) { candidate = fe; break; }
                }
                try { current = VisualTreeHelper.GetParent(current); } catch { current = null; }
            }
            if (Object.ReferenceEquals(candidate, _lastHoverStatusSource)) return;
            _lastHoverStatusSource = candidate;
            if (candidate == null) { _hoverStatusText.Text = ""; return; }
            string status = ToolTipService.GetToolTip(candidate) as string;
            if (String.IsNullOrWhiteSpace(status)) status = System.Windows.Automation.AutomationProperties.GetName(candidate);
            _hoverStatusText.Text = String.IsNullOrWhiteSpace(status) ? "" : status.Replace("\r"," ").Replace("\n"," ");
        }

        private void UpdateStatusBarProjection()
        {
            if (_statusPlaybackText != null)
            {
                bool loading = _startupPrewarmInFlight || (_engineLaunchMonitorActive && _engineLaunchPrewarm);
                bool warmReady = _startupPrewarmReady;
                string phase = loading ? "Loading" : (warmReady ? "Ready" : (String.IsNullOrWhiteSpace(_lastPlaybackPhase) ? (_running ? "Ready" : "Stopped") : _lastPlaybackPhase));
                if (IsTransitionPhase(phase)) phase = (_running && _audioActive && !loading) ? "Playing" : "Loading";
                _statusPlaybackText.Text = Char.ToUpperInvariant(phase[0]) + (phase.Length > 1 ? phase.Substring(1) : "");
            }
            if (_statusObsText != null)
            {
                bool connected = _lastObsProbeResult != null && _lastObsProbeResult.BrowserClientCount > 0;
                _statusObsText.Text = connected ? "OBS connected" : (_running ? "OBS waiting" : "OBS —");
                _statusObsText.Foreground = Brush(connected ? "Info" : "TextMuted");
            }
        }

        private IntPtr WindowMessageHook(IntPtr hwnd, int msg, IntPtr wParam, IntPtr lParam, ref bool handled)
        {
            const int WM_NCHITTEST = 0x0084;
            const int WM_ENTERSIZEMOVE = 0x0231;
            const int WM_EXITSIZEMOVE = 0x0232;
            const int HTBOTTOMLEFT = 16;
            const int HTBOTTOMRIGHT = 17;

            // R61.96: straight resize edges stay intentionally narrow so the Queue scrollbar
            // remains easy to grab. Bottom corners retain an 18-DIP target because corner
            // resizing is the high-value two-dimensional gesture. WindowChrome handles the
            // ordinary 4-DIP edges; this hook only enlarges the two bottom corners.
            if (msg == WM_NCHITTEST && _window != null && _window.WindowState == WindowState.Normal && _window.ResizeMode == ResizeMode.CanResize)
            {
                RECT rect;
                if (GetWindowRect(hwnd, out rect))
                {
                    long packed = lParam.ToInt64();
                    int screenX = unchecked((short)(packed & 0xFFFF));
                    int screenY = unchecked((short)((packed >> 16) & 0xFFFF));
                    double scale = 1.0;
                    try
                    {
                        PresentationSource ps = PresentationSource.FromVisual(_window);
                        if (ps != null && ps.CompositionTarget != null) scale = Math.Max(0.5, ps.CompositionTarget.TransformToDevice.M11);
                    }
                    catch { }
                    int corner = Math.Max(12, (int)Math.Ceiling(18.0 * scale));
                    if (screenY >= rect.Bottom - corner)
                    {
                        if (screenX <= rect.Left + corner) { handled = true; return new IntPtr(HTBOTTOMLEFT); }
                        if (screenX >= rect.Right - corner) { handled = true; return new IntPtr(HTBOTTOMRIGHT); }
                    }
                }
            }

            if (msg == WM_ENTERSIZEMOVE && !_liveResize)
            {
                _liveResize = true;
                // R61.36: previews are ordinary WPF Images now. Interactive resize no
                // longer hides them; this hook only marks resize state and lets the normal
                // frame surface continue without resurrecting the retired MediaElements.
                SyncHostedMediaAirspace();
            }
            else if (msg == WM_EXITSIZEMOVE && _liveResize)
            {
                _liveResize = false;
                SyncHostedMediaAirspace();
                // R61.97: only now may width-tier presentation change. This preserves the
                // exact rectangle Windows just committed and prevents workbench geometry flash.
                ApplyAutomaticScaleTier();
                CaptureNormalWindowGeometry();
                ApplyAdaptiveLayout(true);
                UpdateProgressVisual();
                _lastMediaOccurrence = 0;
                SafeRefresh(true);
            }
            return IntPtr.Zero;
        }

        private void WindowPreviewKeyDown(object sender, KeyEventArgs e)
        {
            bool ctrl = (e.KeyboardDevice.Modifiers & ModifierKeys.Control) == ModifierKeys.Control;
            bool shift = (e.KeyboardDevice.Modifiers & ModifierKeys.Shift) == ModifierKeys.Shift;
            bool alt = (e.KeyboardDevice.Modifiers & ModifierKeys.Alt) == ModifierKeys.Alt;

            // R61.36: the in-app playlist editor owns ordinary editing shortcuts while open.
            // The Window sees preview-key events before the TextBox does, so stop player/global
            // shortcuts here and let Ctrl+A/C/V/X/Z work as normal text editing below.
            if (_playlistEditorOverlay != null && _playlistEditorOverlay.Visibility == Visibility.Visible)
            {
                if (ctrl && !shift && !alt && e.Key == Key.S) { SavePlaylistEditor(); e.Handled = true; }
                else if (!ctrl && !shift && !alt && e.Key == Key.Escape) { ClosePlaylistEditor(); e.Handled = true; }
                return;
            }

            if (ctrl && !shift && !alt && e.Key == Key.OemComma)
            {
                OpenIntegratedSettings();
                e.Handled = true;
                return;
            }

            if (!ctrl && !shift && !alt && e.Key == Key.F10)
            {
                SetMenuBarVisible(true, true);
                e.Handled = true;
                return;
            }

            if (ctrl && !shift && alt && e.Key == Key.R)
            {
                CycleRepeatMode();
                e.Handled = true;
                return;
            }

            if (e.Key == Key.Escape && _settingsOverlay.Visibility == Visibility.Visible)
            {
                if (_settingsSearchBox != null && _settingsSearchBox.IsKeyboardFocusWithin && !String.IsNullOrWhiteSpace(_settingsSearchBox.Text))
                {
                    _settingsSearchBox.Clear();
                    e.Handled = true;
                    return;
                }
                CloseIntegratedSettings();
                e.Handled = true;
                return;
            }
            if (_settingsOverlay.Visibility == Visibility.Visible && ctrl && !shift && !alt && e.Key == Key.F)
            {
                _settingsSearchBox.Focus();
                _settingsSearchBox.SelectAll();
                e.Handled = true;
                return;
            }
            // While Settings owns focus, normal media-player hotkeys must not
            // steal Space/arrows/letters from checkboxes and combo boxes.
            if (_settingsOverlay.Visibility == Visibility.Visible)
                return;

            // R61.67: once the command palette is visible it owns the keyboard surface.
            // Do this before other global command chords so list navigation cannot tunnel through
            // into player/workspace actions.
            if (_commandPaletteOverlay.Visibility == Visibility.Visible)
            {
                if (e.Key == Key.Escape)
                {
                    CloseCommandPalette();
                    e.Handled = true;
                }
                else if (ctrl && !shift && !alt && e.Key == Key.F)
                {
                    _commandPaletteSearch.Focus();
                    _commandPaletteSearch.SelectAll();
                    e.Handled = true;
                }
                return;
            }

            if (e.Key == Key.Escape && _slotsOverlay != null && _slotsOverlay.Visibility == Visibility.Visible)
            {
                if (!_slotSwitchActive) CloseListeningSlots();
                e.Handled = true;
                return;
            }
            if (_slotsOverlay != null && _slotsOverlay.Visibility == Visibility.Visible)
                return;

            Key chordKey = e.Key == Key.System ? e.SystemKey : e.Key;
            if (ctrl && !shift && alt && TrySwitchListeningSlotShortcut(chordKey))
            {
                e.Handled = true;
                return;
            }

            if (e.Key == Key.Escape && _poolOverlay != null && _poolOverlay.Visibility == Visibility.Visible)
            {
                if (!_poolBuildActive) ClosePlaylistPool();
                e.Handled = true;
                return;
            }
            if (_poolOverlay != null && _poolOverlay.Visibility == Visibility.Visible)
                return;

            if (ctrl && shift && !alt && e.Key == Key.L)
            {
                OpenIntentFabric();
                e.Handled = true;
                return;
            }

            if (ctrl && shift && !alt && e.Key == Key.X)
            {
                RequestCancelActiveIntent("keyboard abort");
                e.Handled = true;
                return;
            }

            if (ctrl && shift && !alt && e.Key == Key.K)
            {
                OpenOperatorDeck();
                e.Handled = true;
                return;
            }

            if (ctrl && !shift && !alt && e.Key == Key.K)
            {
                OpenCommandPalette();
                e.Handled = true;
                return;
            }
            if (!ctrl && !shift && !alt && e.Key == Key.F1)
            {
                OpenShortcutPalette();
                e.Handled = true;
                return;
            }

            if (e.Key == Key.Escape && _intentFabricOverlay.Visibility == Visibility.Visible)
            {
                CloseIntentFabric();
                e.Handled = true;
                return;
            }

            if (e.Key == Key.Escape && _operatorDeckOverlay.Visibility == Visibility.Visible)
            {
                CloseOperatorDeck();
                e.Handled = true;
                return;
            }

            if (_operatorDeckOverlay.Visibility == Visibility.Visible && !ctrl && !shift && (int)e.Key >= (int)Key.D1 && (int)e.Key <= (int)Key.D6)
            {
                ExecuteOperatorDeckNumber(((int)e.Key - (int)Key.D1) + 1);
                e.Handled = true;
                return;
            }

            if (!ctrl && !shift && !alt && e.Key == Key.Oem2 && _queueOpen)
            {
                _queueSearchBox.Focus();
                _queueSearchBox.SelectAll();
                e.Handled = true;
                return;
            }

            if (e.Key == Key.Escape && _queueOpen && _commandPaletteOverlay.Visibility != Visibility.Visible)
            {
                if (_queueSearchBox.IsKeyboardFocusWithin && !String.IsNullOrWhiteSpace(_queueSearchBox.Text))
                {
                    _queueSearchBox.Clear();
                    e.Handled = true;
                    return;
                }
                SetQueueOpen(false, true);
                e.Handled = true;
                return;
            }

            if (ctrl && !shift && !alt && e.Key == Key.F)
            {
                if (!_queueOpen)
                    SetQueueOpen(true, true);
                _queueSearchBox.Focus();
                _queueSearchBox.SelectAll();
                e.Handled = true;
                return;
            }

            if (ctrl && !shift && !alt && e.Key == Key.G)
            {
                BeginQueueSlotNavigation();
                e.Handled = true;
                return;
            }

            if (ctrl && !shift && !alt && e.Key == Key.Q)
            {
                SetQueueOpen(!_queueOpen, true);
                e.Handled = true;
                return;
            }

            if (ctrl && !shift && !alt && e.Key == Key.Z)
            {
                if (_running) UndoQueueOrder();
                e.Handled = true;
                return;
            }

            if (ctrl && !shift && !alt && e.Key == Key.Y)
            {
                if (_running) RedoQueueOrder();
                e.Handled = true;
                return;
            }

            if (ctrl && !shift && !alt && e.Key == Key.I)
            {
                SetInspectorOpen(!_inspectorOpen, true);
                e.Handled = true;
                return;
            }

            if (ctrl && shift && !alt && e.Key == Key.R)
            {
                SetInspectorOpen(true, true);
                RefreshInspector();
                ShowToast("Media path", "Media-path details are available in Inspector.");
                e.Handled = true;
                return;
            }

            if (ctrl && shift && !alt && e.Key == Key.D1) { ApplyWorkspaceProfile(WorkspaceProfile.Player, true); e.Handled = true; return; }
            if (ctrl && shift && !alt && e.Key == Key.D2) { ApplyWorkspaceProfile(WorkspaceProfile.Broadcast, true); e.Handled = true; return; }
            if (ctrl && shift && !alt && e.Key == Key.D3) { ApplyWorkspaceProfile(WorkspaceProfile.Library, true); e.Handled = true; return; }
            if (ctrl && shift && !alt && e.Key == Key.D4) { ApplyWorkspaceProfile(WorkspaceProfile.Performance, true); e.Handled = true; return; }
            if (ctrl && shift && !alt && e.Key == Key.Back) { ReturnToPreviousWorkspace(); e.Handled = true; return; }

            if (ctrl && !shift && !alt && e.Key == Key.M)
            {
                SetMicroMode(!_microMode, true);
                e.Handled = true;
                return;
            }

            if (ctrl && shift && !alt && e.Key == Key.V)
            {
                SetVisualizerEnabled(!_visualizerEnabled, true);
                e.Handled = true;
                return;
            }

            if (ctrl && !shift && !alt && e.Key == Key.D1) { ToggleMediaModule(true); e.Handled = true; return; }
            if (ctrl && !shift && !alt && e.Key == Key.D2) { ToggleMediaModule(false); e.Handled = true; return; }

            if (ctrl && !shift && !alt && e.Key == Key.D)
            {
                ToggleFavoriteSelectedOrCurrent();
                e.Handled = true;
                return;
            }

            if (ctrl && shift && !alt && e.Key == Key.M)
            {
                ToggleMute();
                e.Handled = true;
                return;
            }

            if (ctrl && !shift && !alt && e.Key == Key.Up)
            {
                AdjustVolume(2.0);
                e.Handled = true;
                return;
            }
            if (ctrl && !shift && !alt && e.Key == Key.Down)
            {
                AdjustVolume(-2.0);
                e.Handled = true;
                return;
            }

            if (ctrl && !shift && alt && e.Key == Key.T)
            {
                SetAlwaysOnTop(!_alwaysOnTop, true);
                e.Handled = true;
                return;
            }

            // R61.36: selectable/read-only text is still text. Once a user clicks title,
            // channel or Inspector detail to select/copy it, do not reinterpret typing,
            // Space or cursor keys as player transport until focus leaves that TextBox.
            bool nativeTextFocus = Keyboard.FocusedElement is TextBox;
            bool editing = _queueSearchBox.IsKeyboardFocusWithin || _commandPaletteSearch.IsKeyboardFocusWithin || nativeTextFocus;
            if (!editing && e.Key == Key.Space)
            {
                TogglePlayPause();
                e.Handled = true;
                return;
            }

            if (!editing && (e.Key == Key.Left || e.Key == Key.Right) && _running)
            {
                double step = shift ? 15.0 : 5.0;
                SeekRelative(e.Key == Key.Left ? -step : step);
                e.Handled = true;
                return;
            }

            if (!editing && e.Key == Key.MediaNextTrack)
            {
                if (_running) NavigateRelative(1);
                e.Handled = true;
                return;
            }
            if (!editing && e.Key == Key.MediaPreviousTrack)
            {
                if (_running) NavigateRelative(-1);
                e.Handled = true;
            }
        }

        private void NavigateRelative(int delta)
        {
            if (!_running || delta == 0)
                return;

            // R57 TRANSPORT FIDELITY: relative transport is resolved by the playback
            // authority, not by the controller's periodically refreshed occurrence.
            // Commands are serialized off the UI thread so repeated input stays crisp
            // even if the local IPC endpoint briefly takes time to acknowledge.
            string message = delta > 0 ? "yomi-next" : "yomi-prev";
            // R61.91: snapshot transport handoff evidence before asynchronous dispatch.
            // The engine can publish the destination before the callback runs; capturing here
            // guarantees the accepted command remembers the occurrence that was actually outgoing.
            int transportOutgoingMediaOccurrence = _lastMediaOccurrence > 0 ? _lastMediaOccurrence : _currentOccurrence;
            DispatchTransportCommand(new object[] { "script-message", message }, delegate(bool accepted)
            {
                if (accepted)
                {
                    _lastStateRefreshMs = 0;
                    _lastQueueRefreshMs = 0;
                    _pendingTransportOutgoingMediaOccurrence = transportOutgoingMediaOccurrence;
                    _lastVisualizerDemandSent = null;
                    _lastMediaDemandSent = "";
                    AddActivity("Playback", delta > 0 ? "next requested" : "previous requested");
                    ScheduleFastPlaybackRefresh();
                }
                else
                {
                    ShowToast("Playback", "Engine transport command failed.");
                }
            });
        }

        private void WireTransport()
        {
            _previousButton.Click += delegate { if (_running) NavigateRelative(-1); };
            _nextButton.Click += delegate { if (_running) NavigateRelative(1); };
            _playPauseButton.Click += delegate { TogglePlayPause(); };
            _miniPreviousButton2.Click += delegate { if (_running) NavigateRelative(-1); };
            _miniPlayPauseButton2.Click += delegate { TogglePlayPause(); };
            _miniNextButton2.Click += delegate { if (_running) NavigateRelative(1); };
            _microPreviousButton.Click += delegate { if (_running) NavigateRelative(-1); };
            _microNextButton.Click += delegate { if (_running) NavigateRelative(1); };
            _microPlayPauseButton.Click += delegate { TogglePlayPause(); };
            _repeatStatePill.Click += delegate { CycleRepeatMode(); };
            if (_miniRepeatButton2 != null) _miniRepeatButton2.Click += delegate { CycleRepeatMode(); };
            if (_microRepeatButton != null) _microRepeatButton.Click += delegate { CycleRepeatMode(); };
            if (_queueDockPreviousButton != null) _queueDockPreviousButton.Click += delegate { if (_running) NavigateRelative(-1); };
            if (_queueDockPlayPauseButton != null) _queueDockPlayPauseButton.Click += delegate { TogglePlayPause(); };
            if (_queueDockNextButton != null) _queueDockNextButton.Click += delegate { if (_running) NavigateRelative(1); };
            if (_queueDockRepeatButton != null) _queueDockRepeatButton.Click += delegate { CycleRepeatMode(); };
            if (_queueDockPositionButton != null) _queueDockPositionButton.Click += delegate { SetQueuePlayerDock(_queuePlayerDock == QueuePlayerDock.Top ? QueuePlayerDock.Bottom : QueuePlayerDock.Top, true); };
            if (_queueDockPlayerButton != null) _queueDockPlayerButton.Click += delegate
            {
                SetQueueOpen(false, true);
                if (_window.WindowState == WindowState.Maximized) _window.WindowState = WindowState.Normal;
                _window.Activate();
            };
            if (_queueDockHideButton != null) _queueDockHideButton.Click += delegate { SetQueueOpen(false, true); };
            if (_queueDockElapsedText != null) _queueDockElapsedText.MouseLeftButtonUp += delegate { ToggleTimeDisplayMode(); };
            if (_queueDockRemainingText != null) _queueDockRemainingText.MouseLeftButtonUp += delegate { ToggleTimeDisplayMode(); };

            _previousUpStrip.MouseLeftButtonUp += delegate(object sender, MouseButtonEventArgs e) { if (_running) NavigateRelative(-1); e.Handled = true; };
            _previousAgainButton.Click += delegate(object sender, RoutedEventArgs e) { QueuePreviousAgain(); e.Handled = true; };
            _previousLocateButton.Click += delegate(object sender, RoutedEventArgs e) { LocatePreviousInQueue(); e.Handled = true; };
            _nextLaterButton.Click += delegate(object sender, RoutedEventArgs e) { DeferNextOccurrence(5); e.Handled = true; };
            _nextLocateButton.Click += delegate(object sender, RoutedEventArgs e) { LocateNextInQueue(); e.Handled = true; };
            _favoriteButton.Click += delegate { ToggleFavoriteCurrent(); };
            _copyTrackButton.Click += delegate { CopyNowPlaying(); };
            if (_openSourceButton != null)
            {
                _openSourceButton.Visibility = Visibility.Collapsed;
                _openSourceButton.IsEnabled = false;
            }
            _queueTrackButton.Click += delegate { SetQueueOpen(true, true); JumpQueueToCurrent(); };
            _inspectTrackButton.Click += delegate { ToggleInspectorFromSurface(); };
            _mediaStateInspectButton.Click += delegate { ToggleInspectorFromSurface(); };
            _elapsedText.MouseLeftButtonUp += delegate { ToggleTimeDisplayMode(); };
            _remainingText.MouseLeftButtonUp += delegate { ToggleTimeDisplayMode(); };
            // R50: right-click exposes the actions already present in the hover strip; no second action authority.
            var nowPlayingMenu = new ContextMenu();
            var nowFavoriteItem = AddMenuItem(nowPlayingMenu, "Favorite / unfavorite", delegate { ToggleFavoriteCurrent(); });
            AddMenuItem(nowPlayingMenu, "Copy now playing", delegate { CopyNowPlaying(); });
            AddMenuItem(nowPlayingMenu, "Locate in queue", delegate { SetQueueOpen(true, true); JumpQueueToCurrent(); });
            AddMenuItem(nowPlayingMenu, "Explain track / readiness", delegate { SetInspectorOpen(true, true); RefreshInspector(); });
            _nowPlayingSurface.ContextMenu = nowPlayingMenu;
            nowPlayingMenu.Opened += delegate
            {
                var meta = CurrentMeta();
                nowFavoriteItem.IsEnabled = meta != null;
                nowFavoriteItem.Header = meta != null && IsFavorite(meta) ? "Remove from favorites" : "Add to favorites";
            };
            _miniQueueButton.Click += delegate { OpenQueueFromCompact(WorkspaceProfile.Micro); };
            _miniExpandButton.Click += delegate { SetMiniMode(false, true); };
            _miniMicroButton.Click += delegate { SetMicroMode(true, true); };
            _miniQueueButton2.Click += delegate { if (_queueCanvasActive) SetQueueOpen(false, true); else OpenQueueFromCompact(WorkspaceProfile.Micro); };
            _miniExpandButton2.Click += delegate { if (_queueCanvasActive) SetQueueOpen(false, true); else SetMiniMode(false, true); };
            _miniMicroButton2.Click += delegate { SetMicroMode(true, true); };
            _microQueueButton.Click += delegate { OpenQueueFromCompact(WorkspaceProfile.Micro); };
            _microMiniButton.Click += delegate { SetMicroMode(false, true); };
            _miniNextText.MouseLeftButtonUp += delegate(object sender, MouseButtonEventArgs e) { if (_running) NavigateRelative(1); e.Handled = true; };
            _nextUpStrip.MouseLeftButtonUp += delegate(object sender, MouseButtonEventArgs e) { if (_running) NavigateRelative(1); e.Handled = true; };

            // R61.75: direct Thumbnail and Video toggles are real runtime authorities.
            // A visible control must never be a presentation-only dummy.
            if (_mediaThumbnailToggle != null) _mediaThumbnailToggle.Click += delegate { ToggleMediaModule(true); };
            if (_mediaVideoToggle != null) _mediaVideoToggle.Click += delegate { ToggleMediaModule(false); };

            if (_visualizerQuickStrip != null) _visualizerQuickStrip.Visibility = Visibility.Collapsed;
            _visualizerSizeButton.Click += delegate { CycleVisualizerPresentation(); };

            _visualizerToggle.Click += delegate
            {
                SetVisualizerEnabled(_visualizerToggle.IsChecked == true, true);
            };
            _visualizerSettingsButton.Click += delegate { OpenBroadcastVisualizer(); };

            _queueToggle.Click += delegate
            {
                SetQueueOpen(_queueToggle.IsChecked == true, true);
            };

            _seekSurface.MouseLeftButtonDown += delegate(object sender, MouseButtonEventArgs e)
            {
                if (!_running || _duration <= 0)
                    return;
                _seeking = true;
                _seekSurface.CaptureMouse();
                UpdateSeekPreview(e.GetPosition(_progressTrack).X);
                e.Handled = true;
            };
            _seekSurface.MouseMove += delegate(object sender, MouseEventArgs e)
            {
                if (_duration <= 0)
                    return;
                double x = e.GetPosition(_progressTrack).X;
                UpdateSeekHover(x);
                if (_seeking && e.LeftButton == MouseButtonState.Pressed)
                    UpdateSeekPreview(x);
            };
            _seekSurface.MouseLeave += delegate
            {
                if (!_seeking) HideSeekHover();
            };
            _seekSurface.MouseWheel += delegate(object sender, MouseWheelEventArgs e)
            {
                if (!_running) return;
                SeekRelative(e.Delta >= 0 ? 5.0 : -5.0);
                e.Handled = true;
            };
            _seekSurface.MouseLeftButtonUp += delegate(object sender, MouseButtonEventArgs e)
            {
                if (!_seeking)
                    return;
                UpdateSeekPreview(e.GetPosition(_progressTrack).X);
                _seeking = false;
                _seekSurface.ReleaseMouseCapture();
                SeekAbsolute(_seekPreview);
                e.Handled = true;
            };

            if (_queueDockSeekSurface != null)
            {
                _queueDockSeekSurface.MouseLeftButtonDown += delegate(object sender, MouseButtonEventArgs e)
                {
                    if (!_running || _duration <= 0) return;
                    _seeking = true;
                    _queueDockSeekSurface.CaptureMouse();
                    UpdateQueueDockSeekPreview(e.GetPosition(_queueDockProgressTrack).X);
                    e.Handled = true;
                };
                _queueDockSeekSurface.MouseMove += delegate(object sender, MouseEventArgs e)
                {
                    if (_seeking && e.LeftButton == MouseButtonState.Pressed && _duration > 0)
                        UpdateQueueDockSeekPreview(e.GetPosition(_queueDockProgressTrack).X);
                };
                _queueDockSeekSurface.MouseWheel += delegate(object sender, MouseWheelEventArgs e)
                {
                    if (!_running) return;
                    SeekRelative(e.Delta >= 0 ? 5.0 : -5.0);
                    e.Handled = true;
                };
                _queueDockSeekSurface.MouseLeftButtonUp += delegate(object sender, MouseButtonEventArgs e)
                {
                    if (!_seeking) return;
                    UpdateQueueDockSeekPreview(e.GetPosition(_queueDockProgressTrack).X);
                    _seeking = false;
                    _queueDockSeekSurface.ReleaseMouseCapture();
                    SeekAbsolute(_seekPreview);
                    e.Handled = true;
                };
            }

            _miniSeekSurface.MouseLeftButtonDown += delegate(object sender, MouseButtonEventArgs e)
            {
                if (!_running || _duration <= 0) return;
                _seeking = true;
                _miniSeekSurface.CaptureMouse();
                UpdateMiniSeekPreview(e.GetPosition(_miniProgressTrack).X);
                e.Handled = true;
            };
            _miniSeekSurface.MouseMove += delegate(object sender, MouseEventArgs e)
            {
                if (_seeking && e.LeftButton == MouseButtonState.Pressed && _duration > 0)
                    UpdateMiniSeekPreview(e.GetPosition(_miniProgressTrack).X);
            };
            _miniSeekSurface.MouseWheel += delegate(object sender, MouseWheelEventArgs e)
            {
                if (!_running) return;
                SeekRelative(e.Delta >= 0 ? 5.0 : -5.0);
                e.Handled = true;
            };
            _miniSeekSurface.MouseLeftButtonUp += delegate(object sender, MouseButtonEventArgs e)
            {
                if (!_seeking) return;
                UpdateMiniSeekPreview(e.GetPosition(_miniProgressTrack).X);
                _seeking = false;
                _miniSeekSurface.ReleaseMouseCapture();
                SeekAbsolute(_seekPreview);
                e.Handled = true;
            };

            _microElapsedText.MouseLeftButtonUp += delegate { ToggleTimeDisplayMode(); };
            _microRemainingText.MouseLeftButtonUp += delegate { ToggleTimeDisplayMode(); };
            _microSeekSurface.MouseLeftButtonDown += delegate(object sender, MouseButtonEventArgs e)
            {
                if (!_running || _duration <= 0) return;
                _seeking = true;
                _microSeekSurface.CaptureMouse();
                UpdateMicroSeekPreview(e.GetPosition(_microProgressTrack).X);
                e.Handled = true;
            };
            _microSeekSurface.MouseMove += delegate(object sender, MouseEventArgs e)
            {
                if (_seeking && e.LeftButton == MouseButtonState.Pressed && _duration > 0)
                    UpdateMicroSeekPreview(e.GetPosition(_microProgressTrack).X);
            };
            _microSeekSurface.MouseWheel += delegate(object sender, MouseWheelEventArgs e)
            {
                if (!_running) return;
                SeekRelative(e.Delta >= 0 ? 5.0 : -5.0);
                e.Handled = true;
            };
            _microSeekSurface.MouseLeftButtonUp += delegate(object sender, MouseButtonEventArgs e)
            {
                if (!_seeking) return;
                UpdateMicroSeekPreview(e.GetPosition(_microProgressTrack).X);
                _seeking = false;
                _microSeekSurface.ReleaseMouseCapture();
                SeekAbsolute(_seekPreview);
                e.Handled = true;
            };
        }

        private void WireVolume()
        {
            _volumeButton.Click += delegate { ToggleVolumePopup(_volumeButton); };
            _miniVolumeButton.Click += delegate { ToggleVolumePopup(_miniVolumeButton); };
            _microVolumeButton.Click += delegate { ToggleVolumePopup(_microVolumeButton); };
            if (_queueDockVolumeButton != null) _queueDockVolumeButton.Click += delegate { ToggleVolumePopup(_queueDockVolumeButton); };
            _volumeButton.MouseWheel += delegate(object sender, MouseWheelEventArgs e)
            {
                AdjustVolume(e.Delta >= 0 ? 5.0 : -5.0);
                e.Handled = true;
            };
            _miniVolumeButton.MouseWheel += delegate(object sender, MouseWheelEventArgs e)
            {
                AdjustVolume(e.Delta >= 0 ? 5.0 : -5.0);
                e.Handled = true;
            };
            _microVolumeButton.MouseWheel += delegate(object sender, MouseWheelEventArgs e)
            {
                AdjustVolume(e.Delta >= 0 ? 5.0 : -5.0);
                e.Handled = true;
            };
            if (_queueDockVolumeButton != null) _queueDockVolumeButton.MouseWheel += delegate(object sender, MouseWheelEventArgs e)
            {
                AdjustVolume(e.Delta >= 0 ? 5.0 : -5.0);
                e.Handled = true;
            };
            _mainVolumeSlider.ValueChanged += delegate(object sender, RoutedPropertyChangedEventArgs<double> e)
            {
                if (_syncingVolume || !_running)
                    return;
                SetVolume(e.NewValue, false);
            };
            _mainVolumeSlider.MouseWheel += delegate(object sender, MouseWheelEventArgs e)
            {
                AdjustVolume(e.Delta >= 0 ? 2.0 : -2.0);
                e.Handled = true;
            };
            _volumeSlider.ValueChanged += delegate(object sender, RoutedPropertyChangedEventArgs<double> e)
            {
                if (_syncingVolume || !_running)
                    return;
                SetVolume(e.NewValue, false);
            };
            _volumeSlider.MouseWheel += delegate(object sender, MouseWheelEventArgs e)
            {
                AdjustVolume(e.Delta >= 0 ? 2.0 : -2.0);
                e.Handled = true;
            };
            _volumeMuteToggle.Click += delegate { SetMute(_volumeMuteToggle.IsChecked == true); };
        }

        private void ToggleVolumePopup(Button target)
        {
            RefreshVolumeState(true);
            if (_volumePopup != null && target != null) _volumePopup.PlacementTarget = target;
            _volumePopup.IsOpen = !_volumePopup.IsOpen;
        }

        private void QueueMpvVolumeSnapshotRefresh()
        {
            if (_disposed || !_running) return;
            lock (_volumeSnapshotSync)
            {
                if (_volumeSnapshotWorkerActive) return;
                _volumeSnapshotWorkerActive = true;
            }
            ThreadPool.QueueUserWorkItem(delegate(object ignored)
            {
                double volume = _volume; bool muted = _muted; bool okVolume = false, okMute = false;
                try
                {
                    object raw;
                    if (GetMpvProperty("volume", out raw)) { volume = Math.Max(0, Math.Min(130, ToDouble(raw, volume))); okVolume = true; }
                    if (GetMpvProperty("mute", out raw))
                    {
                        muted = raw is bool ? (bool)raw : String.Equals(Convert.ToString(raw, CultureInfo.InvariantCulture), "true", StringComparison.OrdinalIgnoreCase);
                        okMute = true;
                    }
                }
                catch { }
                lock (_volumeSnapshotSync)
                {
                    if (okVolume || okMute)
                    {
                        if (okVolume) _volumeSnapshotVolume = volume;
                        if (okMute) _volumeSnapshotMuted = muted;
                        _volumeSnapshotValid = true;
                        _volumeSnapshotStampMs = _clock.ElapsedMilliseconds;
                    }
                    _volumeSnapshotWorkerActive = false;
                }
            });
        }

        private void RefreshVolumeState(bool force)
        {
            if (_volumeButton == null) return;
            long now = _clock.ElapsedMilliseconds;
            if (!force && now - _lastVolumeRefreshMs < 1200) return;
            _lastVolumeRefreshMs = now;

            if (!_running)
            {
                _volumeAppliedToRuntime = false;
                _volumeButton.IsEnabled = false;
                if (_mainVolumeSlider != null) _mainVolumeSlider.IsEnabled = false;
                if (_queueDockVolumeButton != null) _queueDockVolumeButton.IsEnabled = false;
                lock (_volumeSnapshotSync) _volumeSnapshotValid = false;
                if (_volumePreferenceLoaded) ApplyVolumeUi();
                else { _volumeButton.Content = "Vol"; if (_queueDockVolumeButton != null) _queueDockVolumeButton.Content = "Vol"; _volumeValueText.Text = ""; }
                return;
            }

            _volumeButton.IsEnabled = true;
            if (_mainVolumeSlider != null) _mainVolumeSlider.IsEnabled = true;
            if (_queueDockVolumeButton != null) _queueDockVolumeButton.IsEnabled = true;
            if (_volumePreferenceLoaded && !_volumeAppliedToRuntime)
            {
                // Fire-and-forget property writes are bounded and do not wait for a response.
                bool volumeApplied = SendMpv("set_property", "volume", Math.Round(_volume, 1));
                bool muteApplied = SendMpv("set_property", "mute", _muted);
                if (volumeApplied && muteApplied) _volumeAppliedToRuntime = true;
                ApplyVolumeUi();
                QueueMpvVolumeSnapshotRefresh();
                return;
            }

            QueueMpvVolumeSnapshotRefresh();
            lock (_volumeSnapshotSync)
            {
                if (_volumeSnapshotValid && now - _volumeSnapshotStampMs <= 5000)
                {
                    _volume = _volumeSnapshotVolume;
                    _muted = _volumeSnapshotMuted;
                }
            }
            ApplyVolumeUi();
        }

        private void ApplyVolumeUi()
        {
            _syncingVolume = true;
            try
            {
                if (_mainVolumeSlider != null) _mainVolumeSlider.Value = Math.Max(0, Math.Min(130, _volume));
                if (_volumeSlider != null) _volumeSlider.Value = Math.Max(0, Math.Min(130, _volume));
                if (_volumeMuteToggle != null) _volumeMuteToggle.IsChecked = _muted;
                string value = Math.Round(_volume).ToString("0", CultureInfo.InvariantCulture);
                if (_mainVolumeValueText != null) _mainVolumeValueText.Text = _muted ? "Mute" : value + "%";
                if (_volumeValueText != null) _volumeValueText.Text = _muted ? "Muted " + value + "%" : value + "%";
                if (_volumeButton != null) _volumeButton.Content = _muted ? "Muted" : "Vol " + value;
                if (_statusVolumeText != null) _statusVolumeText.Text = _muted ? "Mute " + value + "%" : "Vol " + value + "%";
                if (_queueDockVolumeButton != null) { _queueDockVolumeButton.Content = _muted ? "Muted" : "Vol " + value; _queueDockVolumeButton.IsEnabled = _running; }
            }
            finally { _syncingVolume = false; }
        }

        private void AdjustVolume(double delta)
        {
            if (!_running) return;
            RefreshVolumeState(true);
            SetVolume(Math.Max(0, Math.Min(130, _volume + delta)), true);
        }

        private void SetVolume(double value, bool toast)
        {
            if (!_running) return;
            value = Math.Max(0, Math.Min(130, value));
            if (SendMpv("set_property", "volume", Math.Round(value, 1)))
            {
                _volume = value;
                _volumePreferenceLoaded = true;
                _volumeAppliedToRuntime = true;
                if (_muted && value > 0) SetMute(false, false);
                ApplyVolumeUi();
                SaveUiState();
                if (toast) ShowToast("Volume", Math.Round(_volume).ToString("0", CultureInfo.InvariantCulture) + "%");
            }
        }

        private void ToggleMute()
        {
            if (!_running) return;
            RefreshVolumeState(true);
            SetMute(!_muted);
        }

        private void SetMute(bool muted)
        {
            SetMute(muted, true);
        }

        private void SetMute(bool muted, bool toast)
        {
            if (!_running) return;
            if (SendMpv("set_property", "mute", muted))
            {
                _muted = muted;
                _volumePreferenceLoaded = true;
                _volumeAppliedToRuntime = true;
                ApplyVolumeUi();
                SaveUiState();
                if (toast) ShowToast("Audio", muted ? "Muted" : "Unmuted");
            }
        }

        private MenuItem MenuAction(string header, string gesture, Action action)
        {
            var item = new MenuItem { Header = header };
            if (!String.IsNullOrWhiteSpace(gesture)) item.InputGestureText = gesture;
            item.Click += delegate { if (action != null) action(); };
            return item;
        }

        private MenuItem MenuSub(string header) { return new MenuItem { Header = header }; }
        private void MenuSeparator(MenuItem menu) { menu.Items.Add(new Separator()); }

        private string ActiveSlotDescriptorPath { get { return Path.Combine(_dataRoot, "active-slot.json"); } }
        private string SlotSwitchJournalPath { get { return Path.Combine(_stateRoot, "listening-slot-switch.pending.json"); } }

        private string SlotRootPath(string id)
        {
            return Path.Combine(_slotsRoot, NormalizeSlotId(id));
        }

        private string SlotManifestPath(string id)
        {
            return Path.Combine(SlotRootPath(id), "slot.json");
        }

        private static string NormalizeSlotId(string value)
        {
            string raw = (value ?? "").Trim();
            if (raw.Length == 0) return "";
            var sb = new StringBuilder();
            foreach (char c in raw)
            {
                if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '-' || c == '_') sb.Append(c);
            }
            string clean = sb.ToString();
            return clean.Length > 80 ? clean.Substring(0, 80) : clean;
        }

        private static string NormalizeSlotName(string value)
        {
            string name = (value ?? "").Replace("\r", " ").Replace("\n", " ").Trim();
            while (name.Contains("  ")) name = name.Replace("  ", " ");
            if (name.Length > 80) name = name.Substring(0, 80).Trim();
            return name;
        }

        private static string NormalizeSlotBroadcastPreset(string value)
        {
            string preset = (value ?? "").Trim();
            foreach (string allowed in new[] { "Keep current", "Classic strip", "Split sources", "Text + artwork", "Visual focus" })
                if (String.Equals(preset, allowed, StringComparison.OrdinalIgnoreCase)) return allowed;
            return "Keep current";
        }

        private string UniqueSlotName(string preferred)
        {
            string basis = NormalizeSlotName(preferred);
            if (basis.Length == 0) basis = "New slot";
            string candidate = basis;
            int suffix = 2;
            while (_slotItems.Any(x => String.Equals(x.Name, candidate, StringComparison.OrdinalIgnoreCase)))
            {
                candidate = basis + " " + suffix.ToString(CultureInfo.InvariantCulture);
                suffix++;
            }
            return candidate;
        }

        private static string NewSlotId()
        {
            return "slot-" + Guid.NewGuid().ToString("N").Substring(0, 12);
        }

        private SlotRecord ReadSlotRecord(string id)
        {
            string clean = NormalizeSlotId(id);
            if (clean.Length == 0) return null;
            string path = SlotManifestPath(clean);
            if (!File.Exists(path)) return null;
            try
            {
                Dictionary<string, object> map = ReadJsonFresh(path);
                if (map.Count == 0) return null;
                string storedId = NormalizeSlotId(GetString(map, "id", clean));
                if (!String.Equals(storedId, clean, StringComparison.OrdinalIgnoreCase)) return null;
                return new SlotRecord
                {
                    Id = clean,
                    Name = NormalizeSlotName(GetString(map, "name", clean)),
                    SourceKind = GetString(map, "source_kind", "Playlist"),
                    PoolName = GetString(map, "pool_name", ""),
                    TrackCount = Math.Max(0, GetInt(map, "track_count", 0)),
                    BookmarkOccurrence = Math.Max(0, GetInt(map, "bookmark_occurrence", 0)),
                    BookmarkSeconds = Math.Max(0, GetDouble(map, "bookmark_seconds", 0)),
                    Paused = GetBool(map, "paused", false),
                    BroadcastPreset = NormalizeSlotBroadcastPreset(GetString(map, "broadcast_preset", "Keep current")),
                    CreatedUtc = GetString(map, "created_utc", ""),
                    UpdatedUtc = GetString(map, "updated_utc", ""),
                    LastUsedUtc = GetString(map, "last_used_utc", "")
                };
            }
            catch { return null; }
        }

        private void SaveSlotRecord(SlotRecord slot)
        {
            if (slot == null) return;
            slot.Id = NormalizeSlotId(slot.Id);
            slot.Name = NormalizeSlotName(slot.Name);
            if (slot.Id.Length == 0) throw new InvalidOperationException("Listening slot has no valid ID.");
            if (slot.Name.Length == 0) slot.Name = "Slot";
            if (String.IsNullOrWhiteSpace(slot.CreatedUtc)) slot.CreatedUtc = DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture);
            slot.UpdatedUtc = DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture);
            string root = SlotRootPath(slot.Id);
            Directory.CreateDirectory(root);
            var map = new Dictionary<string, object>
            {
                { "schema", 2 }, { "id", slot.Id }, { "name", slot.Name },
                { "source_kind", slot.SourceKind ?? "Playlist" }, { "pool_name", slot.PoolName ?? "" }, { "track_count", slot.TrackCount },
                { "bookmark_occurrence", slot.BookmarkOccurrence }, { "bookmark_seconds", Math.Max(0, slot.BookmarkSeconds) }, { "paused", slot.Paused },
                { "broadcast_preset", NormalizeSlotBroadcastPreset(slot.BroadcastPreset) },
                { "created_utc", slot.CreatedUtc ?? "" }, { "updated_utc", slot.UpdatedUtc ?? "" }, { "last_used_utc", slot.LastUsedUtc ?? "" }
            };
            WriteUtf8NoBom(SlotManifestPath(slot.Id), _json.Serialize(map));
        }

        private void WriteActiveSlotDescriptor(SlotRecord slot)
        {
            if (slot == null) return;
            Directory.CreateDirectory(_dataRoot);
            var map = new Dictionary<string, object>
            {
                { "schema", 2 }, { "id", slot.Id ?? "" }, { "name", slot.Name ?? "" },
                { "source_kind", slot.SourceKind ?? "Playlist" }, { "pool_name", slot.PoolName ?? "" },
                { "bookmark_occurrence", slot.BookmarkOccurrence }, { "bookmark_seconds", Math.Max(0, slot.BookmarkSeconds) }, { "paused", slot.Paused },
                { "broadcast_preset", NormalizeSlotBroadcastPreset(slot.BroadcastPreset) },
                { "updated_utc", DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture) }
            };
            WriteUtf8NoBom(ActiveSlotDescriptorPath, _json.Serialize(map));
        }

        private void ReloadSlotRecords()
        {
            string previousSelection = "";
            if (_slotsList != null && _slotsList.SelectedItem is SlotRecord) previousSelection = ((SlotRecord)_slotsList.SelectedItem).Id;
            _slotUiSyncing = true;
            try
            {
                _slotItems.Clear();
                _slotsById.Clear();
                if (Directory.Exists(_slotsRoot))
                {
                    var loaded = new List<SlotRecord>();
                    foreach (string directory in Directory.GetDirectories(_slotsRoot))
                    {
                        string id = NormalizeSlotId(Path.GetFileName(directory));
                        SlotRecord slot = ReadSlotRecord(id);
                        if (slot != null) loaded.Add(slot);
                    }
                    foreach (SlotRecord slot in loaded.OrderBy(x => String.IsNullOrWhiteSpace(x.CreatedUtc) ? "9999" : x.CreatedUtc, StringComparer.Ordinal).ThenBy(x => x.Name, StringComparer.OrdinalIgnoreCase))
                    {
                        slot.IsActive = String.Equals(slot.Id, _activeSlotId ?? "", StringComparison.OrdinalIgnoreCase);
                        _slotItems.Add(slot);
                        _slotsById[slot.Id] = slot;
                    }
                }
                if (_slotSelector != null)
                {
                    SlotRecord active;
                    _slotsById.TryGetValue(_activeSlotId ?? "", out active);
                    _slotSelector.SelectedItem = active;
                    _slotSelector.ToolTip = active == null
                        ? "Switch listening slot. Ctrl+Alt+1-9 switches the first nine slots."
                        : active.Name + " | " + active.ListSubtitle + " | Ctrl+Alt+1-9 switches the first nine slots.";
                }
                if (_slotsList != null)
                {
                    SlotRecord selected = null;
                    if (!String.IsNullOrWhiteSpace(previousSelection)) _slotsById.TryGetValue(previousSelection, out selected);
                    if (selected == null) _slotsById.TryGetValue(_activeSlotId ?? "", out selected);
                    _slotsList.SelectedItem = selected;
                }
            }
            finally { _slotUiSyncing = false; }
            UpdateSlotManagerSelection();
        }

        private int ReadResumeOccurrence()
        {
            try
            {
                string path = Path.Combine(_stateRoot, "resume-track.txt");
                if (!File.Exists(path)) return 0;
                int value;
                return Int32.TryParse((ReadTextShared(path) ?? "").Trim(), NumberStyles.Integer, CultureInfo.InvariantCulture, out value) ? Math.Max(0, value) : 0;
            }
            catch { return 0; }
        }

        private int CountPlaylistEntries(string path)
        {
            try
            {
                if (!File.Exists(path)) return 0;
                int count = 0;
                foreach (string raw in File.ReadLines(path, Encoding.UTF8))
                {
                    string line = (raw ?? "").Trim();
                    if (line.StartsWith("http://", StringComparison.OrdinalIgnoreCase) || line.StartsWith("https://", StringComparison.OrdinalIgnoreCase)) count++;
                }
                return count;
            }
            catch { return 0; }
        }

        private bool ActivePlaylistMatchesCurrentPool()
        {
            try
            {
                Dictionary<string, object> pool = ReadJsonFresh(CurrentPoolPath);
                var tracks = GetList(pool, "tracks");
                if (tracks.Count == 0) return false;
                var playlist = File.Exists(DirectPlaylistPath)
                    ? File.ReadAllLines(DirectPlaylistPath, Encoding.UTF8).Select(x => (x ?? "").Trim()).Where(x => x.StartsWith("http://", StringComparison.OrdinalIgnoreCase) || x.StartsWith("https://", StringComparison.OrdinalIgnoreCase)).ToList()
                    : new List<string>();
                if (playlist.Count != tracks.Count) return false;
                // Source ownership must be exact. Sampling only the first few entries can
                // misclassify a hand-edited playlist as its former Pool when a later URL changed.
                for (int i = 0; i < playlist.Count; i++)
                {
                    string url = GetString(AsMap(tracks[i]), "url", "").Trim();
                    if (!String.Equals(url, playlist[i], StringComparison.OrdinalIgnoreCase)) return false;
                }
                return true;
            }
            catch { return false; }
        }

        private string DetectActiveSlotSourceKind(out string poolName)
        {
            poolName = "";
            int count = CountPlaylistEntries(DirectPlaylistPath);
            if (count <= 0) return "Empty";
            if (ActivePlaylistMatchesCurrentPool())
            {
                Dictionary<string, object> pool = ReadJsonFresh(CurrentPoolPath);
                poolName = GetString(pool, "name", "Current Pool");
                return "Pool";
            }
            return "Playlist";
        }

        private void WriteSlotSwitchJournal(SlotRecord from, SlotRecord to)
        {
            if (from == null || to == null) throw new InvalidOperationException("Listening-slot switch has no rollback authority.");
            Directory.CreateDirectory(_stateRoot);
            var map = new Dictionary<string, object>
            {
                { "schema", 1 }, { "from_id", from.Id ?? "" }, { "from_name", from.Name ?? "" },
                { "to_id", to.Id ?? "" }, { "to_name", to.Name ?? "" },
                { "created_utc", DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture) }
            };
            WriteUtf8NoBom(SlotSwitchJournalPath, _json.Serialize(map));
        }

        private void ClearSlotSwitchJournal()
        {
            try { File.Delete(SlotSwitchJournalPath); } catch { }
        }

        private void RecoverInterruptedSlotSwitch()
        {
            if (!File.Exists(SlotSwitchJournalPath)) return;
            Dictionary<string, object> journal = ReadJsonFresh(SlotSwitchJournalPath);
            string fromId = NormalizeSlotId(GetString(journal, "from_id", ""));
            SlotRecord from = null;
            if (fromId.Length > 0) _slotsById.TryGetValue(fromId, out from);
            if (from == null)
            {
                // Never guess which Slot owns partially restored global files. Preserve the
                // evidence for diagnostics and continue with the last committed descriptor.
                string quarantine = SlotSwitchJournalPath + ".unresolved." + DateTime.UtcNow.ToString("yyyyMMdd-HHmmss", CultureInfo.InvariantCulture);
                try { File.Move(SlotSwitchJournalPath, quarantine); } catch { }
                return;
            }

            RestoreSlotIntoGlobal(from);
            _activeSlotId = from.Id;
            _activeSlotName = from.Name;
            WriteActiveSlotDescriptor(from);
            ClearSlotSwitchJournal();
            AddActivity("Listening slot", "recovered interrupted switch | restored " + from.Name);
        }

        private void CopyGlobalFileToSlot(string relative, string slotRoot)
        {
            string source = Path.Combine(_dataRoot, relative);
            string target = Path.Combine(slotRoot, relative);
            if (File.Exists(source))
            {
                string parent = Path.GetDirectoryName(target);
                if (!String.IsNullOrWhiteSpace(parent)) Directory.CreateDirectory(parent);
                File.Copy(source, target, true);
            }
            else
            {
                try { if (File.Exists(target)) File.Delete(target); } catch { }
            }
        }

        private void RestoreSlotFileToGlobal(string relative, string slotRoot)
        {
            string source = Path.Combine(slotRoot, relative);
            string target = Path.Combine(_dataRoot, relative);
            if (File.Exists(source))
            {
                string parent = Path.GetDirectoryName(target);
                if (!String.IsNullOrWhiteSpace(parent)) Directory.CreateDirectory(parent);
                File.Copy(source, target, true);
            }
            else
            {
                try { if (File.Exists(target)) File.Delete(target); } catch { }
            }
        }

        private void CaptureLiveSlotBookmark(SlotRecord slot)
        {
            if (slot == null) return;
            int occurrence = _currentOccurrence > 0 ? _currentOccurrence : ReadResumeOccurrence();
            double seconds = Math.Max(0, _timePosition);
            if (_running)
            {
                double observed = GetMpvTimePosition();
                if (observed >= 0) seconds = observed;
            }
            slot.BookmarkOccurrence = occurrence;
            slot.BookmarkSeconds = seconds;
            slot.Paused = _running && _audioActive && _paused;
            if (occurrence > 0)
            {
                string resume = Path.Combine(SlotRootPath(slot.Id), "state", "resume-track.txt");
                Directory.CreateDirectory(Path.GetDirectoryName(resume));
                WriteUtf8NoBom(resume, occurrence.ToString(CultureInfo.InvariantCulture));
            }
            SaveSlotRecord(slot);
            if (String.Equals(slot.Id, _activeSlotId, StringComparison.OrdinalIgnoreCase)) WriteActiveSlotDescriptor(slot);
        }

        private void SnapshotGlobalStateIntoSlot(SlotRecord slot, bool captureLiveBookmark)
        {
            if (slot == null) return;
            string root = SlotRootPath(slot.Id);
            Directory.CreateDirectory(root);
            Directory.CreateDirectory(Path.Combine(root, "state"));
            if (captureLiveBookmark)
            {
                SaveQueueCheckpointsState();
                CaptureLiveSlotBookmark(slot);
            }
            foreach (string relative in SlotSnapshotFiles) CopyGlobalFileToSlot(relative, root);

            if (!captureLiveBookmark && slot.BookmarkOccurrence <= 0)
                slot.BookmarkOccurrence = ReadResumeOccurrence();

            string poolName;
            slot.SourceKind = DetectActiveSlotSourceKind(out poolName);
            slot.PoolName = poolName;
            slot.TrackCount = CountPlaylistEntries(DirectPlaylistPath);
            SaveSlotRecord(slot);
            if (String.Equals(slot.Id, _activeSlotId, StringComparison.OrdinalIgnoreCase)) WriteActiveSlotDescriptor(slot);
        }

        private void RestoreSlotIntoGlobal(SlotRecord slot)
        {
            if (slot == null) throw new InvalidOperationException("Listening slot is unavailable.");
            string root = SlotRootPath(slot.Id);
            if (!Directory.Exists(root)) throw new DirectoryNotFoundException("Listening slot folder is missing: " + slot.Name);
            Directory.CreateDirectory(_stateRoot);
            foreach (string relative in SlotSnapshotFiles) RestoreSlotFileToGlobal(relative, root);
            if (!File.Exists(DirectPlaylistPath)) WriteUtf8NoBom(DirectPlaylistPath, "");
            if (slot.BookmarkOccurrence > 0) WriteUtf8NoBom(Path.Combine(_stateRoot, "resume-track.txt"), slot.BookmarkOccurrence.ToString(CultureInfo.InvariantCulture));

            foreach (string volatileName in new[] { "current.json", "engine-status.json", "queue-runtime.json", "runtime-lease.json", "startup-flight.json", "supervisor-status.txt", "planned-stop.pending", "controller-runtime-owner.json", "supervisor.pid", "engine.pid", "server.pid" })
            {
                try { File.Delete(Path.Combine(_stateRoot, volatileName)); } catch { }
            }
            _jsonCache.Clear();
        }

        private void EnsureListeningSlotFoundation()
        {
            try
            {
                Directory.CreateDirectory(_slotsRoot);
                Directory.CreateDirectory(_stateRoot);
                ReloadSlotRecords();
                RecoverInterruptedSlotSwitch();
                ReloadSlotRecords();
                Dictionary<string, object> activeMap = ReadJsonFresh(ActiveSlotDescriptorPath);
                string requested = NormalizeSlotId(GetString(activeMap, "id", ""));
                SlotRecord active = null;
                if (requested.Length > 0) _slotsById.TryGetValue(requested, out active);

                if (_slotItems.Count == 0)
                {
                    active = new SlotRecord
                    {
                        Id = "default",
                        Name = "Main",
                        SourceKind = "Playlist",
                        CreatedUtc = DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture),
                        LastUsedUtc = DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture)
                    };
                    _activeSlotId = active.Id;
                    _activeSlotName = active.Name;
                    SnapshotGlobalStateIntoSlot(active, false);
                    ReloadSlotRecords();
                    _slotsById.TryGetValue(active.Id, out active);
                }
                if (active == null && _slotItems.Count > 0) active = _slotItems[0];
                if (active == null) return;
                // If the engine had time to checkpoint a newer exact position but the
                // controller was terminated before its 15-second manifest checkpoint,
                // recover that active descriptor instead of throwing the position away.
                if (String.Equals(GetString(activeMap, "id", ""), active.Id, StringComparison.OrdinalIgnoreCase) &&
                    GetInt(activeMap, "engine_updated_unix", 0) > 0)
                {
                    active.BookmarkOccurrence = Math.Max(active.BookmarkOccurrence, GetInt(activeMap, "bookmark_occurrence", active.BookmarkOccurrence));
                    active.BookmarkSeconds = Math.Max(0, GetDouble(activeMap, "bookmark_seconds", active.BookmarkSeconds));
                    active.Paused = GetBool(activeMap, "paused", active.Paused);
                    SaveSlotRecord(active);
                }
                _activeSlotId = active.Id;
                _activeSlotName = active.Name;
                WriteActiveSlotDescriptor(active);
                ReloadSlotRecords();
            }
            catch
            {
                _activeSlotId = "";
                _activeSlotName = "Main";
            }
        }

        private void CheckpointActiveSlotBookmarkIfDue(long now)
        {
            if (!_running || String.IsNullOrWhiteSpace(_activeSlotId)) return;
            if (now - _lastSlotBookmarkCheckpointMs < 15000) return;
            _lastSlotBookmarkCheckpointMs = now;
            SlotRecord slot;
            if (!_slotsById.TryGetValue(_activeSlotId, out slot) || slot == null) return;
            slot.BookmarkOccurrence = _currentOccurrence > 0 ? _currentOccurrence : slot.BookmarkOccurrence;
            slot.BookmarkSeconds = Math.Max(0, _timePosition);
            slot.Paused = _audioActive && _paused;
            QueueSlotBookmarkWrite(slot.Clone());
        }

        private void QueueSlotBookmarkWrite(SlotRecord snapshot)
        {
            if (snapshot == null) return;
            ThreadPool.QueueUserWorkItem(delegate(object ignored)
            {
                try
                {
                    snapshot.Id = NormalizeSlotId(snapshot.Id);
                    snapshot.Name = NormalizeSlotName(snapshot.Name);
                    if (snapshot.Id.Length == 0) return;
                    if (snapshot.Name.Length == 0) snapshot.Name = "Slot";
                    if (String.IsNullOrWhiteSpace(snapshot.CreatedUtc)) snapshot.CreatedUtc = DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture);
                    snapshot.UpdatedUtc = DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture);
                    string root = SlotRootPath(snapshot.Id);
                    Directory.CreateDirectory(root);
                    var serializer = new JavaScriptSerializer();
                    var map = new Dictionary<string, object>
                    {
                        { "schema", 2 }, { "id", snapshot.Id }, { "name", snapshot.Name },
                        { "source_kind", snapshot.SourceKind ?? "Playlist" }, { "pool_name", snapshot.PoolName ?? "" }, { "track_count", snapshot.TrackCount },
                        { "bookmark_occurrence", snapshot.BookmarkOccurrence }, { "bookmark_seconds", Math.Max(0, snapshot.BookmarkSeconds) }, { "paused", snapshot.Paused },
                        { "broadcast_preset", NormalizeSlotBroadcastPreset(snapshot.BroadcastPreset) },
                        { "created_utc", snapshot.CreatedUtc ?? "" }, { "updated_utc", snapshot.UpdatedUtc ?? "" }, { "last_used_utc", snapshot.LastUsedUtc ?? "" }
                    };
                    WriteUtf8NoBom(SlotManifestPath(snapshot.Id), serializer.Serialize(map));
                    var active = new Dictionary<string, object>
                    {
                        { "schema", 2 }, { "id", snapshot.Id ?? "" }, { "name", snapshot.Name ?? "" },
                        { "source_kind", snapshot.SourceKind ?? "Playlist" }, { "pool_name", snapshot.PoolName ?? "" },
                        { "bookmark_occurrence", snapshot.BookmarkOccurrence }, { "bookmark_seconds", Math.Max(0, snapshot.BookmarkSeconds) }, { "paused", snapshot.Paused },
                        { "broadcast_preset", NormalizeSlotBroadcastPreset(snapshot.BroadcastPreset) }, { "updated_utc", snapshot.UpdatedUtc ?? "" }
                    };
                    Directory.CreateDirectory(_dataRoot);
                    WriteUtf8NoBom(ActiveSlotDescriptorPath, serializer.Serialize(active));
                }
                catch (Exception ex) { WriteControllerPerformanceLogAsync("Slot bookmark could not be saved: " + ex.GetType().Name + " " + ex.Message); }
            });
        }

        private void PersistActiveSlotState(bool captureLiveBookmark)
        {
            if (String.IsNullOrWhiteSpace(_activeSlotId)) return;
            SlotRecord slot;
            if (!_slotsById.TryGetValue(_activeSlotId, out slot) || slot == null) slot = ReadSlotRecord(_activeSlotId);
            if (slot == null) return;
            SnapshotGlobalStateIntoSlot(slot, captureLiveBookmark);
            _activeSlotName = slot.Name;
        }

        private void MarkActiveSlotSourceChanged(string kind)
        {
            SlotRecord slot;
            if (!_slotsById.TryGetValue(_activeSlotId ?? "", out slot) || slot == null) return;
            string poolName;
            string detected = DetectActiveSlotSourceKind(out poolName);
            slot.SourceKind = String.IsNullOrWhiteSpace(kind) ? detected : kind;
            slot.PoolName = String.Equals(slot.SourceKind, "Pool", StringComparison.OrdinalIgnoreCase) ? poolName : "";
            slot.TrackCount = CountPlaylistEntries(DirectPlaylistPath);
            try { SnapshotGlobalStateIntoSlot(slot, false); } catch { }
            ReloadSlotRecords();
        }

        private bool ActiveSlotHasPlayableSource()
        {
            return CountPlaylistEntries(DirectPlaylistPath) > 0;
        }

        private void ResetControllerProjectionForSlotSwitch()
        {
            StopPreviewProcesses();
            _order.Clear(); _orderIndexByOccurrence.Clear(); _queueRows.Clear(); _queueByOccurrence.Clear(); _runtimeQueue.Clear(); _trackMeta.Clear();
            _queueUiMaterialized = false; _queueUiOrderDirty = true; _queueUiMaterializationActive = false; _queueUiMaterializationGeneration++;
            _queueUiMaterializationRemaining = 0; _queueUiDeferredDirtyOccurrences.Clear(); _queueUiRestoreSelectedOccurrences.Clear(); _queueUiPendingSelectOccurrence = 0; _queueUiPendingSelectRelaxFilters = false;
            _queueHorizonTemporalRows.Clear();
            _metadataPrefetchQueue.Clear(); _metadataUrgentQueue.Clear(); _metadataPrefetchPending.Clear(); _metadataPrefetchRetryAfterMs.Clear();
            _currentOccurrence = 0; _currentSlot = 0; _sessionId = ""; _orderRevision = -1; _orderCommandSerial = 0;
            _duration = 0; _timePosition = 0; _lastMediaOccurrence = 0; _pendingTransportOutgoingMediaOccurrence = 0; _lastQueueFollowOccurrence = 0;
            _running = false; _audioActive = false; _paused = false; _lastPlaybackPhase = "stopped";
            _startupPrewarmReady = false;
            _engineLaunchRequestedMs = -10000; _engineLaunchMonitorActive = false; _engineLaunchGeneration++;
            LoadQueueCheckpoints();
        }

        private void SwitchListeningSlot(string targetId, string origin)
        {
            string id = NormalizeSlotId(targetId);
            if (id.Length == 0 || _slotSwitchActive) return;
            if ((_settingsOverlay != null && _settingsOverlay.Visibility == Visibility.Visible) ||
                (_poolOverlay != null && _poolOverlay.Visibility == Visibility.Visible) ||
                (_playlistEditorOverlay != null && _playlistEditorOverlay.Visibility == Visibility.Visible))
            {
                ShowToast("Listening slot", "Finish or close the open editor first so its draft stays attached to the right slot.");
                ReloadSlotRecords();
                return;
            }
            if (String.Equals(id, _activeSlotId, StringComparison.OrdinalIgnoreCase))
            {
                ReloadSlotRecords();
                return;
            }
            SlotRecord target;
            if (!_slotsById.TryGetValue(id, out target) || target == null)
            {
                ShowToast("Listening slot", "That slot is no longer available.");
                ReloadSlotRecords();
                return;
            }
            SlotRecord current;
            _slotsById.TryGetValue(_activeSlotId ?? "", out current);
            if (current == null)
            {
                ShowToast("Listening slot", "The current slot state could not be verified, so YOMI did not switch.");
                ReloadSlotRecords();
                return;
            }
            bool wasRunning = _running || _engineLaunchMonitorActive ||
                IsPidFileLive(Path.Combine(_stateRoot, "supervisor.pid")) ||
                IsPidFileLive(Path.Combine(_stateRoot, "engine.pid"));
            bool switchJournalWritten = false;
            _slotSwitchActive = true;
            UpdateSlotSwitchUi();
            try
            {
                FinalizeListeningVisit(true, true);
                // Capture the exact user-facing bookmark while mpv is still reachable, then
                // stop playback before copying session/order/history files so the snapshot
                // cannot race active writers.
                CaptureLiveSlotBookmark(current);
                if (wasRunning && !StopOwnedYomiRuntime())
                    throw new InvalidOperationException("The current playback runtime could not be stopped safely, so YOMI kept the current slot active.");
                SnapshotGlobalStateIntoSlot(current, false);

                // From this point forward a crash must be recoverable. Startup treats an
                // undeleted journal as an uncommitted switch and restores from_id.
                WriteSlotSwitchJournal(current, target);
                switchJournalWritten = true;
                try { File.Delete(Path.Combine(_stateRoot, "planned-stop.pending")); } catch { }
                RestoreSlotIntoGlobal(target);
                target.LastUsedUtc = DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture);
                SaveSlotRecord(target);
                _activeSlotId = target.Id;
                _activeSlotName = target.Name;
                WriteActiveSlotDescriptor(target);
                ClearSlotSwitchJournal();
                switchJournalWritten = false;
                ResetControllerProjectionForSlotSwitch();
                ReloadSlotRecords();
                SafeRefresh(true);

                string broadcastNote;
                TryApplySlotBroadcastAffinity(target, out broadcastNote);
                string obsNote = String.IsNullOrWhiteSpace(broadcastNote)
                    ? "OBS stays on the same YOMI output."
                    : "OBS URL unchanged. " + broadcastNote;

                if (wasRunning && ActiveSlotHasPlayableSource())
                {
                    var restart = new DispatcherTimer { Interval = TimeSpan.FromMilliseconds(650) };
                    restart.Tick += delegate
                    {
                        restart.Stop();
                        StartEngine();
                        ShowToast("Listening slot", "Switched to " + target.Name + ". " + obsNote);
                    };
                    restart.Start();
                }
                else if (wasRunning)
                {
                    ShowToast("Listening slot", target.Name + " is empty. " + obsNote + " Add a playlist or Pool, then press Play.");
                }
                else
                {
                    ShowToast("Listening slot", "Switched to " + target.Name + ". " + obsNote);
                }
                AddActivity("Listening slot", "switched to " + target.Name + " | " + (origin ?? "ui"));
            }
            catch (Exception ex)
            {
                bool rollbackComplete = false;
                try
                {
                    RestoreSlotIntoGlobal(current);
                    _activeSlotId = current.Id;
                    _activeSlotName = current.Name;
                    WriteActiveSlotDescriptor(current);
                    ResetControllerProjectionForSlotSwitch();
                    rollbackComplete = true;
                    if (wasRunning && ActiveSlotHasPlayableSource())
                    {
                        var rollbackRestart = new DispatcherTimer { Interval = TimeSpan.FromMilliseconds(650) };
                        rollbackRestart.Tick += delegate { rollbackRestart.Stop(); StartEngine(); };
                        rollbackRestart.Start();
                    }
                }
                catch { }
                // If rollback itself failed, deliberately leave the journal behind. The next
                // controller startup gets another deterministic chance to restore from_id.
                if (rollbackComplete && switchJournalWritten) ClearSlotSwitchJournal();
                ShowToast("Slot switch stopped", ex.Message);
            }
            finally
            {
                _slotSwitchActive = false;
                ReloadSlotRecords();
                UpdateSlotSwitchUi();
            }
        }

        private void WireListeningSlots()
        {
            if (_slotSelector == null || _slotsOverlay == null) return;
            _slotSelector.ItemsSource = _slotItems;
            _slotsList.ItemsSource = _slotItems;
            FillCombo(_slotBroadcastPresetCombo, "Keep current", "Classic strip", "Split sources", "Text + artwork", "Visual focus");
            _slotBroadcastFollowCheck.IsChecked = _slotBroadcastFollowEnabled;
            _slotBroadcastFollowCheck.Checked += delegate
            {
                if (_slotUiSyncing) return;
                _slotBroadcastFollowEnabled = true; SaveUiState();
                _slotsStatusText.Text = "Layout following enabled. A slot's preferred layout applies when that slot becomes active; the OBS URL does not change.";
                UpdateSlotSwitchUi();
            };
            _slotBroadcastFollowCheck.Unchecked += delegate
            {
                if (_slotUiSyncing) return;
                _slotBroadcastFollowEnabled = false; SaveUiState();
                _slotsStatusText.Text = "Layout following disabled. Slot switching changes music only.";
                UpdateSlotSwitchUi();
            };
            _slotBroadcastPresetCombo.SelectionChanged += delegate
            {
                if (_slotUiSyncing || _slotSwitchActive) return;
                SlotRecord selected = _slotsList.SelectedItem as SlotRecord;
                if (selected == null) return;
                selected.BroadcastPreset = NormalizeSlotBroadcastPreset(Convert.ToString(_slotBroadcastPresetCombo.SelectedItem, CultureInfo.InvariantCulture));
                try
                {
                    SaveSlotRecord(selected);
                    string keep = selected.Id; ReloadSlotRecords(); SlotRecord loaded; if (_slotsById.TryGetValue(keep, out loaded)) _slotsList.SelectedItem = loaded;
                    _slotsStatusText.Text = String.Equals(selected.BroadcastPreset, "Keep current", StringComparison.OrdinalIgnoreCase)
                        ? "This slot will keep whatever broadcast layout is already active."
                        : "Preferred layout saved. It applies when this slot becomes active if layout following is enabled.";
                }
                catch (Exception ex) { _slotsStatusText.Text = "Could not save layout preference: " + ex.Message; }
            };
            _slotSelector.SelectionChanged += delegate
            {
                if (_slotUiSyncing || _slotSwitchActive) return;
                SlotRecord selected = _slotSelector.SelectedItem as SlotRecord;
                if (selected != null && !String.Equals(selected.Id, _activeSlotId, StringComparison.OrdinalIgnoreCase)) SwitchListeningSlot(selected.Id, "selector");
            };
            _slotsManageButton.Click += delegate { OpenListeningSlots(); };
            _slotsCloseButton.Click += delegate { if (!_slotSwitchActive) CloseListeningSlots(); };
            _slotSwitchButton.Click += delegate
            {
                SlotRecord selected = _slotsList.SelectedItem as SlotRecord;
                if (selected != null) SwitchListeningSlot(selected.Id, "manager");
            };
            _slotNewButton.Click += delegate { CreateBlankListeningSlot(); };
            _slotDuplicateButton.Click += delegate { DuplicateSelectedListeningSlot(); };
            _slotRenameButton.Click += delegate { RenameSelectedListeningSlot(); };
            _slotDeleteButton.Click += delegate { DeleteSelectedListeningSlot(); };
            _slotEditPlaylistButton.Click += delegate
            {
                SlotRecord selected = _slotsList.SelectedItem as SlotRecord;
                if (selected == null || !String.Equals(selected.Id, _activeSlotId, StringComparison.OrdinalIgnoreCase)) return;
                CloseListeningSlots(); OpenPlaylistEditor();
            };
            _slotPoolButton.Click += delegate
            {
                SlotRecord selected = _slotsList.SelectedItem as SlotRecord;
                if (selected == null || !String.Equals(selected.Id, _activeSlotId, StringComparison.OrdinalIgnoreCase)) return;
                CloseListeningSlots(); OpenPlaylistPool();
            };
            _slotsList.SelectionChanged += delegate
            {
                if (_slotUiSyncing) return;
                UpdateSlotManagerSelection();
            };
            _slotNameBox.KeyDown += delegate(object sender, KeyEventArgs e)
            {
                if (e.Key == Key.Enter) { RenameSelectedListeningSlot(); e.Handled = true; }
            };
            _slotsOverlay.PreviewMouseDown += delegate(object sender, MouseButtonEventArgs e)
            {
                if (_slotSwitchActive || IsVisualDescendantOf(e.OriginalSource as DependencyObject, _slotsCard)) return;
                CloseListeningSlots();
            };
            ReloadSlotRecords();
        }

        private bool PrepareAuthoringSurface(AuthoringSurfaceKind target, string label)
        {
            bool settingsOpen = _settingsOverlay != null && _settingsOverlay.Visibility == Visibility.Visible;
            bool slotsOpen = _slotsOverlay != null && _slotsOverlay.Visibility == Visibility.Visible;
            bool poolOpen = _poolOverlay != null && _poolOverlay.Visibility == Visibility.Visible;
            bool editorOpen = _playlistEditorOverlay != null && _playlistEditorOverlay.Visibility == Visibility.Visible;

            if (target != AuthoringSurfaceKind.Settings && settingsOpen)
            {
                ShowToast(label, "Close Settings first so its unsaved draft stays explicit.");
                return false;
            }
            if (target != AuthoringSurfaceKind.PlaylistPool && poolOpen)
            {
                ShowToast(label, "Close Playlist Pool first so one source editor owns the draft.");
                return false;
            }
            if (target != AuthoringSurfaceKind.PlaylistEditor && editorOpen)
            {
                ShowToast(label, "Close the playlist editor first so one source editor owns the draft.");
                return false;
            }
            if (target == AuthoringSurfaceKind.Settings && (poolOpen || editorOpen))
            {
                ShowToast(label, "Finish or close the active source draft first.");
                return false;
            }
            if (target != AuthoringSurfaceKind.ListeningSlots && slotsOpen) CloseListeningSlots();

            if (_commandPaletteOverlay != null && _commandPaletteOverlay.Visibility == Visibility.Visible) CloseCommandPalette();
            if (_operatorDeckOverlay != null && _operatorDeckOverlay.Visibility == Visibility.Visible) CloseOperatorDeck();
            if (_intentFabricOverlay != null && _intentFabricOverlay.Visibility == Visibility.Visible) CloseIntentFabric();
            if (_volumePopup != null) _volumePopup.IsOpen = false;
            return true;
        }

        private void OpenListeningSlots()
        {
            if (_slotsOverlay == null) return;
            if (_slotsOverlay.Visibility == Visibility.Visible)
            {
                _window.Activate();
                if (_slotsList != null) _slotsList.Focus();
                return;
            }
            if (!PrepareAuthoringSurface(AuthoringSurfaceKind.ListeningSlots, "Listening slots")) return;
            _slotsReturnFocus = Keyboard.FocusedElement;
            if (_miniMode || (!_queueOpen && _window.WindowState == WindowState.Normal && _window.ActualHeight <= CompactControllerMaxHeight + 60.0)) ExpandCompactHostForOverlay();
            PersistActiveSlotState(false);
            ReloadSlotRecords();
            _slotsOverlay.Visibility = Visibility.Visible;
            _slotsOverlay.IsHitTestVisible = true;
            SyncHostedMediaAirspace();
            SlotRecord active;
            if (_slotsById.TryGetValue(_activeSlotId ?? "", out active)) _slotsList.SelectedItem = active;
            UpdateSlotManagerSelection();
            _slotsList.Focus();
        }

        private void CloseListeningSlots()
        {
            if (_slotsOverlay == null || _slotSwitchActive) return;
            _slotsOverlay.Visibility = Visibility.Collapsed;
            SyncHostedMediaAirspace();
            RestoreCompactHostAfterOverlay();
            IInputElement restore = _slotsReturnFocus;
            _slotsReturnFocus = null;
            RestoreKeyboardFocus(restore);
        }

        private void UpdateSlotManagerSelection()
        {
            if (_slotsList == null || _slotDetailText == null) return;
            SlotRecord selected = _slotsList.SelectedItem as SlotRecord;
            bool has = selected != null;
            bool active = has && String.Equals(selected.Id, _activeSlotId, StringComparison.OrdinalIgnoreCase);
            _slotUiSyncing = true;
            try
            {
                if (_slotNameBox != null) _slotNameBox.Text = has ? selected.Name : "";
                if (_slotBroadcastFollowCheck != null) _slotBroadcastFollowCheck.IsChecked = _slotBroadcastFollowEnabled;
                if (_slotBroadcastPresetCombo != null) SetComboPreserve(_slotBroadcastPresetCombo, has ? NormalizeSlotBroadcastPreset(selected.BroadcastPreset) : "Keep current");
            }
            finally { _slotUiSyncing = false; }
            if (!has)
            {
                _slotDetailText.Text = "Select a slot.";
            }
            else
            {
                string source = String.IsNullOrWhiteSpace(selected.SourceKind) ? "Playlist" : selected.SourceKind;
                if (String.Equals(source, "Pool", StringComparison.OrdinalIgnoreCase) && !String.IsNullOrWhiteSpace(selected.PoolName)) source += " | " + selected.PoolName;
                string bookmark = selected.BookmarkOccurrence > 0
                    ? "item " + selected.BookmarkOccurrence.ToString(CultureInfo.InvariantCulture) + (selected.BookmarkSeconds > 0.5 ? " at " + FormatTime(selected.BookmarkSeconds) : "")
                    : "no bookmark yet";
                string lastUsed = "";
                DateTime parsedLast;
                if (DateTime.TryParse(selected.LastUsedUtc, CultureInfo.InvariantCulture, DateTimeStyles.RoundtripKind, out parsedLast))
                    lastUsed = " | last used " + parsedLast.ToLocalTime().ToString("g", CultureInfo.CurrentCulture);
                _slotDetailText.Text = (active ? "CURRENT | " : "") + source + " | " + selected.TrackCount.ToString("N0", CultureInfo.InvariantCulture) + " tracks | " + bookmark + (selected.Paused ? " | paused" : "") + lastUsed;
            }
            UpdateSlotSwitchUi();
        }

        private void UpdateSlotSwitchUi()
        {
            SlotRecord selected = _slotsList != null ? _slotsList.SelectedItem as SlotRecord : null;
            bool has = selected != null;
            bool active = has && String.Equals(selected.Id, _activeSlotId, StringComparison.OrdinalIgnoreCase);
            if (_slotSwitchButton != null) { _slotSwitchButton.IsEnabled = has && !active && !_slotSwitchActive; _slotSwitchButton.Content = _slotSwitchActive ? "Switching..." : "Switch"; }
            if (_slotNewButton != null) _slotNewButton.IsEnabled = !_slotSwitchActive;
            if (_slotDuplicateButton != null) _slotDuplicateButton.IsEnabled = has && !_slotSwitchActive;
            if (_slotRenameButton != null) _slotRenameButton.IsEnabled = has && !_slotSwitchActive;
            if (_slotDeleteButton != null) _slotDeleteButton.IsEnabled = has && !active && _slotItems.Count > 1 && !_slotSwitchActive;
            if (_slotEditPlaylistButton != null) _slotEditPlaylistButton.IsEnabled = active && !_slotSwitchActive;
            if (_slotPoolButton != null) _slotPoolButton.IsEnabled = active && !_slotSwitchActive;
            if (_slotSelector != null) _slotSelector.IsEnabled = !_slotSwitchActive;
            if (_slotsManageButton != null) _slotsManageButton.IsEnabled = !_slotSwitchActive;
            if (_slotBroadcastFollowCheck != null) _slotBroadcastFollowCheck.IsEnabled = !_slotSwitchActive;
            if (_slotBroadcastPresetCombo != null) _slotBroadcastPresetCombo.IsEnabled = has && !_slotSwitchActive;
            if (_slotsStatusText != null && _slotSwitchActive) _slotsStatusText.Text = "Saving your place and switching...";
            else if (_slotsStatusText != null) _slotsStatusText.Text = "Your place is saved before switching. Ctrl+Alt+1-9 jumps between slots. OBS keeps using the same YOMI overlay URL.";
        }

        private void CreateBlankListeningSlot()
        {
            string requested = _slotNameBox != null ? _slotNameBox.Text : "";
            string name = UniqueSlotName(String.IsNullOrWhiteSpace(requested) ? "New slot" : requested);
            SlotRecord slot = new SlotRecord
            {
                Id = NewSlotId(), Name = name, SourceKind = "Empty", TrackCount = 0,
                CreatedUtc = DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture), UpdatedUtc = DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture)
            };
            try
            {
                string root = SlotRootPath(slot.Id);
                Directory.CreateDirectory(Path.Combine(root, "state"));
                WriteUtf8NoBom(Path.Combine(root, "playlist.txt"), "");
                WriteUtf8NoBom(Path.Combine(root, "state", "repeat-mode.txt"), "all");
                WriteUtf8NoBom(Path.Combine(root, "state", "resume-track.txt"), "1");
                SaveSlotRecord(slot);
                ReloadSlotRecords();
                SlotRecord loaded; if (_slotsById.TryGetValue(slot.Id, out loaded)) _slotsList.SelectedItem = loaded;
                _slotsStatusText.Text = "Blank slot created. Switch to it, then add a playlist or Pool.";
            }
            catch (Exception ex) { _slotsStatusText.Text = "Could not create slot: " + ex.Message; }
        }

        private void CopyDirectoryPayload(string sourceRoot, string targetRoot)
        {
            Directory.CreateDirectory(targetRoot);
            foreach (string directory in Directory.GetDirectories(sourceRoot, "*", SearchOption.AllDirectories))
            {
                string relative = directory.Substring(sourceRoot.Length).TrimStart(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
                Directory.CreateDirectory(Path.Combine(targetRoot, relative));
            }
            foreach (string file in Directory.GetFiles(sourceRoot, "*", SearchOption.AllDirectories))
            {
                if (String.Equals(Path.GetFileName(file), "slot.json", StringComparison.OrdinalIgnoreCase)) continue;
                string relative = file.Substring(sourceRoot.Length).TrimStart(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
                string target = Path.Combine(targetRoot, relative);
                string parent = Path.GetDirectoryName(target); if (!String.IsNullOrWhiteSpace(parent)) Directory.CreateDirectory(parent);
                File.Copy(file, target, true);
            }
        }

        private void DuplicateSelectedListeningSlot()
        {
            SlotRecord selected = _slotsList != null ? _slotsList.SelectedItem as SlotRecord : null;
            if (selected == null) return;
            if (String.Equals(selected.Id, _activeSlotId, StringComparison.OrdinalIgnoreCase)) PersistActiveSlotState(true);
            selected = ReadSlotRecord(selected.Id) ?? selected;
            string requested = _slotNameBox != null ? _slotNameBox.Text : "";
            string name = UniqueSlotName(String.IsNullOrWhiteSpace(requested) || String.Equals(requested, selected.Name, StringComparison.OrdinalIgnoreCase) ? selected.Name + " copy" : requested);
            SlotRecord copy = selected.Clone();
            copy.Id = NewSlotId(); copy.Name = name; copy.CreatedUtc = DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture); copy.LastUsedUtc = "";
            try
            {
                CopyDirectoryPayload(SlotRootPath(selected.Id), SlotRootPath(copy.Id));
                SaveSlotRecord(copy);
                ReloadSlotRecords();
                SlotRecord loaded; if (_slotsById.TryGetValue(copy.Id, out loaded)) _slotsList.SelectedItem = loaded;
                _slotsStatusText.Text = "Duplicated " + selected.Name + ". The copy has independent session state but uses the same shared YOMI cache.";
            }
            catch (Exception ex) { _slotsStatusText.Text = "Could not duplicate slot: " + ex.Message; }
        }

        private void RenameSelectedListeningSlot()
        {
            if (_slotUiSyncing) return;
            SlotRecord selected = _slotsList != null ? _slotsList.SelectedItem as SlotRecord : null;
            if (selected == null) return;
            string name = NormalizeSlotName(_slotNameBox != null ? _slotNameBox.Text : "");
            if (name.Length == 0) { _slotsStatusText.Text = "Give the slot a name first."; return; }
            SlotRecord collision = _slotItems.FirstOrDefault(x => !String.Equals(x.Id, selected.Id, StringComparison.OrdinalIgnoreCase) && String.Equals(x.Name, name, StringComparison.OrdinalIgnoreCase));
            if (collision != null) { _slotsStatusText.Text = "Another slot already uses that name."; return; }
            selected.Name = name;
            try
            {
                SaveSlotRecord(selected);
                if (String.Equals(selected.Id, _activeSlotId, StringComparison.OrdinalIgnoreCase)) { _activeSlotName = selected.Name; WriteActiveSlotDescriptor(selected); }
                string keep = selected.Id; ReloadSlotRecords(); SlotRecord loaded; if (_slotsById.TryGetValue(keep, out loaded)) _slotsList.SelectedItem = loaded;
                _slotsStatusText.Text = "Slot renamed.";
            }
            catch (Exception ex) { _slotsStatusText.Text = "Could not rename slot: " + ex.Message; }
        }

        private void DeleteSelectedListeningSlot()
        {
            SlotRecord selected = _slotsList != null ? _slotsList.SelectedItem as SlotRecord : null;
            if (selected == null || String.Equals(selected.Id, _activeSlotId, StringComparison.OrdinalIgnoreCase) || _slotItems.Count <= 1) return;
            MessageBoxResult answer = MessageBox.Show(_window,
                "Delete listening slot '" + selected.Name + "'?\r\n\r\nIts playlist/Pool definition and saved session/bookmark are removed. Shared media cache, favorites and other slots are untouched.",
                "Delete listening slot", MessageBoxButton.YesNo, MessageBoxImage.Warning);
            if (answer != MessageBoxResult.Yes) return;
            try
            {
                Directory.Delete(SlotRootPath(selected.Id), true);
                ReloadSlotRecords();
                _slotsStatusText.Text = "Slot deleted.";
            }
            catch (Exception ex) { _slotsStatusText.Text = "Could not delete slot: " + ex.Message; }
        }

        private string DirectPlaylistPath { get { return Path.Combine(_dataRoot, "playlist.txt"); } }

        private void EditPlaylistFile()
        {
            OpenPlaylistEditor();
        }

        private void WirePlaylistEditor()
        {
            if (_playlistEditorOverlay == null) return;
            _playlistEditorCloseButton.Click += delegate { ClosePlaylistEditor(); };
            _playlistEditorSaveButton.Click += delegate { SavePlaylistEditor(); };
            _playlistEditorBox.TextChanged += delegate
            {
                if (_playlistEditorLoading) return;
                bool dirty = !String.Equals(_playlistEditorBox.Text ?? "", _playlistEditorBaseline ?? "", StringComparison.Ordinal);
                _playlistEditorSaveButton.IsEnabled = dirty;
                _playlistEditorStatusText.Text = dirty ? "Unsaved changes." : "No changes.";
            };
            _playlistEditorOverlay.PreviewKeyDown += delegate(object sender, KeyEventArgs e)
            {
                bool ctrl = (e.KeyboardDevice.Modifiers & ModifierKeys.Control) == ModifierKeys.Control;
                if (ctrl && e.Key == Key.S) { SavePlaylistEditor(); e.Handled = true; return; }
                if (e.Key == Key.Escape) { ClosePlaylistEditor(); e.Handled = true; }
            };
            _playlistEditorOverlay.PreviewMouseDown += delegate(object sender, MouseButtonEventArgs e)
            {
                if (IsVisualDescendantOf(e.OriginalSource as DependencyObject, _playlistEditorCard)) return;
                bool dirty = !String.Equals(_playlistEditorBox.Text ?? "", _playlistEditorBaseline ?? "", StringComparison.Ordinal);
                if (dirty)
                {
                    _playlistEditorStatusText.Text = "Unsaved changes - Save or Cancel.";
                    return;
                }
                ClosePlaylistEditor();
            };
        }

        private void OpenPlaylistEditor()
        {
            if (_playlistEditorOverlay == null) return;
            // Reopening a live editor must never reload playlist.txt over an unsaved draft.
            if (_playlistEditorOverlay.Visibility == Visibility.Visible)
            {
                _window.Activate();
                if (_playlistEditorBox != null) _playlistEditorBox.Focus();
                return;
            }
            if (!PrepareAuthoringSurface(AuthoringSurfaceKind.PlaylistEditor, "Playlist")) return;

            _playlistEditorReturnFocus = Keyboard.FocusedElement;
            if (_miniMode || (!_queueOpen && _window.WindowState == WindowState.Normal && _window.ActualHeight <= CompactControllerMaxHeight + 60.0)) ExpandCompactHostForOverlay();
            string text = "";
            try
            {
                Directory.CreateDirectory(_dataRoot);
                if (!File.Exists(DirectPlaylistPath)) WriteUtf8NoBom(DirectPlaylistPath, "");
                text = ReadTextShared(DirectPlaylistPath);
            }
            catch { }

            _playlistEditorLoading = true;
            try
            {
                _playlistEditorBox.Text = (text ?? "").Replace("\r\n", "\n").Replace("\r", "\n").Replace("\n", Environment.NewLine);
                _playlistEditorBaseline = _playlistEditorBox.Text ?? "";
                _playlistEditorSaveButton.IsEnabled = false;
                _playlistEditorStatusText.Text = _running
                    ? "Changes apply the next time playback starts."
                    : "Changes apply when playback starts.";
            }
            finally { _playlistEditorLoading = false; }

            _playlistEditorOverlay.Visibility = Visibility.Visible;
            _playlistEditorOverlay.IsHitTestVisible = true;
            SyncHostedMediaAirspace();
            _playlistEditorBox.CaretIndex = 0;
            _playlistEditorBox.ScrollToHome();
            _playlistEditorBox.Focus();
            AddActivity("Playlist", "editor opened");
        }

        private void SavePlaylistEditor()
        {
            if (_playlistEditorOverlay == null || _playlistEditorOverlay.Visibility != Visibility.Visible) return;
            string text = _playlistEditorBox.Text ?? "";
            try
            {
                Directory.CreateDirectory(_dataRoot);
                WriteUtf8NoBom(DirectPlaylistPath, text);
                // Editing the active list directly makes this slot a direct-playlist source.
                // Saved Pool definitions remain reusable globally, but stale active Pool provenance
                // must not keep claiming ownership of a hand-edited list.
                try { File.Delete(CurrentPoolPath); } catch { }
                try { File.Delete(PoolSourcesPath); } catch { }
                try { File.Delete(PoolResetPath); } catch { }
                MarkActiveSlotSourceChanged("Playlist");
                _playlistEditorBaseline = text;
                _playlistEditorSaveButton.IsEnabled = false;
                int entries = text.Replace("\r", "").Split('\n').Count(line => !String.IsNullOrWhiteSpace(line));
                _playlistEditorStatusText.Text = "Saved " + entries.ToString("N0", CultureInfo.InvariantCulture) + " entries. " + (_running ? "Restart playback to use the changes." : "They will be used when playback starts.");
                AddActivity("Playlist", "saved in YOMI");
                ShowToast("Playlist saved", entries.ToString("N0", CultureInfo.InvariantCulture) + " entries");
            }
            catch (Exception ex)
            {
                _playlistEditorStatusText.Text = "Could not save: " + ex.Message;
            }
        }

        private void ClosePlaylistEditor()
        {
            if (_playlistEditorOverlay == null || _playlistEditorOverlay.Visibility != Visibility.Visible) return;
            _playlistEditorOverlay.Visibility = Visibility.Collapsed;
            SyncHostedMediaAirspace();
            RestoreCompactHostAfterOverlay();
            IInputElement restore = _playlistEditorReturnFocus;
            _playlistEditorReturnFocus = null;
            RestoreKeyboardFocus(restore);
        }

        private string CurrentPoolPath { get { return Path.Combine(_dataRoot, "pool-current.json"); } }
        private string PoolSourcesPath { get { return Path.Combine(_dataRoot, "pool-sources.txt"); } }
        private string PoolResetPath { get { return Path.Combine(_stateRoot, "pool-reset.pending"); } }
        private string SavedPoolsDirectory { get { return Path.Combine(_dataRoot, "pools"); } }

        private void WirePlaylistPool()
        {
            if (_poolOverlay == null) return;
            if (_poolShuffleModeCombo != null)
            {
                _poolShuffleModeCombo.Items.Clear();
                _poolShuffleModeCombo.Items.Add("Global random");
                _poolShuffleModeCombo.Items.Add("Balanced sources");
                _poolShuffleModeCombo.SelectedIndex = 0;
            }
            _poolCloseButton.Click += delegate { if (!_poolBuildActive) ClosePlaylistPool(); };
            _poolBuildButton.Click += delegate { BuildPlaylistPool(); };
            if (_poolSaveButton != null) _poolSaveButton.Click += delegate { SavePlaylistPoolDefinition(); };
            if (_poolLoadButton != null) _poolLoadButton.Click += delegate { LoadSelectedPlaylistPoolDefinition(); };
            if (_poolDeleteButton != null) _poolDeleteButton.Click += delegate { DeleteSelectedPlaylistPoolDefinition(); };
            if (_poolDiscoverButton != null) _poolDiscoverButton.Click += delegate { BeginPlaylistDiscovery(); };
            if (_poolDiscoverAddButton != null) _poolDiscoverAddButton.Click += delegate { AddSelectedDiscoveredPlaylists(); };
            if (_poolDiscoverList != null) _poolDiscoverList.SelectionChanged += delegate { if (_poolDiscoverAddButton != null) _poolDiscoverAddButton.IsEnabled = _poolDiscoverList.SelectedItems.Count > 0; };
            if (_poolDiscoverQueryBox != null) _poolDiscoverQueryBox.KeyDown += delegate(object sender, KeyEventArgs e) { if (e.Key == Key.Enter) { BeginPlaylistDiscovery(); e.Handled = true; } };
            _poolOverlay.PreviewKeyDown += delegate(object sender, KeyEventArgs e)
            {
                if (e.Key == Key.Escape && !_poolBuildActive) { ClosePlaylistPool(); e.Handled = true; }
            };
            _poolOverlay.PreviewMouseDown += delegate(object sender, MouseButtonEventArgs e)
            {
                if (_poolBuildActive || IsVisualDescendantOf(e.OriginalSource as DependencyObject, _poolCard)) return;
                ClosePlaylistPool();
            };
        }

        private static string PlaylistDiscoveryUrl(string query)
        {
            return "https://www.youtube.com/results?search_query=" + Uri.EscapeDataString(query ?? "") + "&sp=EgIQAw%253D%253D";
        }

        private static string DiscoveredPlaylistUrl(Dictionary<string, object> entry)
        {
            if (entry == null) return "";
            string raw = GetString(entry, "webpage_url", GetString(entry, "url", "")).Trim();
            string id = GetString(entry, "id", "").Trim();
            if (raw.StartsWith("http://", StringComparison.OrdinalIgnoreCase) || raw.StartsWith("https://", StringComparison.OrdinalIgnoreCase))
            {
                if (raw.IndexOf("list=", StringComparison.OrdinalIgnoreCase) >= 0) return raw;
                if (id.Length > 0 && (GetString(entry, "ie_key", "").IndexOf("Tab", StringComparison.OrdinalIgnoreCase) >= 0 || GetString(entry, "_type", "").IndexOf("url", StringComparison.OrdinalIgnoreCase) >= 0))
                    return "https://www.youtube.com/playlist?list=" + Uri.EscapeDataString(id);
                return raw;
            }
            if (id.Length > 0) return "https://www.youtube.com/playlist?list=" + Uri.EscapeDataString(id);
            return "";
        }

        private void BeginPlaylistDiscovery()
        {
            if (_poolDiscoverQueryBox == null || _poolDiscoverList == null) return;
            string query = (_poolDiscoverQueryBox.Text ?? "").Trim();
            if (query.Length == 0)
            {
                if (_poolDiscoverStatusText != null) _poolDiscoverStatusText.Text = "Type something to explore.";
                _poolDiscoverQueryBox.Focus();
                return;
            }
            string yt = Path.Combine(_runtimeRoot, "yt-dlp", "yt-dlp.exe");
            if (!File.Exists(yt))
            {
                if (_poolDiscoverStatusText != null) _poolDiscoverStatusText.Text = "yt-dlp is missing from the YOMI runtime.";
                return;
            }
            int generation = Interlocked.Increment(ref _poolDiscoveryGeneration);
            _poolDiscoverList.ItemsSource = null;
            _poolDiscoverList.Items.Clear();
            if (_poolDiscoverButton != null) { _poolDiscoverButton.IsEnabled = false; _poolDiscoverButton.Content = "Searching…"; }
            if (_poolDiscoverAddButton != null) _poolDiscoverAddButton.IsEnabled = false;
            if (_poolDiscoverStatusText != null) _poolDiscoverStatusText.Text = "Searching playlists…";
            string searchUrl = PlaylistDiscoveryUrl(query);
            ThreadPool.QueueUserWorkItem(delegate
            {
                var results = new List<PoolDiscoveryItem>();
                string failure = "";
                try
                {
                    string deno = Path.Combine(_runtimeRoot, "deno", "deno.exe");
                    string args = "--flat-playlist --playlist-end 18 --ignore-errors --quiet --no-warnings --dump-json";
                    if (File.Exists(deno)) args += " --js-runtimes " + Quote("deno:" + deno);
                    args += " " + Quote(searchUrl);
                    var lines = new List<string>();
                    var errors = new List<string>();
                    var psi = new ProcessStartInfo
                    {
                        FileName = yt,
                        Arguments = args,
                        WorkingDirectory = _dataRoot,
                        UseShellExecute = false,
                        CreateNoWindow = true,
                        WindowStyle = ProcessWindowStyle.Hidden,
                        RedirectStandardOutput = true,
                        RedirectStandardError = true
                    };
                    using (var proc = new Process { StartInfo = psi })
                    {
                        proc.OutputDataReceived += delegate(object sender, DataReceivedEventArgs e) { if (!String.IsNullOrWhiteSpace(e.Data)) lock (lines) lines.Add(e.Data); };
                        proc.ErrorDataReceived += delegate(object sender, DataReceivedEventArgs e) { if (!String.IsNullOrWhiteSpace(e.Data)) lock (errors) errors.Add(e.Data); };
                        if (!proc.Start()) throw new InvalidOperationException("Windows could not start yt-dlp.");
                        try { proc.PriorityClass = ProcessPriorityClass.BelowNormal; } catch { }
                        proc.BeginOutputReadLine(); proc.BeginErrorReadLine();
                        if (!proc.WaitForExit(60000)) { try { proc.Kill(); } catch { } throw new TimeoutException("Playlist discovery timed out."); }
                        try { proc.WaitForExit(); } catch { }
                        if (proc.ExitCode != 0 && lines.Count == 0)
                            throw new InvalidOperationException(errors.Count > 0 ? errors[errors.Count - 1] : "yt-dlp returned exit code " + proc.ExitCode.ToString(CultureInfo.InvariantCulture));
                    }
                    string[] snapshot; lock (lines) snapshot = lines.ToArray();
                    var serializer = new JavaScriptSerializer { MaxJsonLength = Int32.MaxValue, RecursionLimit = 128 };
                    var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                    foreach (string line in snapshot)
                    {
                        Dictionary<string, object> entry;
                        try { entry = AsMap(serializer.DeserializeObject(line)); } catch { continue; }
                        string url = DiscoveredPlaylistUrl(entry);
                        if (String.IsNullOrWhiteSpace(url) || !seen.Add(url)) continue;
                        string title = GetString(entry, "title", "Untitled playlist").Trim();
                        string channel = GetString(entry, "channel", GetString(entry, "uploader", GetString(entry, "channel_name", ""))).Trim();
                        int count = GetInt(entry, "playlist_count", GetInt(entry, "n_entries", GetInt(entry, "playlist_index", 0)));
                        string display = title;
                        if (!String.IsNullOrWhiteSpace(channel)) display += "  —  " + channel;
                        if (count > 0) display += "  ·  " + count.ToString("N0", CultureInfo.InvariantCulture) + " tracks";
                        results.Add(new PoolDiscoveryItem { Title = title, Channel = channel, Url = url, TrackCount = count, Display = display });
                        if (results.Count >= 18) break;
                    }
                }
                catch (Exception ex) { failure = ex.Message; }

                try
                {
                    _window.Dispatcher.BeginInvoke(DispatcherPriority.Background, new Action(delegate
                    {
                        if (generation != _poolDiscoveryGeneration) return;
                        if (_poolDiscoverButton != null) { _poolDiscoverButton.IsEnabled = true; _poolDiscoverButton.Content = "Discover"; }
                        if (_poolDiscoverList != null) _poolDiscoverList.ItemsSource = results;
                        if (_poolDiscoverStatusText != null)
                        {
                            if (!String.IsNullOrWhiteSpace(failure)) _poolDiscoverStatusText.Text = "Discovery failed: " + failure;
                            else if (results.Count == 0) _poolDiscoverStatusText.Text = "No playlist results found.";
                            else _poolDiscoverStatusText.Text = results.Count.ToString(CultureInfo.InvariantCulture) + " playlists found";
                        }
                    }));
                }
                catch { }
            });
        }

        private void AddSelectedDiscoveredPlaylists()
        {
            if (_poolDiscoverList == null || _poolSourcesBox == null) return;
            var urls = new List<string>();
            foreach (object raw in _poolDiscoverList.SelectedItems)
            {
                PoolDiscoveryItem item = raw as PoolDiscoveryItem;
                if (item != null && !String.IsNullOrWhiteSpace(item.Url)) urls.Add(item.Url.Trim());
            }
            if (urls.Count == 0) return;
            var existing = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (string line in (_poolSourcesBox.Text ?? "").Replace("\r", "").Split('\n'))
            {
                string trimmed = line.Trim();
                if (trimmed.Length == 0) continue;
                int space = trimmed.IndexOf(' ');
                string candidate = space > 0 && trimmed.Substring(0, space).EndsWith("x", StringComparison.OrdinalIgnoreCase) ? trimmed.Substring(space + 1).Trim() : trimmed;
                existing.Add(candidate);
            }
            int added = 0;
            var append = new List<string>();
            foreach (string url in urls) if (existing.Add(url)) { append.Add(url); added++; }
            if (append.Count > 0)
            {
                string prefix = String.IsNullOrWhiteSpace(_poolSourcesBox.Text) ? "" : (_poolSourcesBox.Text.TrimEnd() + Environment.NewLine);
                _poolSourcesBox.Text = prefix + String.Join(Environment.NewLine, append.ToArray());
                _poolSourcesBox.CaretIndex = _poolSourcesBox.Text.Length;
            }
            if (_poolDiscoverStatusText != null) _poolDiscoverStatusText.Text = added > 0 ? (added.ToString(CultureInfo.InvariantCulture) + " added to this Pool") : "Already in this Pool";
            if (_poolDiscoverAddButton != null) _poolDiscoverAddButton.IsEnabled = _poolDiscoverList.SelectedItems.Count > 0;
        }

        private void OpenPlaylistPool()
        {
            if (_poolOverlay == null) return;
            // Pool source text/weights are a live authoring draft. Re-invoking the command should
            // focus the existing surface, never reconstruct it underneath the user's hands.
            if (_poolOverlay.Visibility == Visibility.Visible)
            {
                _window.Activate();
                if (_poolSourcesBox != null) _poolSourcesBox.Focus();
                return;
            }
            if (!PrepareAuthoringSurface(AuthoringSurfaceKind.PlaylistPool, "Playlist Pool")) return;
            _poolReturnFocus = Keyboard.FocusedElement;
            if (_miniMode || (!_queueOpen && _window.WindowState == WindowState.Normal && _window.ActualHeight <= CompactControllerMaxHeight + 60.0)) ExpandCompactHostForOverlay();
            LoadPlaylistPoolDraft();
            RefreshSavedPoolList(null);
            _poolOverlay.Visibility = Visibility.Visible;
            _poolOverlay.IsHitTestVisible = true;
            SyncHostedMediaAirspace();
            _poolSourcesBox.Focus();
        }

        private void ClosePlaylistPool()
        {
            if (_poolOverlay == null || _poolBuildActive) return;
            _poolOverlay.Visibility = Visibility.Collapsed;
            SyncHostedMediaAirspace();
            RestoreCompactHostAfterOverlay();
            IInputElement restore = _poolReturnFocus;
            _poolReturnFocus = null;
            RestoreKeyboardFocus(restore);
        }

        private static string PoolShuffleModeFromUi(ComboBox combo)
        {
            string text = combo == null ? "" : Convert.ToString(combo.SelectedItem, CultureInfo.InvariantCulture);
            return String.Equals(text, "Balanced sources", StringComparison.OrdinalIgnoreCase) ? "balanced" : "global";
        }

        private static string PoolShuffleModeLabel(string mode)
        {
            return String.Equals(mode, "balanced", StringComparison.OrdinalIgnoreCase) ? "Balanced sources" : "Global random";
        }

        private static string FormatPoolSourceSpec(string url, int weight)
        {
            int w = Math.Max(1, Math.Min(9, weight));
            return (w == 1 ? "" : w.ToString(CultureInfo.InvariantCulture) + "x ") + (url ?? "");
        }

        private void LoadPlaylistPoolDraft()
        {
            try
            {
                string sourceText = "";
                Dictionary<string, object> pool = ReadJsonFresh(CurrentPoolPath);
                var sources = GetList(pool, "sources");
                if (sources.Count > 0)
                {
                    var lines = new List<string>();
                    foreach (object raw in sources)
                    {
                        var map = AsMap(raw);
                        string u = GetString(map, "url", "").Trim();
                        int weight = Math.Max(1, Math.Min(9, GetInt(map, "weight", 1)));
                        if (u.Length > 0) lines.Add(FormatPoolSourceSpec(u, weight));
                    }
                    sourceText = String.Join(Environment.NewLine, lines.ToArray());
                }
                if (sourceText.Length == 0 && File.Exists(PoolSourcesPath)) sourceText = ReadTextShared(PoolSourcesPath).Trim();
                _poolSourcesBox.Text = sourceText;
                if (_poolNameBox != null) _poolNameBox.Text = GetString(pool, "name", "Current Pool");
                _poolDeduplicateCheck.IsChecked = pool.Count == 0 || GetBool(pool, "deduplicate", true);
                if (_poolShuffleModeCombo != null) _poolShuffleModeCombo.SelectedItem = PoolShuffleModeLabel(GetString(pool, "shuffle_mode", "global"));
                int sourceCount = GetInt(pool, "source_count", sources.Count);
                int trackCount = GetInt(pool, "track_count", 0);
                _poolCurrentSummaryText.Text = trackCount > 0
                    ? sourceCount.ToString("N0", CultureInfo.InvariantCulture) + " sources  |  " + trackCount.ToString("N0", CultureInfo.InvariantCulture) + " tracks  |  " + PoolShuffleModeLabel(GetString(pool, "shuffle_mode", "global"))
                    : "No Pool built yet";
                _poolStatusText.Text = "Ready.";
            }
            catch
            {
                _poolCurrentSummaryText.Text = "Pool state unavailable";
                _poolStatusText.Text = "You can still paste sources and rebuild.";
            }
        }

        private bool TryParsePoolSourceLines(out List<PoolSourceSpec> result, out string error)
        {
            result = new List<PoolSourceSpec>();
            error = "";
            var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            string raw = _poolSourcesBox != null ? (_poolSourcesBox.Text ?? "") : "";
            int lineNumber = 0;
            foreach (string line0 in raw.Replace("\r", "").Split('\n'))
            {
                lineNumber++;
                string line = (line0 ?? "").Trim();
                if (line.Length == 0) continue;
                int weight = 1;
                string urlText = line;
                int space = line.IndexOf(' ');
                if (space > 0)
                {
                    string token = line.Substring(0, space).Trim();
                    if (token.EndsWith("x", StringComparison.OrdinalIgnoreCase))
                    {
                        int parsed;
                        if (!Int32.TryParse(token.Substring(0, token.Length - 1), NumberStyles.Integer, CultureInfo.InvariantCulture, out parsed) || parsed < 1 || parsed > 9)
                        {
                            error = "Line " + lineNumber.ToString(CultureInfo.InvariantCulture) + ": source weight must be 1x through 9x.";
                            return false;
                        }
                        weight = parsed;
                        urlText = line.Substring(space + 1).Trim();
                    }
                }
                Uri uri;
                if (!Uri.TryCreate(urlText, UriKind.Absolute, out uri) || (uri.Scheme != Uri.UriSchemeHttp && uri.Scheme != Uri.UriSchemeHttps))
                {
                    error = "Line " + lineNumber.ToString(CultureInfo.InvariantCulture) + ": expected a YouTube http/https URL" + (weight != 1 ? " after the weight." : ".");
                    return false;
                }
                if (seen.Add(urlText)) result.Add(new PoolSourceSpec { Url = urlText, Weight = weight });
            }
            if (result.Count == 0)
            {
                error = "Paste at least one valid http/https playlist or video URL.";
                return false;
            }
            return true;
        }

        private string CurrentPoolName()
        {
            string name = _poolNameBox == null ? "" : (_poolNameBox.Text ?? "").Trim();
            return name.Length == 0 ? "Current Pool" : name;
        }

        private string PoolDefinitionPath(string name)
        {
            string key = Sha256Hex((name ?? "").Trim().ToLowerInvariant());
            return Path.Combine(SavedPoolsDirectory, key.Substring(0, 24) + ".json");
        }

        private Dictionary<string, object> MakePoolDefinition(string name, bool deduplicate, string shuffleMode, IEnumerable<PoolSourceSpec> specs)
        {
            var sourceMaps = new List<object>();
            foreach (PoolSourceSpec spec in specs)
                sourceMaps.Add(new Dictionary<string, object> { { "url", spec.Url }, { "weight", spec.Weight } });
            return new Dictionary<string, object>
            {
                { "schema", 1 }, { "name", name }, { "updated_utc", DateTime.UtcNow.ToString("O", CultureInfo.InvariantCulture) },
                { "deduplicate", deduplicate }, { "shuffle_mode", shuffleMode }, { "sources", sourceMaps }
            };
        }

        private void RefreshSavedPoolList(string selectName)
        {
            if (_poolSavedCombo == null) return;
            string prior = selectName;
            if (String.IsNullOrWhiteSpace(prior)) prior = Convert.ToString(_poolSavedCombo.SelectedItem, CultureInfo.InvariantCulture);
            var names = new List<string>();
            try
            {
                Directory.CreateDirectory(SavedPoolsDirectory);
                foreach (string path in Directory.GetFiles(SavedPoolsDirectory, "*.json"))
                {
                    Dictionary<string, object> map = ReadJsonFresh(path);
                    string name = GetString(map, "name", "").Trim();
                    if (name.Length > 0 && !names.Contains(name, StringComparer.OrdinalIgnoreCase)) names.Add(name);
                }
            }
            catch { }
            names.Sort(StringComparer.CurrentCultureIgnoreCase);
            _poolSavedCombo.Items.Clear();
            foreach (string name in names) _poolSavedCombo.Items.Add(name);
            if (!String.IsNullOrWhiteSpace(prior))
            {
                string match = names.FirstOrDefault(x => String.Equals(x, prior, StringComparison.OrdinalIgnoreCase));
                if (match != null) _poolSavedCombo.SelectedItem = match;
            }
            if (_poolSavedCombo.SelectedIndex < 0 && names.Count > 0) _poolSavedCombo.SelectedIndex = 0;
        }

        private void SavePlaylistPoolDefinition()
        {
            if (_poolBuildActive) return;
            List<PoolSourceSpec> specs; string error;
            if (!TryParsePoolSourceLines(out specs, out error)) { _poolStatusText.Text = error; return; }
            string name = CurrentPoolName();
            bool deduplicate = _poolDeduplicateCheck == null || _poolDeduplicateCheck.IsChecked == true;
            string shuffleMode = PoolShuffleModeFromUi(_poolShuffleModeCombo);
            try
            {
                Directory.CreateDirectory(SavedPoolsDirectory);
                WriteUtf8NoBom(PoolDefinitionPath(name), _json.Serialize(MakePoolDefinition(name, deduplicate, shuffleMode, specs)));
                RefreshSavedPoolList(name);
                _poolStatusText.Text = "Saved '" + name + "'. Building it later re-resolves the playlists, so newly added tracks can join the next shuffle.";
                ShowToast("Pool saved", name);
            }
            catch (Exception ex) { _poolStatusText.Text = "Could not save Pool: " + ex.Message; }
        }

        private void ApplyPoolDefinition(Dictionary<string, object> map)
        {
            if (map == null || map.Count == 0) throw new InvalidOperationException("Saved Pool is empty or unreadable.");
            string name = GetString(map, "name", "Current Pool");
            var lines = new List<string>();
            foreach (object raw in GetList(map, "sources"))
            {
                var source = AsMap(raw);
                string url = GetString(source, "url", "").Trim();
                if (url.Length == 0) continue;
                lines.Add(FormatPoolSourceSpec(url, Math.Max(1, Math.Min(9, GetInt(source, "weight", 1)))));
            }
            if (lines.Count == 0) throw new InvalidOperationException("Saved Pool has no usable sources.");
            _poolNameBox.Text = name;
            _poolSourcesBox.Text = String.Join(Environment.NewLine, lines.ToArray());
            _poolDeduplicateCheck.IsChecked = GetBool(map, "deduplicate", true);
            _poolShuffleModeCombo.SelectedItem = PoolShuffleModeLabel(GetString(map, "shuffle_mode", "global"));
            _poolStatusText.Text = "Loaded '" + name + "'. Build + shuffle when you want a fresh session from these sources.";
        }

        private void LoadSelectedPlaylistPoolDefinition()
        {
            if (_poolBuildActive || _poolSavedCombo == null) return;
            string name = Convert.ToString(_poolSavedCombo.SelectedItem, CultureInfo.InvariantCulture);
            if (String.IsNullOrWhiteSpace(name)) { _poolStatusText.Text = "No saved Pool selected."; return; }
            try { ApplyPoolDefinition(ReadJsonFresh(PoolDefinitionPath(name))); }
            catch (Exception ex) { _poolStatusText.Text = "Could not load Pool: " + ex.Message; }
        }

        private void DeleteSelectedPlaylistPoolDefinition()
        {
            if (_poolBuildActive || _poolSavedCombo == null) return;
            string name = Convert.ToString(_poolSavedCombo.SelectedItem, CultureInfo.InvariantCulture);
            if (String.IsNullOrWhiteSpace(name)) { _poolStatusText.Text = "No saved Pool selected."; return; }
            MessageBoxResult answer = MessageBox.Show(_window, "Delete the saved Pool definition '" + name + "'?\r\n\r\nThis does not delete cached media or the currently playing session.", "Delete Pool", MessageBoxButton.YesNo, MessageBoxImage.Question);
            if (answer != MessageBoxResult.Yes) return;
            try
            {
                string path = PoolDefinitionPath(name);
                if (File.Exists(path)) File.Delete(path);
                RefreshSavedPoolList(null);
                _poolStatusText.Text = "Deleted saved Pool '" + name + "'.";
            }
            catch (Exception ex) { _poolStatusText.Text = "Could not delete Pool: " + ex.Message; }
        }

