        private static string PoolCanonicalUrl(Dictionary<string, object> entry, string sourceUrl)
        {
            string id = GetString(entry, "id", "").Trim();
            string webpage = GetString(entry, "webpage_url", "").Trim();
            if (webpage.StartsWith("http://", StringComparison.OrdinalIgnoreCase) || webpage.StartsWith("https://", StringComparison.OrdinalIgnoreCase)) return webpage;
            string raw = GetString(entry, "url", "").Trim();
            if (raw.StartsWith("http://", StringComparison.OrdinalIgnoreCase) || raw.StartsWith("https://", StringComparison.OrdinalIgnoreCase)) return raw;
            if (id.Length > 0 && sourceUrl.IndexOf("youtu", StringComparison.OrdinalIgnoreCase) >= 0) return "https://www.youtube.com/watch?v=" + id;
            return raw;
        }

        private static string PoolTrackKey(string id, string url)
        {
            if (!String.IsNullOrWhiteSpace(id)) return "id:" + id.Trim().ToLowerInvariant();
            return "url:" + (url ?? "").Trim();
        }

        private static void ShufflePoolTracks(List<PoolTrackBuild> tracks, int seed)
        {
            var random = new Random(seed);
            for (int i = tracks.Count - 1; i > 0; i--)
            {
                int j = random.Next(i + 1);
                PoolTrackBuild temp = tracks[i]; tracks[i] = tracks[j]; tracks[j] = temp;
            }
        }

        private static void ShufflePoolTracksBalanced(List<PoolTrackBuild> tracks, List<PoolSourceBuild> sources, int seed)
        {
            var random = new Random(seed);
            var sourceByIndex = sources.ToDictionary(x => x.Index, x => x);
            var buckets = new Dictionary<int, List<PoolTrackBuild>>();
            foreach (PoolSourceBuild source in sources) buckets[source.Index] = new List<PoolTrackBuild>();

            var assignment = new List<PoolTrackBuild>(tracks);
            ShufflePoolTracks(assignment, seed ^ 0x51A7B11);
            foreach (PoolTrackBuild track in assignment)
            {
                int chosen = 0;
                double bestLoad = Double.MaxValue;
                foreach (int index in track.SourceIndexes)
                {
                    PoolSourceBuild src;
                    List<PoolTrackBuild> bucket;
                    if (!sourceByIndex.TryGetValue(index, out src) || !buckets.TryGetValue(index, out bucket)) continue;
                    double load = (double)bucket.Count / Math.Max(1, src.Weight);
                    if (load < bestLoad - 0.000001 || (Math.Abs(load - bestLoad) < 0.000001 && random.Next(2) == 0))
                    {
                        bestLoad = load;
                        chosen = index;
                    }
                }
                if (chosen == 0 && sources.Count > 0) chosen = sources[0].Index;
                buckets[chosen].Add(track);
            }
            foreach (List<PoolTrackBuild> bucket in buckets.Values) ShufflePoolTracks(bucket, random.Next());

            var credits = new Dictionary<int, int>();
            foreach (PoolSourceBuild source in sources) credits[source.Index] = random.Next(Math.Max(1, source.Weight));
            var mixed = new List<PoolTrackBuild>(tracks.Count);
            while (mixed.Count < tracks.Count)
            {
                int totalWeight = 0;
                foreach (PoolSourceBuild source in sources) if (buckets[source.Index].Count > 0) totalWeight += Math.Max(1, source.Weight);
                if (totalWeight <= 0) break;
                PoolSourceBuild chosen = null;
                int bestCredit = Int32.MinValue;
                foreach (PoolSourceBuild source in sources)
                {
                    if (buckets[source.Index].Count == 0) continue;
                    credits[source.Index] += Math.Max(1, source.Weight);
                    int credit = credits[source.Index];
                    if (chosen == null || credit > bestCredit || (credit == bestCredit && random.Next(2) == 0))
                    {
                        chosen = source;
                        bestCredit = credit;
                    }
                }
                if (chosen == null) break;
                credits[chosen.Index] -= totalWeight;
                List<PoolTrackBuild> selectedBucket = buckets[chosen.Index];
                int last = selectedBucket.Count - 1;
                mixed.Add(selectedBucket[last]);
                selectedBucket.RemoveAt(last);
            }
            if (mixed.Count == tracks.Count)
            {
                tracks.Clear();
                tracks.AddRange(mixed);
            }
        }

        private void BuildPlaylistPool()
        {
            if (_poolBuildActive) return;
            List<PoolSourceSpec> sourceSpecs; string parseError;
            if (!TryParsePoolSourceLines(out sourceSpecs, out parseError))
            {
                _poolStatusText.Text = parseError;
                return;
            }
            bool deduplicate = _poolDeduplicateCheck == null || _poolDeduplicateCheck.IsChecked == true;
            string shuffleMode = PoolShuffleModeFromUi(_poolShuffleModeCombo);
            string poolName = CurrentPoolName();
            string yt = Path.Combine(_runtimeRoot, "yt-dlp", "yt-dlp.exe");
            if (!File.Exists(yt))
            {
                _poolStatusText.Text = "yt-dlp is missing from the YOMI runtime.";
                return;
            }
            SetPoolBuildUi(true, "Resolving " + sourceSpecs.Count.ToString(CultureInfo.InvariantCulture) + " source" + (sourceSpecs.Count == 1 ? "..." : "s..."));
            PoolSourceSpec[] sourceSnapshot = sourceSpecs.ToArray();
            ThreadPool.QueueUserWorkItem(delegate
            {
                var serializer = new JavaScriptSerializer { MaxJsonLength = Int32.MaxValue, RecursionLimit = 128 };
                var sources = new List<PoolSourceBuild>();
                var tracks = new List<PoolTrackBuild>();
                var unique = new Dictionary<string, PoolTrackBuild>(StringComparer.OrdinalIgnoreCase);
                string failure = "";
                int rawTrackCount = 0;
                try
                {
                    for (int sourceIndex = 0; sourceIndex < sourceSnapshot.Length; sourceIndex++)
                    {
                        PoolSourceSpec spec = sourceSnapshot[sourceIndex];
                        string sourceUrl = spec.Url;
                        PoolProgress("Resolving source " + (sourceIndex + 1).ToString(CultureInfo.InvariantCulture) + " / " + sourceSnapshot.Length.ToString(CultureInfo.InvariantCulture) + "...");
                        var source = new PoolSourceBuild { Index = sourceIndex + 1, Url = sourceUrl, Weight = spec.Weight, Label = "Source " + (sourceIndex + 1).ToString(CultureInfo.InvariantCulture) };
                        string deno = Path.Combine(_runtimeRoot, "deno", "deno.exe");
                        string args = "--flat-playlist --ignore-errors --quiet --no-warnings --dump-json";
                        if (File.Exists(deno)) args += " --js-runtimes " + Quote("deno:" + deno);
                        args += " " + Quote(sourceUrl);
                        var lines = new List<string>();
                        var errors = new List<string>();
                        var psi = new ProcessStartInfo
                        {
                            FileName = yt,
                            Arguments = args,
                            WorkingDirectory = _dataRoot,
                            UseShellExecute = false,
                            CreateNoWindow = true,
                            WindowStyle = ProcessWindowStyle.Hidden,
                            RedirectStandardOutput = true,
                            RedirectStandardError = true
                        };
                        using (var proc = new Process { StartInfo = psi })
                        {
                            proc.OutputDataReceived += delegate(object sender, DataReceivedEventArgs e) { if (!String.IsNullOrWhiteSpace(e.Data)) lock (lines) lines.Add(e.Data); };
                            proc.ErrorDataReceived += delegate(object sender, DataReceivedEventArgs e) { if (!String.IsNullOrWhiteSpace(e.Data)) lock (errors) errors.Add(e.Data); };
                            if (!proc.Start()) throw new InvalidOperationException("Windows could not start yt-dlp.");
                            try { proc.PriorityClass = ProcessPriorityClass.BelowNormal; } catch { }
                            proc.BeginOutputReadLine(); proc.BeginErrorReadLine();
                            if (!proc.WaitForExit(180000)) { try { proc.Kill(); } catch { } throw new TimeoutException("Source " + (sourceIndex + 1).ToString(CultureInfo.InvariantCulture) + " timed out."); }
                            try { proc.WaitForExit(); } catch { }
                            if (proc.ExitCode != 0 && lines.Count == 0)
                            {
                                string detail = errors.Count > 0 ? errors[errors.Count - 1] : "yt-dlp returned exit code " + proc.ExitCode.ToString(CultureInfo.InvariantCulture);
                                throw new InvalidOperationException("Source " + (sourceIndex + 1).ToString(CultureInfo.InvariantCulture) + " failed: " + detail);
                            }
                        }
                        string[] snapshot; lock (lines) snapshot = lines.ToArray();
                        foreach (string line in snapshot)
                        {
                            Dictionary<string, object> entry;
                            try { entry = AsMap(serializer.DeserializeObject(line)); } catch { continue; }
                            if (entry.Count == 0) continue;
                            string id = GetString(entry, "id", "").Trim();
                            string url = PoolCanonicalUrl(entry, sourceUrl);
                            if (String.IsNullOrWhiteSpace(url)) continue;
                            string playlistTitle = GetString(entry, "playlist_title", GetString(entry, "playlist", "")).Trim();
                            if (!String.IsNullOrWhiteSpace(playlistTitle) && source.Label.StartsWith("Source ", StringComparison.Ordinal)) source.Label = playlistTitle;
                            var candidate = new PoolTrackBuild
                            {
                                Url = url,
                                Id = id,
                                Title = GetString(entry, "title", "").Trim(),
                                Channel = GetString(entry, "channel", GetString(entry, "uploader", "")).Trim(),
                                Duration = GetDouble(entry, "duration", 0)
                            };
                            string key = PoolTrackKey(candidate.Id, candidate.Url);
                            rawTrackCount++;
                            PoolTrackBuild existing;
                            if (deduplicate && unique.TryGetValue(key, out existing))
                            {
                                if (!existing.SourceIndexes.Contains(source.Index))
                                {
                                    existing.SourceIndexes.Add(source.Index);
                                    existing.SourceLabels.Add(source.Label);
                                }
                            }
                            else
                            {
                                candidate.SourceIndexes.Add(source.Index);
                                candidate.SourceLabels.Add(source.Label);
                                tracks.Add(candidate);
                                if (deduplicate) unique[key] = candidate;
                            }
                            source.Extracted++;
                        }
                        sources.Add(source);
                        PoolProgress("Resolved " + (sourceIndex + 1).ToString(CultureInfo.InvariantCulture) + " / " + sourceSnapshot.Length.ToString(CultureInfo.InvariantCulture) + "  |  " + tracks.Count.ToString("N0", CultureInfo.InvariantCulture) + " playable tracks");
                    }
                    if (tracks.Count == 0) throw new InvalidOperationException("The Pool resolved zero playable tracks.");
                    foreach (PoolTrackBuild track in tracks)
                    {
                        for (int i = 0; i < track.SourceIndexes.Count; i++)
                        {
                            int index = track.SourceIndexes[i];
                            PoolSourceBuild src = sources.FirstOrDefault(x => x.Index == index);
                            if (src != null && i < track.SourceLabels.Count) track.SourceLabels[i] = src.Label;
                        }
                    }
                    int seed = BitConverter.ToInt32(Guid.NewGuid().ToByteArray(), 0) & Int32.MaxValue;
                    if (String.Equals(shuffleMode, "balanced", StringComparison.OrdinalIgnoreCase)) ShufflePoolTracksBalanced(tracks, sources, seed);
                    else ShufflePoolTracks(tracks, seed);
                    var sourceMaps = new List<object>();
                    foreach (PoolSourceBuild source in sources)
                    {
                        sourceMaps.Add(new Dictionary<string, object> { { "index", source.Index }, { "url", source.Url }, { "label", source.Label }, { "weight", source.Weight }, { "extracted_count", source.Extracted } });
                    }
                    var trackMaps = new List<object>();
                    for (int i = 0; i < tracks.Count; i++)
                    {
                        PoolTrackBuild track = tracks[i];
                        trackMaps.Add(new Dictionary<string, object>
                        {
                            { "position", i + 1 }, { "url", track.Url }, { "id", track.Id }, { "title", track.Title }, { "channel", track.Channel }, { "duration", track.Duration },
                            { "source_indexes", track.SourceIndexes.Cast<object>().ToList() }, { "source_labels", track.SourceLabels.Cast<object>().ToList() }
                        });
                    }
                    var poolMap = new Dictionary<string, object>
                    {
                        { "schema", 2 }, { "name", poolName }, { "built_utc", DateTime.UtcNow.ToString("O", CultureInfo.InvariantCulture) },
                        { "deduplicate", deduplicate }, { "shuffle_mode", shuffleMode }, { "shuffle_seed", seed }, { "source_count", sources.Count }, { "raw_track_count", rawTrackCount }, { "track_count", tracks.Count },
                        { "sources", sourceMaps }, { "tracks", trackMaps }
                    };
                    Directory.CreateDirectory(_dataRoot); Directory.CreateDirectory(_stateRoot);
                    string playlistPath = Path.Combine(_dataRoot, "playlist.txt");
                    bool oldSourcesExists = File.Exists(PoolSourcesPath), oldPoolExists = File.Exists(CurrentPoolPath), oldPlaylistExists = File.Exists(playlistPath), oldResetExists = File.Exists(PoolResetPath);
                    string oldSources = oldSourcesExists ? ReadTextShared(PoolSourcesPath) : "";
                    string oldPool = oldPoolExists ? ReadTextShared(CurrentPoolPath) : "";
                    string oldPlaylist = oldPlaylistExists ? ReadTextShared(playlistPath) : "";
                    string oldReset = oldResetExists ? ReadTextShared(PoolResetPath) : "";
                    try
                    {
                        WriteUtf8NoBom(PoolSourcesPath, String.Join(Environment.NewLine, sourceSnapshot.Select(x => FormatPoolSourceSpec(x.Url, x.Weight)).ToArray()) + Environment.NewLine);
                        WriteUtf8NoBom(CurrentPoolPath, serializer.Serialize(poolMap));
                        WriteUtf8NoBom(playlistPath, String.Join(Environment.NewLine, tracks.Select(t => t.Url).ToArray()) + Environment.NewLine);
                        WriteUtf8NoBom(PoolResetPath, DateTime.UtcNow.ToString("O", CultureInfo.InvariantCulture));
                    }
                    catch
                    {
                        RestoreFileSnapshot(PoolSourcesPath, oldSourcesExists, oldSources);
                        RestoreFileSnapshot(CurrentPoolPath, oldPoolExists, oldPool);
                        RestoreFileSnapshot(playlistPath, oldPlaylistExists, oldPlaylist);
                        RestoreFileSnapshot(PoolResetPath, oldResetExists, oldReset);
                        throw;
                    }
                    int duplicateCount = Math.Max(0, rawTrackCount - tracks.Count);
                    _window.Dispatcher.BeginInvoke(DispatcherPriority.Normal, new Action(delegate
                    {
                        string modeLabel = PoolShuffleModeLabel(shuffleMode);
                        SetPoolBuildUi(false, "Built " + tracks.Count.ToString("N0", CultureInfo.InvariantCulture) + " tracks from " + sources.Count.ToString("N0", CultureInfo.InvariantCulture) + " sources  |  " + modeLabel + (duplicateCount > 0 ? "  |  " + duplicateCount.ToString("N0", CultureInfo.InvariantCulture) + " duplicates collapsed" : "") + ".");
                        _poolCurrentSummaryText.Text = poolName + "  |  " + sources.Count.ToString("N0", CultureInfo.InvariantCulture) + " sources  |  " + tracks.Count.ToString("N0", CultureInfo.InvariantCulture) + " tracks  |  " + modeLabel;
                        MarkActiveSlotSourceChanged("Pool");
                        AddActivity("Playlist Pool", "built " + tracks.Count.ToString(CultureInfo.InvariantCulture) + " tracks from " + sources.Count.ToString(CultureInfo.InvariantCulture) + " sources");
                        ShowToast("Playlist Pool ready", modeLabel + ": " + tracks.Count.ToString("N0", CultureInfo.InvariantCulture) + " tracks.");
                        if (_running)
                        {
                            MessageBoxResult restart = MessageBox.Show(_window,
                                "The Pool is built. Restart YOMI playback now so the new mix becomes authoritative?\r\n\r\nCurrent playback keeps running until you choose to switch.",
                                "Activate Playlist Pool", MessageBoxButton.YesNo, MessageBoxImage.Question);
                            if (restart == MessageBoxResult.Yes) RestartPlaybackForPool();
                            else _poolStatusText.Text += " Current playback is unchanged; restart when you want to activate it.";
                        }
                        else
                        {
                            _poolStatusText.Text += " Press Play to start it.";
                        }
                    }));
                }
                catch (Exception ex)
                {
                    failure = ex.Message;
                    _window.Dispatcher.BeginInvoke(DispatcherPriority.Normal, new Action(delegate
                    {
                        SetPoolBuildUi(false, "Could not build Pool: " + failure);
                        ShowToast("Playlist Pool", "Build failed. Your current playlist was left unchanged.");
                    }));
                }
            });
        }

        private static void RestoreFileSnapshot(string path, bool existed, string content)
        {
            try
            {
                if (existed) WriteUtf8NoBom(path, content ?? "");
                else if (File.Exists(path)) File.Delete(path);
            }
            catch { }
        }

        private void RestartPlaybackForPool()
        {
            if (!_running) { StartEngine(); return; }
            _poolStatusText.Text = "Restarting playback with the new Pool...";
            if (!StopOwnedYomiRuntime())
            {
                _poolStatusText.Text = "Pool built, but the current runtime could not be stopped safely. Restart YOMI later to activate it.";
                return;
            }
            _running = false; _audioActive = false; _paused = false;
            _startupPrewarmReady = false;
            try { File.Delete(Path.Combine(_stateRoot, "planned-stop.pending")); } catch { }
            SafeRefresh(true);
            var restart = new DispatcherTimer { Interval = TimeSpan.FromMilliseconds(750) };
            restart.Tick += delegate
            {
                restart.Stop();
                StartEngine();
                _poolStatusText.Text = "Pool active. Playback is starting from the global shuffle.";
            };
            restart.Start();
        }

        private string UpdateLaneSummary()
        {
            string updateHostPath = Path.Combine(_appDir, "YomiUpdateHost.ps1");
            if (!File.Exists(updateHostPath)) return "Update packages: setup EXE only (persistent host is not installed).";
            bool associationReady = false;
            try
            {
                using (Microsoft.Win32.RegistryKey extension = Microsoft.Win32.Registry.CurrentUser.OpenSubKey(@"Software\Classes\.yomiupdate"))
                using (Microsoft.Win32.RegistryKey command = Microsoft.Win32.Registry.CurrentUser.OpenSubKey(@"Software\Classes\YOMI.UpdatePackage\shell\open\command"))
                {
                    string type = extension == null ? "" : Convert.ToString(extension.GetValue(""), CultureInfo.InvariantCulture);
                    string launch = command == null ? "" : Convert.ToString(command.GetValue(""), CultureInfo.InvariantCulture);
                    associationReady = String.Equals(type, "YOMI.UpdatePackage", StringComparison.OrdinalIgnoreCase) &&
                        !String.IsNullOrWhiteSpace(launch) && launch.IndexOf("YomiUpdateHost.ps1", StringComparison.OrdinalIgnoreCase) >= 0;
                }
            }
            catch { }
            return associationReady
                ? "Update packages: ready in YOMI and by .yomiupdate double-click."
                : "Update packages: ready through File > Apply YOMI update package; double-click association is not registered.";
        }

        private string InstalledFocusedBuildSummary()
        {
            // R61.86: About reads the same promoted build marker the installer writes.
            // A stale hard-coded revision can therefore never disagree with the installed bytes again.
            try
            {
                string marker = Path.Combine(_appDir, "FOCUSED-BUILD.txt");
                if (File.Exists(marker))
                {
                    string[] markerLines = File.ReadAllLines(marker);
                    for (int i = markerLines.Length - 1; i >= 0; i--)
                    {
                        string line = (markerLines[i] ?? "").Trim();
                        if (line.Length > 0) return line;
                    }
                }
            }
            catch { }
            return "Optical Ergonomics + Interaction Hierarchy R61.96";
        }

        private void ShowAboutYomi()
        {
            string text =
                "YOMI 4.2.0.8 - YouTube OBS Music Interface\r\n" +
                "Focused build: " + InstalledFocusedBuildSummary() + "\r\n" +
                UpdateLaneSummary() + "\r\n\r\n" +
                "A music player built for lightweight YouTube playback and OBS presentation.";
            MessageBox.Show(_window, text, "About YOMI 4.2.0.8", MessageBoxButton.OK, MessageBoxImage.Information);
        }

        private void CheckForUpdates()
        {
            try
            {
                // The full YOMI installation already owns the verified public release lane.
                // Invoke that updater directly instead of cloning its network/verification logic here.
                string publicUpdater = Path.Combine(_appDir, "update.ps1");
                string powershell = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows), "System32", "WindowsPowerShell", "v1.0", "powershell.exe");
                if (File.Exists(publicUpdater))
                {
                    SafeStart(powershell, "-NoProfile -ExecutionPolicy Bypass -File " + Quote(publicUpdater));
                    ShowToast("Updates", "Checking for YOMI updates...");
                    return;
                }

                DirectoryInfo appParent = Directory.GetParent(_appDir);
                string legacySettings = appParent == null ? "" : Path.Combine(appParent.FullName, "app", "settings.ps1");
                if (File.Exists(legacySettings))
                {
                    SafeStart(powershell, "-NoProfile -ExecutionPolicy Bypass -File " + Quote(legacySettings));
                    ShowToast("Updates", "Opened YOMI settings. Check for Updates is in Components.");
                    return;
                }

                MessageBoxResult choose = MessageBox.Show(_window,
                    "The public updater is not present in this installation.\r\n\r\n" + UpdateLaneSummary() +
                    "\r\n\r\nOpen the verified update-package picker instead?",
                    "Check for updates", MessageBoxButton.YesNo, MessageBoxImage.Information);
                if (choose == MessageBoxResult.Yes) ApplyUpdatePackage();
            }
            catch (Exception ex)
            {
                ShowToast("Updates", "Could not check for updates: " + ex.Message);
            }
        }

        private void ApplyUpdatePackage()
        {
            try
            {
                string host = Path.Combine(_appDir, "YomiUpdateHost.ps1");
                if (!File.Exists(host))
                {
                    ShowToast("Updater", "The persistent update host is not installed yet.");
                    return;
                }
                var dialog = new Microsoft.Win32.OpenFileDialog
                {
                    Title = "Apply YOMI update package",
                    Filter = "YOMI update package (*.yomiupdate)|*.yomiupdate|All files (*.*)|*.*",
                    CheckFileExists = true,
                    Multiselect = false
                };
                bool? accepted = dialog.ShowDialog(_window);
                if (accepted != true) return;
                string powershell = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows), "System32", "WindowsPowerShell", "v1.0", "powershell.exe");
                SafeStart(powershell, "-NoProfile -WindowStyle Hidden -ExecutionPolicy Bypass -File " + Quote(host) + " " + Quote(dialog.FileName));
                ShowToast("Updater", "Verified update host started. YOMI will relaunch after promotion.");
            }
            catch (Exception ex)
            {
                ShowToast("Updater", "Could not start update: " + ex.Message);
            }
        }

