        private static void FillCombo(ComboBox box, params string[] values)
        {
            box.Items.Clear(); foreach (string value in values) box.Items.Add(value);
        }
        private static void SetCombo(ComboBox box, string value) { box.SelectedItem = value; if (box.SelectedIndex < 0 && box.Items.Count > 0) box.SelectedIndex = 0; }
        private static void SetComboPreserve(ComboBox box, string value)
        {
            string wanted = value ?? "";
            if (wanted.Length > 0 && !box.Items.Cast<object>().Any(item => String.Equals(Convert.ToString(item, CultureInfo.InvariantCulture), wanted, StringComparison.OrdinalIgnoreCase))) box.Items.Add(wanted);
            box.SelectedItem = wanted;
            if (box.SelectedIndex < 0 && box.Items.Count > 0) box.SelectedIndex = 0;
        }
        private static string ComboText(ComboBox box, string fallback)
        {
            if (box == null) return fallback;
            string typed = box.IsEditable ? (box.Text ?? "").Trim() : "";
            if (!String.IsNullOrWhiteSpace(typed)) return typed;
            return box.SelectedItem == null ? fallback : Convert.ToString(box.SelectedItem, CultureInfo.InvariantCulture);
        }
        private static bool Checked(CheckBox box) { return box.IsChecked == true; }
        private static int ComboInt(ComboBox box, int fallback) { int n; return Int32.TryParse(ComboText(box, fallback.ToString(CultureInfo.InvariantCulture)), NumberStyles.Integer, CultureInfo.InvariantCulture, out n) ? n : fallback; }
        private static double ComboDouble(ComboBox box, double fallback) { double n; return Double.TryParse(ComboText(box, fallback.ToString(CultureInfo.InvariantCulture)), NumberStyles.Float, CultureInfo.InvariantCulture, out n) ? n : fallback; }

