        private void WireSettingsDirtyTracking()
        {
            ComboBox[] combos = new[] { _settingsAppMode, _settingsHistoryMax, _settingsAudioQuality, _settingsPlayerVideoQuality, _settingsTransitionPolicy, _settingsOverlayVideoQuality, _settingsVideoFps, _settingsCanvasWidth, _settingsCanvasHeight, _settingsMediaWidth, _settingsMediaHeight, _settingsSafeMargin, _settingsBroadcastPreset, _settingsOutput1Modules, _settingsOutput1Layout, _settingsOutput2Modules, _settingsOutput2Layout, _settingsOutput3Modules, _settingsOutput3Layout, _settingsOutput4Modules, _settingsOutput4Layout, _settingsTextSize, _settingsMinTextSize, _settingsTextGap, _settingsTextFont, _settingsTextColor, _settingsTextOutline, _settingsOutlineColor, _settingsTextOpacity, _settingsTextAlignment, _settingsTextSpacing, _settingsMediaBorderPx, _settingsMediaBorderColor, _settingsMediaCornerStyle, _settingsVisualizerFill, _settingsVisualizerActivity, _settingsVisualizerOpacity, _settingsVisualizerColorMode, _settingsVisualizerSolidColor, _settingsVisualizerFrequencyScale, _settingsVisualizerTrim, _settingsVisualizerLift, _settingsVisualizerShape, _settingsVisualizerSpacing, _settingsVisualizerFps, _settingsVisualizerLength, _settingsVisualizerDirection, _settingsVisualizerAnchor, _settingsVisualizerLayer, _settingsPrefetch, _settingsVideoPrefetch, _settingsCacheWorkers, _settingsBrowserFps, _settingsVisualizerInternalWidth, _settingsVisualizerInternalHeight, _settingsWorkspace, _settingsTheme, _settingsDetail };
            foreach (ComboBox combo in combos)
            {
                combo.SelectionChanged += delegate { MarkSettingsDirty("Unsaved changes."); };
                if (combo.IsEditable) combo.LostKeyboardFocus += delegate { MarkSettingsDirty("Unsaved changes."); };
            }
            CheckBox[] checks = new[] { _settingsHistoryEnabled, _settingsLoudness, _settingsArtwork, _settingsVideo, _settingsTitle, _settingsChannel, _settingsSmartArtworkCrop, _settingsAutoFitText, _settingsTextGlow, _settingsMediaBorderEnabled, _settingsVisualizerEnabled, _settingsVisualizerMatchText, _settingsDirectorMode, _settingsOutput1Enabled, _settingsOutput2Enabled, _settingsOutput3Enabled, _settingsOutput4Enabled, _settingsQuietSurface, _settingsClassicMenu, _settingsReduceMotion, _settingsAlwaysOnTop };
            foreach (CheckBox check in checks)
            {
                check.Checked += delegate { MarkSettingsDirty("Unsaved changes."); };
                check.Unchecked += delegate { MarkSettingsDirty("Unsaved changes."); };
            }
        }

        private void MarkSettingsDirty(string message)
        {
            if (_settingsPopulating || _settingsHistoryApplying) return;
            RecordSettingsDraftChange();
            string current = CaptureSettingsDraft();
            _settingsDirty = !String.Equals(current, _settingsBaselineSnapshot, StringComparison.Ordinal);
            if (_settingsSaveButton != null) _settingsSaveButton.IsEnabled = _settingsDirty;
            if (_settingsStatusText != null) _settingsStatusText.Text = _settingsDirty ? message : "Back to the saved settings.";
            UpdateSettingsHistoryButtons();
            RefreshObsQuickSetup();
        }

        private ComboBox[] SettingsDraftCombos()
        {
            return new[] { _settingsAppMode, _settingsHistoryMax, _settingsAudioQuality, _settingsPlayerVideoQuality, _settingsTransitionPolicy, _settingsOverlayVideoQuality, _settingsVideoFps, _settingsCanvasWidth, _settingsCanvasHeight, _settingsMediaWidth, _settingsMediaHeight, _settingsSafeMargin, _settingsBroadcastPreset, _settingsOutput1Modules, _settingsOutput1Layout, _settingsOutput2Modules, _settingsOutput2Layout, _settingsOutput3Modules, _settingsOutput3Layout, _settingsOutput4Modules, _settingsOutput4Layout, _settingsTextSize, _settingsMinTextSize, _settingsTextGap, _settingsTextFont, _settingsTextColor, _settingsTextOutline, _settingsOutlineColor, _settingsTextOpacity, _settingsTextAlignment, _settingsTextSpacing, _settingsMediaBorderPx, _settingsMediaBorderColor, _settingsMediaCornerStyle, _settingsVisualizerFill, _settingsVisualizerActivity, _settingsVisualizerOpacity, _settingsVisualizerColorMode, _settingsVisualizerSolidColor, _settingsVisualizerFrequencyScale, _settingsVisualizerTrim, _settingsVisualizerLift, _settingsVisualizerShape, _settingsVisualizerSpacing, _settingsVisualizerFps, _settingsVisualizerLength, _settingsVisualizerDirection, _settingsVisualizerAnchor, _settingsVisualizerLayer, _settingsPrefetch, _settingsVideoPrefetch, _settingsCacheWorkers, _settingsBrowserFps, _settingsVisualizerInternalWidth, _settingsVisualizerInternalHeight, _settingsWorkspace, _settingsTheme, _settingsDetail };
        }

        private CheckBox[] SettingsDraftChecks()
        {
            return new[] { _settingsHistoryEnabled, _settingsLoudness, _settingsArtwork, _settingsVideo, _settingsTitle, _settingsChannel, _settingsSmartArtworkCrop, _settingsAutoFitText, _settingsTextGlow, _settingsMediaBorderEnabled, _settingsVisualizerEnabled, _settingsVisualizerMatchText, _settingsDirectorMode, _settingsOutput1Enabled, _settingsOutput2Enabled, _settingsOutput3Enabled, _settingsOutput4Enabled, _settingsQuietSurface, _settingsClassicMenu, _settingsReduceMotion, _settingsAlwaysOnTop };
        }

        private string CaptureSettingsDraft()
        {
            try
            {
                var map = new SortedDictionary<string, object>(StringComparer.Ordinal);
                foreach (ComboBox combo in SettingsDraftCombos()) if (combo != null) map["combo:" + combo.Name] = ComboText(combo, "");
                foreach (CheckBox check in SettingsDraftChecks()) if (check != null) map["check:" + check.Name] = check.IsChecked == true;
                return _json.Serialize(map);
            }
            catch { return ""; }
        }

        private void PushSettingsHistory(Stack<string> stack, string snapshot)
        {
            if (stack == null || String.IsNullOrEmpty(snapshot)) return;
            if (stack.Count >= SettingsHistoryLimit)
            {
                string[] newestFirst = stack.ToArray();
                stack.Clear();
                foreach (string item in newestFirst.Take(SettingsHistoryLimit - 1).Reverse()) stack.Push(item);
            }
            stack.Push(snapshot);
        }

        private void RecordSettingsDraftChange()
        {
            if (_settingsPopulating || _settingsHistoryApplying) return;
            string current = CaptureSettingsDraft();
            if (String.IsNullOrEmpty(current)) return;
            if (String.IsNullOrEmpty(_settingsLastSnapshot)) { _settingsLastSnapshot = current; return; }
            if (String.Equals(current, _settingsLastSnapshot, StringComparison.Ordinal)) return;
            PushSettingsHistory(_settingsUndo, _settingsLastSnapshot);
            _settingsRedo.Clear();
            _settingsLastSnapshot = current;
        }

        private void UpdateSettingsHistoryButtons()
        {
            if (_settingsUndoButton != null) _settingsUndoButton.IsEnabled = _settingsUndo.Count > 0;
            if (_settingsRedoButton != null) _settingsRedoButton.IsEnabled = _settingsRedo.Count > 0;
        }

        private void ApplySettingsDraftSnapshot(string snapshot, string status)
        {
            if (String.IsNullOrWhiteSpace(snapshot)) return;
            Dictionary<string, object> map;
            try { map = AsMap(_json.DeserializeObject(snapshot)); } catch { return; }
            _settingsHistoryApplying = true;
            _settingsPopulating = true;
            try
            {
                foreach (ComboBox combo in SettingsDraftCombos())
                {
                    if (combo == null) continue; object raw;
                    if (map.TryGetValue("combo:" + combo.Name, out raw)) SetComboPreserve(combo, Convert.ToString(raw, CultureInfo.InvariantCulture));
                }
                foreach (CheckBox check in SettingsDraftChecks())
                {
                    if (check == null) continue; object raw;
                    if (map.TryGetValue("check:" + check.Name, out raw)) check.IsChecked = raw is bool ? (bool)raw : String.Equals(Convert.ToString(raw, CultureInfo.InvariantCulture), "true", StringComparison.OrdinalIgnoreCase);
                }
            }
            finally { _settingsPopulating = false; _settingsHistoryApplying = false; }
            _settingsLastSnapshot = CaptureSettingsDraft();
            _settingsDirty = !String.Equals(_settingsLastSnapshot, _settingsBaselineSnapshot, StringComparison.Ordinal);
            if (_settingsSaveButton != null) _settingsSaveButton.IsEnabled = _settingsDirty;
            if (_settingsStatusText != null) _settingsStatusText.Text = status + (_settingsDirty ? " Save to apply." : " You are back at the saved settings.");
            UpdateSettingsHistoryButtons();
            RefreshObsQuickSetup();
        }

        private void UndoSettingsDraft()
        {
            if (_settingsUndo.Count == 0) return;
            string current = CaptureSettingsDraft();
            PushSettingsHistory(_settingsRedo, current);
            string previous = _settingsUndo.Pop();
            ApplySettingsDraftSnapshot(previous, "Undid the last settings change.");
        }

        private void RedoSettingsDraft()
        {
            if (_settingsRedo.Count == 0) return;
            string current = CaptureSettingsDraft();
            PushSettingsHistory(_settingsUndo, current);
            string next = _settingsRedo.Pop();
            ApplySettingsDraftSnapshot(next, "Redid the settings change.");
        }

        private void RestoreDefaultSettingsDraft()
        {
            MessageBoxResult answer = MessageBox.Show(_window,
                "Restore YOMI settings to the factory defaults?\r\n\r\nYour playlist, favorites, history, cache, and library are not changed. You can Undo this settings change afterward.",
                "Restore default settings", MessageBoxButton.YesNo, MessageBoxImage.Warning, MessageBoxResult.No);
            if (answer != MessageBoxResult.Yes) return;
            string before = CaptureSettingsDraft();
            PopulateIntegratedSettings(true);
            string after = CaptureSettingsDraft();
            if (!String.Equals(before, after, StringComparison.Ordinal)) PushSettingsHistory(_settingsUndo, before);
            _settingsRedo.Clear();
            _settingsLastSnapshot = after;
            _settingsDirty = !String.Equals(after, _settingsBaselineSnapshot, StringComparison.Ordinal);
            if (_settingsSaveButton != null) _settingsSaveButton.IsEnabled = _settingsDirty;
            if (_settingsStatusText != null) _settingsStatusText.Text = "Factory defaults loaded into the draft. Save to apply, or Undo to go back.";
            UpdateSettingsHistoryButtons();
            RefreshObsQuickSetup();
        }

