        private static string OutputBundleToModules(string bundle)
        {
            switch ((bundle ?? "").Trim())
            {
                case "Thumbnail + text":
                case "Artwork + text": return "artwork,title,channel";
                case "Video + text": return "video,title,channel";
                case "Text only": return "title,channel";
                case "Thumbnail only":
                case "Artwork only": return "artwork";
                case "Video only": return "video";
                case "Visualizer only": return "visualizer";
                case "Thumbnail + visualizer":
                case "Artwork + visualizer": return "artwork,visualizer";
                case "Video + visualizer": return "video,visualizer";
                case "History": return "history";
                case "Full strip": return "artwork,video,title,channel,visualizer";
                default: return String.IsNullOrWhiteSpace(bundle) ? "artwork,video,title,channel,visualizer" : bundle.Trim();
            }
        }

        private static string ModulesToOutputBundle(string modules)
        {
            string normalized = String.Join(",", (modules ?? "").Split(',').Select(v => v.Trim().ToLowerInvariant()).Where(v => v.Length > 0));
            if (normalized == "artwork,title,channel" || normalized == "artwork,channel,title") return "Thumbnail + text";
            if (normalized == "video,title,channel" || normalized == "video,channel,title") return "Video + text";
            if (normalized == "title,channel" || normalized == "channel,title") return "Text only";
            if (normalized == "artwork") return "Thumbnail only";
            if (normalized == "video") return "Video only";
            if (normalized == "visualizer") return "Visualizer only";
            if (normalized == "artwork,visualizer" || normalized == "visualizer,artwork") return "Thumbnail + visualizer";
            if (normalized == "video,visualizer" || normalized == "visualizer,video") return "Video + visualizer";
            if (normalized == "history") return "History";
            if (normalized == "artwork,video,title,channel,visualizer") return "Full strip";
            return String.IsNullOrWhiteSpace(modules) ? "Full strip" : modules;
        }

        private Dictionary<string, object> DirectorOutput(Dictionary<string, object> config, int id)
        {
            foreach (object raw in GetList(config, "director_outputs"))
            {
                Dictionary<string, object> map = AsMap(raw);
                if (GetInt(map, "id", 0) == id) return map;
            }
            return EmptyMap();
        }

        private void LoadDirectorOutputDraft(Dictionary<string, object> config, int id, CheckBox enabled, ComboBox modules, ComboBox layout)
        {
            Dictionary<string, object> map = DirectorOutput(config, id);
            enabled.IsChecked = GetBool(map, "enabled", id == 1);
            SetComboPreserve(modules, ModulesToOutputBundle(GetString(map, "modules", id == 1 ? "artwork,video,title,channel,visualizer" : "")));
            SetComboPreserve(layout, GetString(map, "layout", "Horizontal"));
        }

        private List<object> BuildDirectorOutputs(Dictionary<string, object> config)
        {
            var output = new List<object>();
            var seen = new HashSet<int>();
            CheckBox[] enabled = new[] { _settingsOutput1Enabled, _settingsOutput2Enabled, _settingsOutput3Enabled, _settingsOutput4Enabled };
            ComboBox[] modules = new[] { _settingsOutput1Modules, _settingsOutput2Modules, _settingsOutput3Modules, _settingsOutput4Modules };
            ComboBox[] layout = new[] { _settingsOutput1Layout, _settingsOutput2Layout, _settingsOutput3Layout, _settingsOutput4Layout };
            for (int id = 1; id <= 4; id++)
            {
                Dictionary<string, object> map = DirectorOutput(config, id);
                if (map.Count == 0) map = EmptyMap(); else map = new Dictionary<string, object>(map, StringComparer.OrdinalIgnoreCase);
                map["id"] = id;
                map["enabled"] = enabled[id - 1].IsChecked == true;
                map["modules"] = OutputBundleToModules(ComboText(modules[id - 1], "Full strip"));
                map["layout"] = ComboText(layout[id - 1], "Horizontal");
                output.Add(map); seen.Add(id);
            }
            foreach (object raw in GetList(config, "director_outputs"))
            {
                Dictionary<string, object> map = AsMap(raw); int id = GetInt(map, "id", 0);
                if (id > 0 && !seen.Contains(id)) output.Add(map);
            }
            return output;
        }

        private void ApplyBroadcastPresetDraft(string preset)
        {
            if (_settingsPopulating || String.IsNullOrWhiteSpace(preset) || String.Equals(preset, "Custom", StringComparison.OrdinalIgnoreCase)) return;
            _settingsPopulating = true;
            try
            {
                if (String.Equals(preset, "Classic strip", StringComparison.OrdinalIgnoreCase))
                {
                    _settingsDirectorMode.IsChecked = false; _settingsArtwork.IsChecked = true; _settingsVideo.IsChecked = true; _settingsTitle.IsChecked = true; _settingsChannel.IsChecked = true; _settingsVisualizerEnabled.IsChecked = true;
                }
                else if (String.Equals(preset, "Split sources", StringComparison.OrdinalIgnoreCase))
                {
                    _settingsDirectorMode.IsChecked = true;
                    _settingsOutput1Enabled.IsChecked = true; SetComboPreserve(_settingsOutput1Modules, "Thumbnail only"); SetComboPreserve(_settingsOutput1Layout, "Horizontal");
                    _settingsOutput2Enabled.IsChecked = true; SetComboPreserve(_settingsOutput2Modules, "Video only"); SetComboPreserve(_settingsOutput2Layout, "Horizontal");
                    _settingsOutput3Enabled.IsChecked = true; SetComboPreserve(_settingsOutput3Modules, "Text only"); SetComboPreserve(_settingsOutput3Layout, "Horizontal");
                    _settingsOutput4Enabled.IsChecked = true; SetComboPreserve(_settingsOutput4Modules, "Visualizer only"); SetComboPreserve(_settingsOutput4Layout, "Horizontal");
                }
                else if (String.Equals(preset, "Text + artwork", StringComparison.OrdinalIgnoreCase))
                {
                    _settingsDirectorMode.IsChecked = true;
                    _settingsOutput1Enabled.IsChecked = true; SetComboPreserve(_settingsOutput1Modules, "Thumbnail + text"); SetComboPreserve(_settingsOutput1Layout, "Horizontal");
                    _settingsOutput2Enabled.IsChecked = false; _settingsOutput3Enabled.IsChecked = false; _settingsOutput4Enabled.IsChecked = false;
                }
                else if (String.Equals(preset, "Visual focus", StringComparison.OrdinalIgnoreCase))
                {
                    _settingsDirectorMode.IsChecked = true;
                    _settingsOutput1Enabled.IsChecked = true; SetComboPreserve(_settingsOutput1Modules, "Thumbnail + visualizer"); SetComboPreserve(_settingsOutput1Layout, "Horizontal");
                    _settingsOutput2Enabled.IsChecked = true; SetComboPreserve(_settingsOutput2Modules, "Text only"); SetComboPreserve(_settingsOutput2Layout, "Horizontal");
                    _settingsOutput3Enabled.IsChecked = false; _settingsOutput4Enabled.IsChecked = false;
                }
            }
            finally { _settingsPopulating = false; }
            MarkSettingsDirty("Broadcast preset loaded into the draft - save to apply.");
        }

        private void SetDirectorOutputConfig(Dictionary<string, object> config, int id, bool enabled, string modules, string layout)
        {
            var outputs = new List<object>();
            bool found = false;
            foreach (object raw in GetList(config, "director_outputs"))
            {
                Dictionary<string, object> map = AsMap(raw);
                if (GetInt(map, "id", 0) == id)
                {
                    map = new Dictionary<string, object>(map, StringComparer.OrdinalIgnoreCase);
                    map["id"] = id; map["enabled"] = enabled;
                    if (modules != null) map["modules"] = modules;
                    if (layout != null) map["layout"] = layout;
                    found = true;
                }
                outputs.Add(map);
            }
            if (!found)
            {
                var map = new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase)
                {
                    { "id", id }, { "enabled", enabled }, { "modules", modules ?? "" }, { "layout", layout ?? "Horizontal" }
                };
                outputs.Add(map);
            }
            config["director_outputs"] = outputs;
        }

        private void ApplyBroadcastPresetToConfig(Dictionary<string, object> config, string requestedPreset)
        {
            if (config == null) throw new ArgumentNullException("config");
            string preset = NormalizeSlotBroadcastPreset(requestedPreset);
            if (String.Equals(preset, "Keep current", StringComparison.OrdinalIgnoreCase)) return;
            config["overlay_preset"] = preset;
            if (String.Equals(preset, "Classic strip", StringComparison.OrdinalIgnoreCase))
            {
                config["director_mode"] = false; config["artwork_enabled"] = true; config["video_enabled"] = true; config["title_enabled"] = true; config["channel_enabled"] = true; config["visualizer_enabled"] = true;
            }
            else if (String.Equals(preset, "Split sources", StringComparison.OrdinalIgnoreCase))
            {
                config["director_mode"] = true;
                SetDirectorOutputConfig(config, 1, true, "artwork", "Horizontal");
                SetDirectorOutputConfig(config, 2, true, "video", "Horizontal");
                SetDirectorOutputConfig(config, 3, true, "title,channel", "Horizontal");
                SetDirectorOutputConfig(config, 4, true, "visualizer", "Horizontal");
            }
            else if (String.Equals(preset, "Text + artwork", StringComparison.OrdinalIgnoreCase))
            {
                config["director_mode"] = true;
                SetDirectorOutputConfig(config, 1, true, "artwork,title,channel", "Horizontal");
                SetDirectorOutputConfig(config, 2, false, null, null); SetDirectorOutputConfig(config, 3, false, null, null); SetDirectorOutputConfig(config, 4, false, null, null);
            }
            else if (String.Equals(preset, "Visual focus", StringComparison.OrdinalIgnoreCase))
            {
                config["director_mode"] = true;
                SetDirectorOutputConfig(config, 1, true, "artwork,visualizer", "Horizontal");
                SetDirectorOutputConfig(config, 2, true, "title,channel", "Horizontal");
                SetDirectorOutputConfig(config, 3, false, null, null); SetDirectorOutputConfig(config, 4, false, null, null);
            }
        }

        private string ApplyIntegratedConfigTransaction(Dictionary<string, object> config)
        {
            if (config == null || config.Count == 0) throw new InvalidOperationException("The settings candidate is empty.");
            Directory.CreateDirectory(_stateRoot);
            string token = Guid.NewGuid().ToString("N");
            string candidate = Path.Combine(_stateRoot, "settings-candidate-" + token + ".json");
            string result = Path.Combine(_stateRoot, "settings-result-" + token + ".json");
            var serializer = new JavaScriptSerializer();
            WriteUtf8NoBom(candidate, serializer.Serialize(config));
            try
            {
                string script = Path.Combine(_appDir, "apply-integrated-settings.ps1");
                if (!File.Exists(script))
                {
                    // R61.69 focused packages may sit on installations predating the integrated helper.
                    // Never make appearance/UI settings depend on a missing external script. Commit the
                    // complete validated candidate atomically on this worker thread and retain a previous
                    // copy for recovery. Runtime-sensitive settings naturally take effect on the next
                    // engine/config observation; controller-side theme/layout state applies immediately.
                    string configPath = Path.Combine(_dataRoot, "config.json");
                    string previousPath = Path.Combine(_stateRoot, "config-before-integrated-save.json");
                    try
                    {
                        if (File.Exists(configPath)) File.Copy(configPath, previousPath, true);
                        WriteUtf8NoBom(configPath, serializer.Serialize(config));
                        try { File.Delete(Path.Combine(_stateRoot, "config-pending.json")); } catch { }
                        try { File.Delete(Path.Combine(_stateRoot, "config-pending-conflict.json")); } catch { }
                        _jsonCache.Clear();
                    }
                    catch (Exception ex)
                    {
                        throw new InvalidOperationException("YOMI could not commit settings atomically: " + ex.Message, ex);
                    }
                    if (_running) SendMpv("script-message", "yomi-reload-config");
                    return "APPLIED";
                }
                string ps = Path.Combine(Environment.SystemDirectory, @"WindowsPowerShell\v1.0\powershell.exe");
                var psi = new ProcessStartInfo { FileName=ps, Arguments="-NoProfile -ExecutionPolicy Bypass -File " + Quote(script) + " -CandidatePath " + Quote(candidate) + " -ResultPath " + Quote(result), WorkingDirectory=_appDir, UseShellExecute=false, CreateNoWindow=true, WindowStyle=ProcessWindowStyle.Hidden };
                using (Process proc = Process.Start(psi))
                {
                    if (proc == null) throw new InvalidOperationException("YOMI could not start the settings helper.");
                    if (!proc.WaitForExit(12000)) { try { proc.Kill(); } catch { } throw new TimeoutException("The settings helper timed out and was stopped."); }
                    if (proc.ExitCode != 0) throw new InvalidOperationException("The settings helper exited with code " + proc.ExitCode + ".");
                }
                if (!File.Exists(result)) throw new InvalidOperationException("The settings helper returned no result.");
                Dictionary<string, object> r = AsMap(serializer.DeserializeObject(ReadTextShared(result)));
                if (!String.Equals(GetString(r, "status", ""), "PASS", StringComparison.OrdinalIgnoreCase)) throw new InvalidOperationException(GetString(r, "message", "The settings transaction did not report PASS."));
                string action = GetString(r, "action", "");
                if (String.IsNullOrWhiteSpace(action)) throw new InvalidOperationException("The settings transaction returned no action.");

                string liveConfigPath = Path.Combine(_dataRoot, "config.json");
                WriteUtf8NoBom(liveConfigPath, serializer.Serialize(config));
                try { File.Delete(Path.Combine(_stateRoot, "config-pending.json")); } catch { }
                try { File.Delete(Path.Combine(_stateRoot, "config-pending-conflict.json")); } catch { }
                _jsonCache.Clear();
                if (_running) SendMpv("script-message", "yomi-reload-config");
                return "APPLIED";
            }
            finally { try { File.Delete(candidate); File.Delete(result); } catch { } }
        }

        private bool TryApplySlotBroadcastAffinity(SlotRecord slot, out string note)
        {
            note = "";
            if (!_slotBroadcastFollowEnabled || slot == null) return true;
            string preset = NormalizeSlotBroadcastPreset(slot.BroadcastPreset);
            if (String.Equals(preset, "Keep current", StringComparison.OrdinalIgnoreCase)) return true;
            try
            {
                Dictionary<string, object> config = ReadJsonFresh(Path.Combine(_dataRoot, "config.json"));
                if (config.Count == 0) config = ReadJsonFresh(Path.Combine(_appDir, "default-config.json"));
                ApplyBroadcastPresetToConfig(config, preset);
                string action = ApplyIntegratedConfigTransaction(config);
                note = "Layout: " + preset + (String.Equals(action, "NOOP", StringComparison.OrdinalIgnoreCase) ? "" : ".");
                AddActivity("Listening slot", "broadcast layout " + preset + " | " + action.ToLowerInvariant());
                return true;
            }
            catch (Exception ex)
            {
                note = "Preferred layout could not be applied; the current OBS layout was kept.";
                AddActivity("Listening slot", "broadcast layout preference failed | " + ex.GetType().Name);
                return false;
            }
        }

