                new SettingsSearchTarget { TabIndex=2, Path="Performance > Broadcast rendering", Label="Browser Source FPS", Aliases="obs fps|browser fps|browser source frame rate|60 fps|30 fps|auto fps", Control=_settingsBrowserFps },
                new SettingsSearchTarget { TabIndex=2, Path="Performance > Broadcast rendering", Label="Visualizer analysis width", Aliases="visualizer resolution|viz internal width|signal width|analysis width", Control=_settingsVisualizerInternalWidth },
                new SettingsSearchTarget { TabIndex=2, Path="Performance > Broadcast rendering", Label="Visualizer analysis height", Aliases="visualizer resolution|viz internal height|signal height|analysis height", Control=_settingsVisualizerInternalHeight }
            };
        }

        private static int ScoreSettingsSearch(SettingsSearchTarget target, string query)
        {
            string q = (query ?? "").Trim().ToLowerInvariant();
            if (q.Length == 0 || target == null) return 0;

            // R61.6: broad one-word category searches must not silently jump to whichever
            // label happens to begin with that word. Example: "video" previously selected
            // Advanced > Videos to prepare because the prefix score (100) outranked
            // Player video / Overlay video / quality / source-frame-rate terminology.
            // Exact names and exact aliases still win; otherwise one-word label hits share
            // the same score so the UI can truthfully report ambiguity and ask for refinement.
            bool broadOneWord = q.IndexOf(' ') < 0 && q.IndexOf('\t') < 0;
            int score = 0;
            string label = (target.Label ?? "").ToLowerInvariant();
            if (label == q) score = Math.Max(score, 120);
            else if (broadOneWord && label.IndexOf(q, StringComparison.Ordinal) >= 0) score = Math.Max(score, 80);
            else if (label.StartsWith(q, StringComparison.Ordinal)) score = Math.Max(score, 100);
            else if (label.IndexOf(q, StringComparison.Ordinal) >= 0) score = Math.Max(score, 80);

            string[] aliases = (target.Aliases ?? "").Split('|');
            foreach (string raw in aliases)
            {
                string alias = raw.Trim().ToLowerInvariant();
                if (alias == q) score = Math.Max(score, 110);
                else if (broadOneWord && alias.IndexOf(q, StringComparison.Ordinal) >= 0) score = Math.Max(score, 70);
                else if (alias.StartsWith(q, StringComparison.Ordinal)) score = Math.Max(score, 90);
                else if (alias.IndexOf(q, StringComparison.Ordinal) >= 0) score = Math.Max(score, 70);
            }

            string path = (target.Path ?? "").ToLowerInvariant();
            if (path.IndexOf(q, StringComparison.Ordinal) >= 0) score = Math.Max(score, 50);
            return score;
        }

        private static string DescribeSettingsSearchMatch(string query, SettingsSearchMatch match)
        {
            if (match == null) return "query='" + (query ?? "") + "' match=<null>";
            string primary = match.Target == null ? "<none>" : match.Target.Path + " > " + match.Target.Label;
            string alternate = match.Alternate == null ? "<none>" : match.Alternate.Path + " > " + match.Alternate.Label;
            return "query='" + (query ?? "") + "' target='" + primary + "' score=" + match.Score.ToString(CultureInfo.InvariantCulture) +
                   " ambiguous=" + match.Ambiguous.ToString() + " alternate='" + alternate + "'";
        }

        private SettingsSearchMatch FindSettingsMatch(string query)
        {
            var match = new SettingsSearchMatch();
            SettingsSearchTarget[] targets = SettingsSearchTargets();
            int best = 0;
            foreach (SettingsSearchTarget target in targets)
            {
                int score = ScoreSettingsSearch(target, query);
                if (score <= 0) continue;
                if (score > best)
                {
                    best = score;
                    match.Target = target;
                    match.Alternate = null;
                    match.Ambiguous = false;
                    match.Score = score;
                }
                else if (score == best && match.Target != null)
                {
                    match.Ambiguous = true;
                    if (match.Alternate == null) match.Alternate = target;
                }
            }
            return match;
        }

        private void UpdateSettingsSearchHint()
        {
            if (_settingsSearchBox == null) return;
            bool empty = String.IsNullOrWhiteSpace(_settingsSearchBox.Text);
            _settingsSearchPlaceholder.Visibility = empty ? Visibility.Visible : Visibility.Collapsed;
            _settingsSearchClearButton.Visibility = empty ? Visibility.Collapsed : Visibility.Visible;
            if (empty)
            {
                _settingsStatusText.Text = _settingsDirty ? "Unsaved changes." : "Everyday controls first. Broadcast presentation second. Performance/resource policy last.";
                return;
            }
            SettingsSearchMatch match = FindSettingsMatch(_settingsSearchBox.Text);
            if (match.Target == null)
            {
                _settingsStatusText.Text = "No direct match yet. Try OBS canvas, media size, artwork crop, visualizer, browser FPS, prefetch, or buffer.";
                return;
            }
            if (match.Ambiguous && match.Alternate != null)
            {
                _settingsStatusText.Text = "More than one match - " + match.Target.Path + " > " + match.Target.Label + " | " + match.Alternate.Path + " > " + match.Alternate.Label + ". Type a little more.";
                return;
            }
            _settingsStatusText.Text = match.Target.Path + " > " + match.Target.Label + " - press Enter to go there.";
        }

        private void ApplySettingsSearch()
        {
            SettingsSearchMatch match = FindSettingsMatch(_settingsSearchBox.Text);
            if (match.Target == null || match.Ambiguous || match.Target.TabIndex < 0 || match.Target.TabIndex >= _settingsTabs.Items.Count)
            {
                UpdateSettingsSearchHint();
                return;
            }
            _settingsTabs.SelectedIndex = match.Target.TabIndex;
            SettingsSearchTarget target = match.Target;
            _settingsStatusText.Text = target.Path + " > " + target.Label;
            _window.Dispatcher.BeginInvoke(new Action(delegate
            {
                try
                {
                    if (target.Control != null)
                    {
                        ExpandSettingsAncestors(target.Control);
                        target.Control.BringIntoView();
                        target.Control.Focus();
                    }
                }
                catch { }
            }), DispatcherPriority.Background);
        }

        public bool SelfTestSettingsHierarchy()
        {
            _selfTestFailureDetail = "";
            try
            {
                if (_settingsTabs == null || _settingsTabs.Items.Count != 3) return SelfTestFail("SelfTestSettingsHierarchy assertion 1: expected 3 tabs; actual " + (_settingsTabs == null ? "<null>" : _settingsTabs.Items.Count.ToString(CultureInfo.InvariantCulture)));
                string[] expected = new[] { "Everyday", "Broadcast", "Performance" };
                for (int i = 0; i < expected.Length; i++)
                {
                    TabItem tab = _settingsTabs.Items[i] as TabItem;
                    string actual = tab == null ? "<null>" : Convert.ToString(tab.Header, CultureInfo.InvariantCulture);
                    if (tab == null || !String.Equals(actual, expected[i], StringComparison.Ordinal)) return SelfTestFail("SelfTestSettingsHierarchy assertion 2: tab " + i.ToString(CultureInfo.InvariantCulture) + " expected='" + expected[i] + "' actual='" + actual + "'");
                }
                SettingsSearchMatch audio = FindSettingsMatch("audio quality");
                if (audio.Target == null || audio.Ambiguous || audio.Target.TabIndex != 0 || audio.Target.Control != _settingsAudioQuality) return SelfTestFail("SelfTestSettingsHierarchy assertion 3: " + DescribeSettingsSearchMatch("audio quality", audio));
                SettingsSearchMatch workers = FindSettingsMatch("workers");
                if (workers.Target == null || workers.Ambiguous || workers.Target.TabIndex != 2 || workers.Target.Control != _settingsCacheWorkers) return SelfTestFail("SelfTestSettingsHierarchy assertion 4: " + DescribeSettingsSearchMatch("workers", workers));
                SettingsSearchMatch video = FindSettingsMatch("video");
                if (video.Target == null || !video.Ambiguous) return SelfTestFail("SelfTestSettingsHierarchy assertion 5: broad video search must be ambiguous; " + DescribeSettingsSearchMatch("video", video));
                SettingsSearchMatch playerVideo = FindSettingsMatch("player video");
                if (playerVideo.Target == null || playerVideo.Ambiguous || playerVideo.Target.Control != _settingsPlayerVideoQuality) return SelfTestFail("SelfTestSettingsHierarchy assertion 6: " + DescribeSettingsSearchMatch("player video", playerVideo));
                SettingsSearchMatch overlayVideo = FindSettingsMatch("overlay video");
                if (overlayVideo.Target == null || overlayVideo.Ambiguous || overlayVideo.Target.Control != _settingsVideo) return SelfTestFail("SelfTestSettingsHierarchy assertion 7: " + DescribeSettingsSearchMatch("overlay video", overlayVideo));
                SettingsSearchMatch font = FindSettingsMatch("font");
                if (font.Target == null || font.Ambiguous || font.Target.Control != _settingsTextFont) return SelfTestFail("SelfTestSettingsHierarchy assertion 8: restored font control is not searchable; " + DescribeSettingsSearchMatch("font", font));
                SettingsSearchMatch videoPrefetch = FindSettingsMatch("video prefetch");
                if (videoPrefetch.Target == null || videoPrefetch.Ambiguous || videoPrefetch.Target.Control != _settingsPrefetch) return SelfTestFail("SelfTestSettingsHierarchy assertion 9: retired video-prefetch vocabulary did not resolve to the live preparation control; " + DescribeSettingsSearchMatch("video prefetch", videoPrefetch));
                Expander performanceAdvanced = _window.FindName("SettingsPerformanceAdvancedExpander") as Expander;
                if (performanceAdvanced == null || performanceAdvanced.IsExpanded) return SelfTestFail("SelfTestSettingsHierarchy assertion 10: advanced Performance controls must exist and start collapsed");
                if (_settingsSectionText == null || _settingsEverydayScroll == null || _settingsSectionEverydayUse == null || _settingsSectionBroadcastSetup == null || _settingsSectionPerformancePreparation == null) return SelfTestFail("SelfTestSettingsHierarchy assertion 11: settings section visual tree incomplete");
                return true;
            }
            catch (Exception ex) { return SelfTestFail("SelfTestSettingsHierarchy assertion 12 exception: " + ex.GetType().Name + ": " + ex.Message); }
        }

        public bool SelfTestQueueConfidence()
        {
            _selfTestFailureDetail = "";
            try
            {
                var full = new RuntimeQueueItem { Audio="READY", Artwork="READY", Video="READY", Visualizer="READY", TransitionReady=true, PresentationComplete=true };
                string fullNote = QueueConfidenceNote("READY", "FULL READY", full, 2);
                if (!String.IsNullOrWhiteSpace(fullNote)) return SelfTestFail("SelfTestQueueConfidence assertion 1: expected empty note; actual='" + fullNote + "'");
                var audioReady = new RuntimeQueueItem { Audio="READY", Artwork="ACTIVE", Video="NOT_REQUIRED", Visualizer="NOT_REQUIRED", TransitionReady=true, PresentationComplete=false };
                string audioReadyNote = QueueConfidenceNote("AUDIO READY", "AUDIO READY", audioReady, 2);
                if (audioReadyNote.IndexOf("artwork is still catching up", StringComparison.OrdinalIgnoreCase) < 0) return SelfTestFail("SelfTestQueueConfidence assertion 2: expected specific artwork waiting note; actual='" + audioReadyNote + "'");
                var late = new RuntimeQueueItem { Audio="READY", Artwork="ACTIVE", HasSlack=true, SlackSeconds=-8, TransitionReady=false };
                string lateNote = QueueConfidenceNote("BUILDING", "SLACK -8s", late, 2);
                if (lateNote.IndexOf("audio remains priority", StringComparison.OrdinalIgnoreCase) < 0) return SelfTestFail("SelfTestQueueConfidence assertion 3: actual='" + lateNote + "'");
                var isolated = new RuntimeQueueItem { Audio="READY", Artwork="DEFERRED_CIRCUIT", TransitionReady=true, PresentationComplete=true };
                string isolatedNote = QueueConfidenceNote("ISOLATED READY", "ISOLATED READY", isolated, 2);
                if (isolatedNote.IndexOf("fault contained", StringComparison.OrdinalIgnoreCase) < 0) return SelfTestFail("SelfTestQueueConfidence assertion 4: actual='" + isolatedNote + "'");
                var fallback = new RuntimeQueueItem { Audio="READY", Artwork="READY", Video="READY", Visualizer="READY", TransitionReady=true, PresentationComplete=true, VideoFallback=true, VideoActualHeight=360 };
                string fallbackNote = QueueConfidenceNote("READY", "FULL READY", fallback, 2);
                if (fallbackNote.IndexOf("360p", StringComparison.OrdinalIgnoreCase) < 0) return SelfTestFail("SelfTestQueueConfidence assertion 5: actual='" + fallbackNote + "'");
                string playedNote = QueueConfidenceNote("PLAYED", "", late, -1);
                if (!String.IsNullOrWhiteSpace(playedNote)) return SelfTestFail("SelfTestQueueConfidence assertion 6: expected empty note; actual='" + playedNote + "'");
                return true;
            }
            catch (Exception ex) { return SelfTestFail("SelfTestQueueConfidence assertion 7 exception: " + ex.GetType().Name + ": " + ex.Message); }
        }

        public void OpenSettingsInitial() { OpenIntegratedSettings(); }

        private void OpenSettingsTab(int tabIndex, FrameworkElement focus, string status)
        {
            OpenIntegratedSettings();
            if (_settingsTabs != null && tabIndex >= 0 && tabIndex < _settingsTabs.Items.Count) _settingsTabs.SelectedIndex = tabIndex;
            if (!String.IsNullOrWhiteSpace(status) && _settingsStatusText != null) _settingsStatusText.Text = status;
            if (focus != null)
            {
                ExpandSettingsAncestors(focus);
                _window.Dispatcher.BeginInvoke(new Action(delegate
                {
                    try { ExpandSettingsAncestors(focus); focus.BringIntoView(); focus.Focus(); } catch { }
                }), DispatcherPriority.Background);
            }
        }

        private static void ExpandSettingsAncestors(FrameworkElement focus)
        {
            DependencyObject current = focus;
            for (int guard = 0; current != null && guard < 32; guard++)
            {
                Expander expander = current as Expander;
                if (expander != null) expander.IsExpanded = true;
                DependencyObject next = null;
                try { next = LogicalTreeHelper.GetParent(current); } catch { }
                if (next == null)
                {
                    try { next = VisualTreeHelper.GetParent(current); } catch { }
                }
                current = next;
            }
        }

