        private static double EffectiveFullWidthFloor(Rect work)
        {
            // R61.67 fluid desktop contract: the full player is allowed to become genuinely compact.
            // Individual controls own their own irreducible minimums; the shell should not reserve dead width.
            return Math.Min(FullPlayerMinWidth, Math.Max(640.0, work.Width));
        }

        private static double EffectiveFullHeightFloor(Rect work)
        {
            return Math.Min(FullPlayerMinHeight, Math.Max(FullPlayerMinHeight, work.Height));
        }

        private void ExpandCompactHostForOverlay()
        {
            if (_overlayExpandedCompactHost || _window.WindowState != WindowState.Normal) return;
            Rect work = CurrentWorkAreaDips();
            // R61.48: tool surfaces are workstation surfaces. They grow the host deliberately,
            // independently of Mini/compact player geometry, then restore it exactly on close.
            double targetWidth = Math.Min(ToolHostPreferredWidth, Math.Max(760.0, work.Width - 24));
            double targetHeight = Math.Min(ToolHostPreferredHeight, Math.Max(500.0, work.Height - 24));
            if (!_miniMode && _window.ActualWidth >= targetWidth - 1 && _window.ActualHeight >= targetHeight - 1) return;
            _overlayExpandedCompactHost = true;
            _overlayHostWidth = _window.Width; _overlayHostHeight = _window.Height;
            _overlayHostLeft = _window.Left; _overlayHostTop = _window.Top;
            _overlayHostMinWidth = _window.MinWidth; _overlayHostMinHeight = _window.MinHeight;
            double width = targetWidth;
            double height = targetHeight;
            _internalGeometryChange = true;
            try
            {
                _window.MinWidth = Math.Min(EffectiveFullWidthFloor(work), width);
                _window.MinHeight = Math.Min(EffectiveFullHeightFloor(work), height);
                _window.Width = width; _window.Height = height;
                _window.Left = Math.Max(work.Left, Math.Min(_overlayHostLeft, work.Right - width));
                _window.Top = Math.Max(work.Top, Math.Min(_overlayHostTop, work.Bottom - height));
            }
            finally { _internalGeometryChange = false; }
            ApplyCompactLayoutForSize();
        }

        private void RestoreCompactHostAfterOverlay()
        {
            if (!_overlayExpandedCompactHost) return;
            _overlayExpandedCompactHost = false;
            if (_window.WindowState != WindowState.Normal) return;
            Rect work = CurrentWorkAreaDips();
            double width = Math.Max(1, _overlayHostWidth);
            double height = Math.Max(1, _overlayHostHeight);
            _internalGeometryChange = true;
            try
            {
                _window.MinWidth = _overlayHostMinWidth > 0 ? _overlayHostMinWidth : (_miniMode ? MicroPlayerMinWidth : EffectiveFullWidthFloor(CurrentWorkAreaDips()));
                _window.MinHeight = _overlayHostMinHeight > 0 ? _overlayHostMinHeight : (_miniMode ? MicroPlayerMinHeight : EffectiveFullHeightFloor(CurrentWorkAreaDips()));
                _window.Width = width; _window.Height = height;
                _window.Left = Math.Max(work.Left, Math.Min(_overlayHostLeft, work.Right - width));
                _window.Top = Math.Max(work.Top, Math.Min(_overlayHostTop, work.Bottom - height));
            }
            finally { _internalGeometryChange = false; }
            ApplyCompactLayoutForSize();
        }

        private void CaptureSettingsNavigationMemory()
        {
            if (_settingsTabs != null) _settingsRememberedTab = Math.Max(0, Math.Min(2, _settingsTabs.SelectedIndex));
            if (_settingsEverydayScroll != null) _settingsRememberedEverydayOffset = Math.Max(0.0, _settingsEverydayScroll.VerticalOffset);
            if (_settingsBroadcastScroll != null) _settingsRememberedBroadcastOffset = Math.Max(0.0, _settingsBroadcastScroll.VerticalOffset);
            if (_settingsPerformanceScroll != null) _settingsRememberedPerformanceOffset = Math.Max(0.0, _settingsPerformanceScroll.VerticalOffset);
        }

        private void RestoreSettingsNavigationMemory()
        {
            if (_settingsTabs == null) return;
            _settingsTabs.SelectedIndex = Math.Max(0, Math.Min(2, _settingsRememberedTab));
            _window.Dispatcher.BeginInvoke(DispatcherPriority.ContextIdle, new Action(delegate
            {
                if (_settingsOverlay == null || _settingsOverlay.Visibility != Visibility.Visible) return;
                if (_settingsEverydayScroll != null) _settingsEverydayScroll.ScrollToVerticalOffset(Math.Max(0.0, _settingsRememberedEverydayOffset));
                if (_settingsBroadcastScroll != null) _settingsBroadcastScroll.ScrollToVerticalOffset(Math.Max(0.0, _settingsRememberedBroadcastOffset));
                if (_settingsPerformanceScroll != null) _settingsPerformanceScroll.ScrollToVerticalOffset(Math.Max(0.0, _settingsRememberedPerformanceOffset));
                UpdateSettingsContextBand();
                ScheduleSettingsSectionCartography();
            }));
        }

        private void OpenIntegratedSettings()
        {
            // R47: reopening an already-open Settings surface must never reload and destroy its draft.
            if (_settingsOverlay.Visibility == Visibility.Visible)
            {
                _window.Activate();
                return;
            }
            if (!PrepareAuthoringSurface(AuthoringSurfaceKind.Settings, "Settings")) return;
            _settingsReturnFocus = Keyboard.FocusedElement;
            if (_miniMode || (!_queueOpen && _window.WindowState == WindowState.Normal && _window.ActualHeight <= CompactControllerMaxHeight + 60.0)) ExpandCompactHostForOverlay();
            PopulateIntegratedSettings(false);
            _settingsUndo.Clear(); _settingsRedo.Clear();
            _settingsBaselineSnapshot = CaptureSettingsDraft();
            _settingsLastSnapshot = _settingsBaselineSnapshot;
            UpdateSettingsHistoryButtons();
            _settingsOverlay.Visibility = Visibility.Visible;
            RestoreSettingsNavigationMemory();
            UpdateSettingsContextBand();
            ScheduleSettingsSectionCartography();
            SyncHostedMediaAirspace();
            var selectedTab = _settingsTabs.SelectedItem as TabItem;
            if (selectedTab != null) selectedTab.Focus(); else _settingsTabs.Focus();
        }

        private void CloseIntegratedSettings()
        {
            bool discardedDraft = _settingsDirty;
            CaptureSettingsNavigationMemory();
            _settingsOverlay.Visibility = Visibility.Collapsed;
            SyncHostedMediaAirspace();
            RestoreCompactHostAfterOverlay();
            _settingsDirty = false;
            if (_settingsSaveButton != null) _settingsSaveButton.IsEnabled = false;
            if (_settingsStatusText != null) _settingsStatusText.Text = "";
            if (discardedDraft)
            {
                Dictionary<string, object> saved = ReadJsonCached(Path.Combine(_dataRoot, "config.json"));
                string savedShape = GetString(saved, "visualizer_shape", "Spectrum");
                if (!String.Equals(savedShape, _visualizerShape, StringComparison.OrdinalIgnoreCase))
                {
                    _visualizerShape = savedShape;
                    if (!_performanceWorkspace && _visualizerEnabled && !String.IsNullOrWhiteSpace(_lastVizPath)) StartFramePreview(_lastVizPath, _timePosition, true);
                }
            }
            IInputElement restore = _settingsReturnFocus;
            _settingsReturnFocus = null;
            RestoreKeyboardFocus(restore);
            SaveUiState();
            if (discardedDraft) ShowToast("Settings", "Unsaved changes discarded");
        }

        private void UpdateSettingsContextBand()
        {
            if (_settingsTabs == null || _settingsContextIndexText == null || _settingsContextTitleText == null || _settingsContextDescriptionText == null) return;
            int index = Math.Max(0, _settingsTabs.SelectedIndex);
            string title;
            string description;
            switch (index)
            {
                case 1:
                    title = "Broadcast";
                    description = "OBS output, layout, visualizer, and Browser Source settings.";
                    break;
                case 2:
                    title = "Performance";
                    description = "Preparation, rendering cost, and background-work limits.";
                    break;
                default:
                    title = "Everyday";
                    description = "Playback, interface, and listening-memory settings.";
                    index = 0;
                    break;
            }
            _settingsContextIndexText.Text = (index + 1).ToString("00", CultureInfo.InvariantCulture) + " / " + _settingsTabs.Items.Count.ToString("00", CultureInfo.InvariantCulture);
            _settingsContextTitleText.Text = title;
            _settingsContextDescriptionText.Text = description;
            if (_settingsContextNodeEveryday != null) _settingsContextNodeEveryday.Opacity = index == 0 ? 0.82 : 0.14;
            if (_settingsContextNodeBroadcast != null) _settingsContextNodeBroadcast.Opacity = index == 1 ? 0.82 : 0.14;
            if (_settingsContextNodePerformance != null) _settingsContextNodePerformance.Opacity = index == 2 ? 0.82 : 0.14;
            UpdateSettingsSectionCartography();
        }

        private void CurrentSettingsSections(out ScrollViewer scroller, out List<FrameworkElement> elements, out List<string> labels)
        {
            int tab = Math.Max(0, _settingsTabs == null ? 0 : _settingsTabs.SelectedIndex);
            FrameworkElement[] rawElements; string[] rawLabels;
            if (tab == 1)
            {
                scroller = _settingsBroadcastScroll;
                rawElements = new[] { _settingsSectionBroadcastSetup, _settingsSectionBroadcastComposition, _settingsSectionBroadcastOverlay, _settingsSectionBroadcastGeometry, _settingsSectionBroadcastText, _settingsSectionBroadcastVisualizer };
                rawLabels = new[] { "SETUP", "COMPOSITION", "OVERLAY", "GEOMETRY", "TEXT", "VISUALIZER" };
            }
            else if (tab == 2)
            {
                scroller = _settingsPerformanceScroll;
                rawElements = new[] { _settingsSectionPerformancePreparation, _settingsSectionPerformanceRendering };
                rawLabels = new[] { "PREPARATION", "RENDERING" };
            }
            else
            {
                scroller = _settingsEverydayScroll;
                rawElements = new[] { _settingsSectionEverydayUse, _settingsSectionEverydayPlayback, _settingsSectionEverydayController, _settingsSectionEverydayHistory };
                rawLabels = new[] { "USE", "PLAYBACK", "CONTROLLER", "HISTORY" };
            }
            elements = new List<FrameworkElement>(); labels = new List<string>();
            for (int i = 0; i < rawElements.Length; i++)
            {
                FrameworkElement element = rawElements[i];
                if (element != null && element.Visibility == Visibility.Visible && element.ActualHeight > 0)
                {
                    elements.Add(element); labels.Add(rawLabels[i]);
                }
            }
        }

        private void SettingsContextRegisterMouseDown(object sender, MouseButtonEventArgs e)
        {
            if (_settingsContextRegister == null || _settingsTabs == null || _settingsContextRegister.ActualWidth <= 0) return;
            double ratio = Math.Max(0.0, Math.Min(0.9999, e.GetPosition(_settingsContextRegister).X / _settingsContextRegister.ActualWidth));
            _settingsTabs.SelectedIndex = Math.Max(0, Math.Min(2, (int)Math.Floor(ratio * 3.0)));
            ScheduleSettingsSectionCartography();
            e.Handled = true;
        }

        private void SettingsSectionRegisterMouseDown(object sender, MouseButtonEventArgs e)
        {
            if (_settingsSectionRegister == null || _settingsSectionRegister.ActualWidth <= 0) return;
            ScrollViewer scroller; List<FrameworkElement> elements; List<string> labels;
            CurrentSettingsSections(out scroller, out elements, out labels);
            if (scroller == null || elements.Count == 0) return;
            double ratio = Math.Max(0.0, Math.Min(0.9999, e.GetPosition(_settingsSectionRegister).X / _settingsSectionRegister.ActualWidth));
            int index = Math.Max(0, Math.Min(elements.Count - 1, (int)Math.Floor(ratio * elements.Count)));
            try
            {
                double top = elements[index].TranslatePoint(new Point(0, 0), scroller).Y;
                scroller.ScrollToVerticalOffset(Math.Max(0.0, scroller.VerticalOffset + top - 12.0));
                _settingsSectionText.Text = (index + 1).ToString("00", CultureInfo.InvariantCulture) + " / " + elements.Count.ToString("00", CultureInfo.InvariantCulture) + " | " + labels[index];
                ScheduleSettingsSectionCartography();
            }
            catch { }
            e.Handled = true;
        }

        private void ScheduleSettingsSectionCartography()
        {
            if (_settingsOverlay == null || _settingsOverlay.Visibility != Visibility.Visible) return;
            _window.Dispatcher.BeginInvoke(DispatcherPriority.Background, new Action(UpdateSettingsSectionCartography));
        }

        private void UpdateSettingsSectionCartography()
        {
            if (_settingsSectionText == null || _settingsTabs == null) return;
            int tab = Math.Max(0, _settingsTabs.SelectedIndex);
            ScrollViewer scroller;
            List<FrameworkElement> visibleElements;
            List<string> visibleLabels;
            CurrentSettingsSections(out scroller, out visibleElements, out visibleLabels);

            Border[] nodes = new[] { _settingsSectionNode1, _settingsSectionNode2, _settingsSectionNode3, _settingsSectionNode4, _settingsSectionNode5, _settingsSectionNode6 };
            if (visibleElements.Count == 0 || scroller == null)
            {
                _settingsSectionText.Text = tab == 2 ? "ADVANCED CONTROLS CLOSED" : "SECTION -";
                foreach (Border node in nodes) if (node != null) node.Visibility = Visibility.Collapsed;
                return;
            }

            int active = 0;
            double anchor = 34.0;
            double nearestTop = Double.NegativeInfinity;
            for (int i = 0; i < visibleElements.Count; i++)
            {
                try
                {
                    double top = visibleElements[i].TranslatePoint(new Point(0, 0), scroller).Y;
                    double bottom = top + visibleElements[i].ActualHeight;
                    if (top <= anchor && bottom > 0 && top >= nearestTop) { active = i; nearestTop = top; }
                    else if (nearestTop == Double.NegativeInfinity && top > anchor) { active = i; break; }
                }
                catch { }
            }
            _settingsSectionText.Text = (active + 1).ToString("00", CultureInfo.InvariantCulture) + " / " + visibleElements.Count.ToString("00", CultureInfo.InvariantCulture) + " | " + visibleLabels[active];
            for (int i = 0; i < nodes.Length; i++)
            {
                Border node = nodes[i];
                if (node == null) continue;
                node.Visibility = i < visibleElements.Count ? Visibility.Visible : Visibility.Collapsed;
                if (i < visibleElements.Count) node.Opacity = i == active ? 0.86 : (i < active ? 0.30 : 0.12);
            }
        }

