        private Dictionary<string, object> ReadJsonFresh(string path)
        {
            try { if (File.Exists(path)) return AsMap(_json.DeserializeObject(ReadTextShared(path))); } catch { }
            return EmptyMap();
        }

        private AppearancePreset ParseAppearance(string s) { if (s.StartsWith("Midnight")) return AppearancePreset.Midnight; if (s.StartsWith("Graphite")) return AppearancePreset.Graphite; if (s.StartsWith("Carbon")) return AppearancePreset.CarbonViolet; if (s.StartsWith("Ember")) return AppearancePreset.Ember; if (s.StartsWith("Dusk")) return AppearancePreset.Dusk; if (s.StartsWith("Slate")) return AppearancePreset.Slate; if (s.StartsWith("Moss")) return AppearancePreset.Moss; if (s.StartsWith("Harbor")) return AppearancePreset.Harbor; if (s.StartsWith("Sage")) return AppearancePreset.Sage; if (s.StartsWith("Paper")) return AppearancePreset.Paper; if (s.StartsWith("High")) return AppearancePreset.HighContrast; return AppearancePreset.Midnight; }
        private WorkspaceProfile ParseWorkspace(string s) { WorkspaceProfile v; return Enum.TryParse<WorkspaceProfile>(s, true, out v) ? v : WorkspaceProfile.Player; }
        private InformationDensity ParseDensity(string s) { InformationDensity v; return Enum.TryParse<InformationDensity>(s, true, out v) ? v : InformationDensity.Clean; }

        private void SaveIntegratedSettings(bool defaults)
        {
            if (_settingsPopulating || (_settingsSaveButton != null && !_settingsSaveButton.IsEnabled)) return;
            Dictionary<string, object> c;
            WorkspaceProfile requestedWorkspace;
            AppearancePreset requestedAppearance;
            InformationDensity requestedDensity;
            bool quiet, classicMenu, reduceMotion, alwaysOnTop;
            try
            {
                Dictionary<string, object> cachedConfig = ReadJsonCached(Path.Combine(_dataRoot, "config.json"));
                if (cachedConfig.Count == 0) cachedConfig = ReadJsonCached(Path.Combine(_appDir, "default-config.json"));
                c = new Dictionary<string, object>(cachedConfig, StringComparer.OrdinalIgnoreCase);
                c["app_mode"] = ComboText(_settingsAppMode, "Streamer / OBS"); c["history_enabled"] = Checked(_settingsHistoryEnabled); c["history_max_entries"] = ComboInt(_settingsHistoryMax, 100);
                c["loudness_normalization"] = Checked(_settingsLoudness); c["audio_quality"] = ComboText(_settingsAudioQuality, "Best available"); c["player_video_quality"] = ComboText(_settingsPlayerVideoQuality, "Off (audio only)"); c["transition_policy"] = ComboText(_settingsTransitionPolicy, "Synchronized presentation");
                c["artwork_enabled"] = Checked(_settingsArtwork); c["video_enabled"] = Checked(_settingsVideo); c["title_enabled"] = Checked(_settingsTitle); c["channel_enabled"] = Checked(_settingsChannel); c["smart_artwork_crop"] = Checked(_settingsSmartArtworkCrop); c["overlay_video_quality"] = ComboText(_settingsOverlayVideoQuality, "240p"); c["video_fps"] = "Source FPS";
                c["overlay_preset"] = ComboText(_settingsBroadcastPreset, "Custom"); c["director_mode"] = Checked(_settingsDirectorMode); c["director_outputs"] = BuildDirectorOutputs(c);
                c["canvas_width"] = Math.Max(320, Math.Min(8192, ComboInt(_settingsCanvasWidth, 2560))); string canvasHeightText = ComboText(_settingsCanvasHeight, "Auto"); c["canvas_height_mode"] = String.Equals(canvasHeightText, "Auto", StringComparison.OrdinalIgnoreCase) ? "Auto" : "Manual"; c["canvas_height"] = String.Equals(canvasHeightText, "Auto", StringComparison.OrdinalIgnoreCase) ? Math.Max(24, ComboInt(_settingsMediaHeight, 90)) : Math.Max(24, Math.Min(4320, ComboInt(_settingsCanvasHeight, 90))); c["media_width"] = Math.Max(16, Math.Min(4096, ComboInt(_settingsMediaWidth, 160))); c["media_height"] = Math.Max(16, Math.Min(2160, ComboInt(_settingsMediaHeight, 90))); c["overlay_safe_margin_px"] = ComboInt(_settingsSafeMargin, 8);
                c["overlay_auto_fit_text"] = Checked(_settingsAutoFitText); c["text_size"] = ComboInt(_settingsTextSize, DefaultOverlayTextSize); c["overlay_min_text_size"] = ComboInt(_settingsMinTextSize, 18); c["overlay_text_gap_px"] = ComboInt(_settingsTextGap, 14); c["text_font"] = ComboText(_settingsTextFont, DefaultOverlayTextFont); c["text_color"] = ComboText(_settingsTextColor, DefaultOverlayTextColor); c["text_outline"] = ComboInt(_settingsTextOutline, DefaultOverlayTextOutline); c["outline_color"] = ComboText(_settingsOutlineColor, DefaultOverlayOutlineColor); c["text_opacity"] = Math.Max(0.05, Math.Min(1.0, ComboDouble(_settingsTextOpacity, DefaultOverlayTextOpacity))); c["text_alignment"] = ComboText(_settingsTextAlignment, DefaultOverlayTextAlignment); c["title_channel_spacing"] = ComboText(_settingsTextSpacing, DefaultOverlayTextSpacing); c["text_glow"] = Checked(_settingsTextGlow); c["media_border_enabled"] = Checked(_settingsMediaBorderEnabled); c["media_border_px"] = Math.Max(0, Math.Min(32, ComboInt(_settingsMediaBorderPx, 2))); c["media_border_color"] = ComboText(_settingsMediaBorderColor, "#252525"); c["media_corner_style"] = ComboText(_settingsMediaCornerStyle, "Square");
                c["visualizer_enabled"] = Checked(_settingsVisualizerEnabled); c["visualizer_match_text_overhang"] = Checked(_settingsVisualizerMatchText); c["visualizer_adaptive_fill"] = ComboText(_settingsVisualizerFill, "Adaptive"); c["visualizer_activity"] = ComboText(_settingsVisualizerActivity, "Active"); c["visualizer_opacity"] = Math.Max(0.05, Math.Min(1.0, ComboDouble(_settingsVisualizerOpacity, 0.3))); c["visualizer_color_mode"] = ComboText(_settingsVisualizerColorMode, "Solid"); c["visualizer_solid_color"] = ComboText(_settingsVisualizerSolidColor, "#8A8A84"); c["visualizer_frequency_scale"] = ComboText(_settingsVisualizerFrequencyScale, "Logarithmic"); c["visualizer_high_frequency_trim"] = ComboInt(_settingsVisualizerTrim, 0); c["visualizer_high_frequency_lift_db"] = ComboInt(_settingsVisualizerLift, 4); c["visualizer_shape"] = ComboText(_settingsVisualizerShape, "Spectrum"); c["visualizer_bar_spacing"] = ComboText(_settingsVisualizerSpacing, "None"); c["visualizer_fps"] = ComboText(_settingsVisualizerFps, "30 FPS"); c["visualizer_length_multiplier"] = ComboDouble(_settingsVisualizerLength, 4.0); c["visualizer_direction"] = ComboText(_settingsVisualizerDirection, "Normal"); c["visualizer_vertical_anchor"] = ComboText(_settingsVisualizerAnchor, "Source"); c["visualizer_layer"] = ComboText(_settingsVisualizerLayer, "Behind text");
                c["prefetch_ahead"] = ComboInt(_settingsPrefetch, 4); c["video_prefetch_ahead"] = ComboInt(_settingsVideoPrefetch, 4); c["cache_workers"] = ComboInt(_settingsCacheWorkers, 2); c["browser_fps_mode"] = ComboText(_settingsBrowserFps, "Auto"); c["visualizer_internal_width"] = ComboInt(_settingsVisualizerInternalWidth, 40); c["visualizer_internal_height"] = ComboInt(_settingsVisualizerInternalHeight, 10);
                requestedWorkspace = ParseWorkspace(ComboText(_settingsWorkspace, _workspaceProfile.ToString()));
                requestedAppearance = ParseAppearance(ComboText(_settingsTheme, AppearanceLabel(_appearancePreset)));
                requestedDensity = ParseDensity(ComboText(_settingsDetail, _informationDensity.ToString()));
                quiet = Checked(_settingsQuietSurface); classicMenu = Checked(_settingsClassicMenu); reduceMotion = Checked(_settingsReduceMotion); alwaysOnTop = Checked(_settingsAlwaysOnTop);
                _settingsSaveButton.IsEnabled = false;
                _settingsStatusText.Text = "Saving...";
            }
            catch (Exception ex)
            {
                _settingsStatusText.Text = "Could not prepare settings: " + ex.Message;
                if (_settingsSaveButton != null) _settingsSaveButton.IsEnabled = true;
                return;
            }

            ThreadPool.QueueUserWorkItem(delegate(object ignored)
            {
                string action = ""; string failure = "";
                try { action = ApplyIntegratedConfigTransaction(c); }
                catch (Exception ex) { failure = ex.Message; }
                try
                {
                    _window.Dispatcher.BeginInvoke(new Action(delegate
                    {
                        if (!String.IsNullOrWhiteSpace(failure))
                        {
                            _settingsStatusText.Text = "Could not save: " + failure;
                            _settingsSaveButton.IsEnabled = true;
                            ShowToast("Settings", "Could not save settings.");
                            return;
                        }
                        _jsonCache.Clear();
                        _settingsStatusText.Text = String.Equals(action, "NOOP", StringComparison.OrdinalIgnoreCase) ? "No changes to save." : "Saved and applied.";
                        if (requestedWorkspace == WorkspaceProfile.Custom) _workspaceProfile = WorkspaceProfile.Custom;
                        else if (requestedWorkspace != _workspaceProfile) ApplyWorkspaceProfile(requestedWorkspace, false);
                        _appearanceManuallySelected = true;
                        SetAppearancePreset(requestedAppearance, false);
                        SetInformationDensity(requestedDensity, false);
                        SetQuietSurface(quiet, false); SetMenuBarVisible(classicMenu, false); SetReduceMotion(reduceMotion, false); SetAlwaysOnTop(alwaysOnTop, false);
                        _visualizerShape = GetString(c, "visualizer_shape", "Spectrum");
                        ApplyArtworkCropPreference(); ApplyMediaMode(false); RefreshObsQuickSetup(); SaveUiState();
                        _settingsBaselineSnapshot = CaptureSettingsDraft(); _settingsLastSnapshot = _settingsBaselineSnapshot; _settingsDirty = false; _settingsSaveButton.IsEnabled = false; UpdateSettingsHistoryButtons();
                        if (!_performanceWorkspace && _visualizerEnabled && !String.IsNullOrWhiteSpace(_lastVizPath)) StartFramePreview(_lastVizPath, _timePosition, true);
                    }), DispatcherPriority.Background);
                }
                catch { }
            });
        }

