        private void WireQueue()
        {
            _queueList.ItemsSource = _queueRows;
            _queueList.Loaded += delegate { AttachQueueHorizonScroll(); ScheduleQueueHorizonMarker(); };
            _queueView = CollectionViewSource.GetDefaultView(_queueRows);
            _queueView.Filter = QueueFilter;

            _queueFilterAll.Click += delegate { SetQueueScope(QueueScope.All); };
            _queueFilterUpcoming.Click += delegate { SetQueueScope(QueueScope.Upcoming); };
            _queueFilterReady.Click += delegate { SetQueueScope(QueueScope.Ready); };
            _queueFilterIssues.Click += delegate { SetQueueScope(QueueScope.Issues); };
            _queueFilterHistory.Click += delegate { SetQueueScope(QueueScope.History); };
            _queueFilterNextTen.Click += delegate { SetQueueScope(QueueScope.NextTen); };
            _queueFilterUnready.Click += delegate { SetQueueScope(QueueScope.Unready); };
            _queueFilterFavorites.Click += delegate { SetQueueScope(QueueScope.Favorites); };
            _queueFilterUnheard.Click += delegate { SetQueueScope(QueueScope.Unheard); };
            _queueFilterFrequent.Click += delegate { SetQueueScope(QueueScope.Frequent); };
            _queueAdvancedFiltersToggle.Click += delegate
            {
                _queueAdvancedFiltersOpen = false;
                _queueAdvancedFiltersToggle.IsChecked = false;
                OpenQueueFilterMenu();
            };
            _queueSearchClearButton.Click += delegate
            {
                ClearQueuePlaybackSubset();
                _queueSearchBox.Clear();
                _queueSearchBox.Focus();
            };
            if (_queueSearchPlayButton != null) _queueSearchPlayButton.Click += delegate { ActivateQueueSearchPlaybackSubset(); };
            _queueJumpCurrentButton.Click += delegate { JumpQueueToCurrent(); };
            _queueOverviewSurface.PreviewMouseLeftButtonDown += QueueOverviewMouseDown;
            _queueOverviewSurface.PreviewMouseMove += QueueOverviewMouseMove;
            _queueOverviewSurface.PreviewMouseLeftButtonUp += QueueOverviewMouseUp;
            _queueOverviewSurface.LostMouseCapture += delegate { _queueOverviewDragging = false; };
            _queueOverviewSurface.SizeChanged += delegate { UpdateQueueOverviewMap(); };
            _queueCollapseButton.Click += delegate { SetQueueOpen(false, true); };
            if (_queueTableChannelSplitter != null)
            {
                _queueTableChannelSplitter.DragCompleted += delegate
                {
                    if (_queueTableChannelColumn == null) return;
                    _queueTableChannelWidth = Math.Max(100.0, Math.Min(520.0, _queueTableChannelColumn.ActualWidth));
                    _queueTableChannelColumn.Width = new GridLength(_queueTableChannelWidth);
                    SaveUiState();
                };
                _queueTableChannelSplitter.MouseDoubleClick += delegate
                {
                    _queueTableChannelWidth = 240.0;
                    if (_queueTableChannelColumn != null) _queueTableChannelColumn.Width = new GridLength(_queueTableChannelWidth);
                    SaveUiState();
                };
            }
            _queueFollowToggle.Click += delegate
            {
                _queueFollowCurrent = _queueFollowToggle.IsChecked == true;
                SaveUiState();
                if (_queueFollowCurrent) FollowCurrentQueueRow();
            };
            ApplyQueueScopeUi();
            _queueList.AddHandler(Button.ClickEvent, new RoutedEventHandler(QueueTemplateActionClick));

            _queueSelectionPlayNextButton.Click += delegate { BatchPlayNextSelected(); };
            _queueSelectionPrepareButton.Click += delegate { BatchPrepareSelected(); };
            _queueSelectionLaterButton.Click += delegate { BatchMoveLaterSelected(5); };
            _queueSelectionFavoriteButton.Click += delegate { FavoriteSelectedQueueRows(); };
            _queueSelectionRemoveButton.Click += delegate { QueueRemoveSelected(); };
            UpdateQueueSelectionBar();

            _queueSearchBox.PreviewKeyDown += delegate(object sender, KeyEventArgs e)
            {
                if (e.Key != Key.Enter) return;
                // R61.67: Enter is deterministic even if the 120 ms typing debounce has not fired yet.
                _queueSearchDebounce.Stop();
                ApplyQueueFilterRefresh();
                if (_queueList == null || _queueList.Items.Count == 0) return;
                QueueRow row = _queueList.Items[0] as QueueRow;
                if (row == null) return;
                _queueList.SelectedItems.Clear();
                _queueList.SelectedItem = row;
                _queueList.ScrollIntoView(row);
                _window.Dispatcher.BeginInvoke(DispatcherPriority.Loaded, new Action(delegate
                {
                    ListBoxItem container = _queueList.ItemContainerGenerator.ContainerFromItem(row) as ListBoxItem;
                    if (container != null) container.Focus();
                    else _queueList.Focus();
                }));
                e.Handled = true;
            };

            _queueSearchBox.TextChanged += delegate
            {
                bool searchEmpty = String.IsNullOrWhiteSpace(_queueSearchBox.Text);
                if (_queuePlaybackSubsetActive && !String.Equals((_queueSearchBox.Text ?? "").Trim(), _queuePlaybackSubsetQuery, StringComparison.OrdinalIgnoreCase)) ClearQueuePlaybackSubset();
                _queueSearchPlaceholder.Visibility = searchEmpty ? Visibility.Visible : Visibility.Collapsed;
                _queueSearchClearButton.Visibility = searchEmpty ? Visibility.Collapsed : Visibility.Visible;
                if (_queueSearchPlayButton != null)
                {
                    _queueSearchPlayButton.Visibility = searchEmpty ? Visibility.Collapsed : Visibility.Visible;
                    _queueSearchPlayButton.IsEnabled = !searchEmpty && _queueView != null && _queueView.Cast<object>().Any();
                }
                if (IsContextWorkspace(_workspaceProfile) && !_applyingWorkspaceProfile)
                    WorkspaceContextFor(_workspaceProfile).QueueSearch = _queueSearchBox.Text ?? "";
                CompileQueueFilterQuery();
                // R61.67: filtering 2,000-10,000 rows synchronously for every physical key event
                // is needless UI-thread churn. Coalesce ordinary typing into one refresh while
                // keeping Enter/clear/scope changes deterministic through immediate flushes.
                _queueSearchDebounce.Stop();
                _queueSearchDebounce.Start();
            };

            _queueList.SelectionChanged += delegate
            {
                RefreshInspector();
                UpdateQueueFilterSummary();
                UpdateQueueSelectionBar();
                _queueOverviewIndexDirty = true;
                UpdateQueueOverviewMap();
            };

            _queueList.MouseDoubleClick += delegate(object sender, MouseButtonEventArgs e)
            {
                var inlineButton = FindVisualParent<Button>(e.OriginalSource as DependencyObject);
                if (inlineButton != null && ((inlineButton.Tag as string) ?? "").StartsWith("queue-row-", StringComparison.Ordinal))
                    return;
                var row = _queueList.SelectedItem as QueueRow;
                if (row != null && _running)
                    SendMpv("script-message", "yomi-jump", row.OccurrenceId.ToString(CultureInfo.InvariantCulture));
            };

            _queueList.PreviewMouseRightButtonDown += delegate(object sender, MouseButtonEventArgs e)
            {
                var item = FindVisualParent<ListBoxItem>(e.OriginalSource as DependencyObject);
                if (item != null && !item.IsSelected)
                {
                    _queueList.SelectedItems.Clear();
                    item.IsSelected = true;
                }
            };

            _queueList.PreviewMouseLeftButtonDown += delegate(object sender, MouseButtonEventArgs e)
            {
                var inlineButton = FindVisualParent<Button>(e.OriginalSource as DependencyObject);
                if (inlineButton != null && ((inlineButton.Tag as string) ?? "").StartsWith("queue-row-", StringComparison.Ordinal))
                {
                    _queueDragArmed = false;
                    return;
                }
                _queueDragStart = e.GetPosition(_queueList);
                var item = FindVisualParent<ListBoxItem>(e.OriginalSource as DependencyObject);
                _queueDragArmed = item != null;
                if (item != null && item.IsSelected && _queueList.SelectedItems.Count > 1 &&
                    Keyboard.Modifiers == ModifierKeys.None)
                {
                    // Explorer-style multi-drag: pressing an already-selected row must not
                    // collapse the selection before the drag threshold is crossed.
                    item.Focus();
                    e.Handled = true;
                }
            };
            _queueList.PreviewMouseLeftButtonUp += delegate
            {
                _queueDragArmed = false;
                ClearQueueDropIndicator();
            };
            _queueList.PreviewMouseMove += delegate(object sender, MouseEventArgs e)
            {
                if (!_queueDragArmed || e.LeftButton != MouseButtonState.Pressed)
                    return;
                Point now = e.GetPosition(_queueList);
                if (Math.Abs(now.X - _queueDragStart.X) < SystemParameters.MinimumHorizontalDragDistance &&
                    Math.Abs(now.Y - _queueDragStart.Y) < SystemParameters.MinimumVerticalDragDistance)
                    return;
                var rows = SelectedQueueRows().Where(r => r.OccurrenceId != _currentOccurrence).ToList();
                if (rows.Count == 0)
                {
                    _queueDragArmed = false;
                    ShowToast("Queue reorder", "The playing occurrence stays anchored.");
                    return;
                }
                if (!QueueDragEditingAllowed())
                {
                    _queueDragArmed = false;
                    ShowToast("Queue reorder", "Use All with an empty search to drag exact slots.");
                    return;
                }
                _queueDragArmed = false;
                var payload = String.Join(",", rows.Select(r => r.OccurrenceId.ToString(CultureInfo.InvariantCulture)).ToArray());
                var data = new DataObject("YOMI_QUEUE_OCCURRENCES", payload);
                DragDrop.DoDragDrop(_queueList, data, DragDropEffects.Move);
                ClearQueueDropIndicator();
            };
            _queueList.AllowDrop = true;
            _queueList.DragOver += delegate(object sender, DragEventArgs e)
            {
                if (!_running || !QueueDragEditingAllowed() || !e.Data.GetDataPresent("YOMI_QUEUE_OCCURRENCES"))
                {
                    e.Effects = DragDropEffects.None;
                    ClearQueueDropIndicator();
                    e.Handled = true;
                    return;
                }
                Point listPoint = e.GetPosition(_queueList);
                var scroller = FindVisualChild<ScrollViewer>(_queueList);
                if (scroller != null)
                {
                    if (listPoint.Y < 26) scroller.LineUp();
                    else if (listPoint.Y > Math.Max(26, _queueList.ActualHeight - 26)) scroller.LineDown();
                }

                var item = FindVisualParent<ListBoxItem>(e.OriginalSource as DependencyObject);
                var row = item != null ? item.DataContext as QueueRow : null;
                if (row == null)
                {
                    ClearQueueDropIndicator();
                    _queueDropToEnd = true;
                    if (_queueDropEndIndicator != null) _queueDropEndIndicator.Visibility = Visibility.Visible;
                    e.Effects = DragDropEffects.Move;
                    e.Handled = true;
                    return;
                }
                _queueDropToEnd = false;
                if (_queueDropEndIndicator != null) _queueDropEndIndicator.Visibility = Visibility.Collapsed;
                Point p = e.GetPosition(item);
                bool after = p.Y > Math.Max(1.0, item.ActualHeight / 2.0);
                SetQueueDropIndicator(row, after);
                e.Effects = DragDropEffects.Move;
                e.Handled = true;
            };
            _queueList.DragLeave += delegate { ClearQueueDropIndicator(); };
            _queueList.Drop += delegate(object sender, DragEventArgs e)
            {
                try
                {
                    if (!_running || !QueueDragEditingAllowed() ||
                        (!_queueDropToEnd && _queueDropRow == null) ||
                        !e.Data.GetDataPresent("YOMI_QUEUE_OCCURRENCES"))
                        return;
                    string raw = Convert.ToString(e.Data.GetData("YOMI_QUEUE_OCCURRENCES"), CultureInfo.InvariantCulture) ?? "";
                    int targetBoundary = _queueDropToEnd
                        ? _order.Count + 1
                        : _queueDropRow.Slot + (_queueDropAfter ? 1 : 0);
                    MoveOccurrenceBlock(raw, targetBoundary, _queueDropToEnd ? "drag-end" : "drag");
                }
                finally
                {
                    ClearQueueDropIndicator();
                    e.Handled = true;
                }
            };

            var queueMenu = new ContextMenu();
            AddMenuItem(queueMenu, "Play now", delegate { QueueCommand("yomi-jump"); });
            AddMenuItem(queueMenu, "Play next", delegate { QueueCommand("yomi-order-play-next"); });
            AddMenuItem(queueMenu, "Prepare", delegate { BatchPrepareSelected(); });
            AddMenuItem(queueMenu, "Toggle favorite", delegate { ToggleFavoriteSelectedOrCurrent(); });
            var queueOpenSourceItem = AddMenuItem(queueMenu, "Open source", delegate { OpenSelectedOrCurrentSource(); });
            AddMenuItem(queueMenu, "Move +5 slots", delegate { QueueCommand("yomi-order-move-later", "5"); });
            AddMenuItem(queueMenu, "Move selected to top of upcoming", delegate { MoveSelectedBlockToBoundary(Math.Max(1, _currentSlot + 1), "top-upcoming"); });
            AddMenuItem(queueMenu, "Move selected to end", delegate { MoveSelectedBlockToBoundary(_order.Count + 1, "end"); });
            queueMenu.Items.Add(new Separator());
            var batchPlayNextItem = AddMenuItem(queueMenu, "Play selected next", delegate { BatchPlayNextSelected(); });
            var batchCopyItem = AddMenuItem(queueMenu, "Copy selected", delegate { CopySelectedQueueRows(false); });
            var batchCopyTableItem = AddMenuItem(queueMenu, "Copy selected as table", delegate { CopySelectedQueueRowsAsTable(); });
            var batchCopyUrlsItem = AddMenuItem(queueMenu, "Copy selected URLs", delegate { CopySelectedQueueRows(true); });
            var batchRemoveItem = AddMenuItem(queueMenu, "Remove selected", delegate { QueueRemoveSelected(); });
            queueMenu.Opened += delegate
            {
                int count = SelectedQueueRows().Count;
                string suffix = count > 1 ? " (" + count.ToString(CultureInfo.InvariantCulture) + ")" : "";
                queueOpenSourceItem.IsEnabled = count == 1 && !String.IsNullOrWhiteSpace(GetSelectedOrCurrentUrl());
                batchPlayNextItem.Header = "Play selected next" + suffix;
                batchCopyItem.Header = "Copy selected" + suffix;
                batchCopyTableItem.Header = "Copy selected as table" + suffix;
                batchCopyUrlsItem.Header = "Copy selected URLs" + suffix;
                batchRemoveItem.Header = "Remove selected" + suffix;
            };
            queueMenu.Items.Add(new Separator());
            AddMenuItem(queueMenu, "Undo order change", delegate { if (_running) UndoQueueOrder(); });
            AddMenuItem(queueMenu, "Redo order change", delegate { if (_running) RedoQueueOrder(); });
            AddMenuItem(queueMenu, "Reshuffle unprepared tail", delegate { if (_running) ReshuffleQueueTail(); });
            AddMenuItem(queueMenu, "Restore original order", delegate { if (_running) RestoreOriginalQueueOrder(); });
            queueMenu.Items.Add(new Separator());
            AddMenuItem(queueMenu, "Save queue checkpoint", delegate { SaveQueueCheckpoint(); });
            AddMenuItem(queueMenu, "Restore latest checkpoint", delegate { RestoreLatestQueueCheckpoint(); });
            _queueList.ContextMenu = queueMenu;
            _queueList.PreviewKeyDown += delegate(object sender, KeyEventArgs e)
            {
                bool shift = (e.KeyboardDevice.Modifiers & ModifierKeys.Shift) == ModifierKeys.Shift;
                bool ctrl = (e.KeyboardDevice.Modifiers & ModifierKeys.Control) == ModifierKeys.Control;
                if (e.Key == Key.Enter)
                {
                    if (shift) BatchPlayNextSelected();
                    else QueueCommand("yomi-jump");
                    e.Handled = true;
                }
                else if (e.Key == Key.P && !ctrl)
                {
                    BatchPrepareSelected();
                    e.Handled = true;
                }
                else if (e.Key == Key.Delete)
                {
                    QueueRemoveSelected();
                    e.Handled = true;
                }
                else if (ctrl && e.Key == Key.Z)
                {
                    if (_running) UndoQueueOrder();
                    e.Handled = true;
                }
                else if (ctrl && e.Key == Key.Y)
                {
                    if (_running) RedoQueueOrder();
                    e.Handled = true;
                }
                else if ((e.KeyboardDevice.Modifiers & ModifierKeys.Alt) == ModifierKeys.Alt && e.Key == Key.Up)
                {
                    MoveSelectedBlockByOne(-1);
                    e.Handled = true;
                }
                else if ((e.KeyboardDevice.Modifiers & ModifierKeys.Alt) == ModifierKeys.Alt && e.Key == Key.Down)
                {
                    MoveSelectedBlockByOne(1);
                    e.Handled = true;
                }
                else if (ctrl && shift && e.Key == Key.Home)
                {
                    MoveSelectedBlockToBoundary(Math.Max(1, _currentSlot + 1), "top-upcoming");
                    e.Handled = true;
                }
                else if (ctrl && shift && e.Key == Key.End)
                {
                    MoveSelectedBlockToBoundary(_order.Count + 1, "end");
                    e.Handled = true;
                }
                else if (ctrl && shift && e.Key == Key.C)
                {
                    CopySelectedQueueRowsAsTable();
                    e.Handled = true;
                }
                else if (ctrl && e.Key == Key.C)
                {
                    CopySelectedQueueRows(false);
                    e.Handled = true;
                }
                else if (ctrl && e.Key == Key.A)
                {
                    _queueList.SelectAll();
                    e.Handled = true;
                }
                else if (ctrl && e.Key == Key.D)
                {
                    ToggleFavoriteSelectedOrCurrent();
                    e.Handled = true;
                }
            };

            var nowMenu = new ContextMenu();
            AddMenuItem(nowMenu, "Inspect", delegate { SetInspectorOpen(true, true); });
            AddMenuItem(nowMenu, "Toggle favorite    Ctrl+D", delegate { ToggleFavoriteCurrent(); });
            AddMenuItem(nowMenu, "Copy now playing", delegate { CopyNowPlaying(); });
            AddMenuItem(nowMenu, "Copy source URL", delegate { CopyCurrentSourceUrl(); });
            _nowPlayingSurface.ContextMenu = nowMenu;
        }

        private void StartBroadcastRehearsal(int count)
        {
            if (!_running)
            {
                ShowToast("Broadcast rehearsal", "Start YOMI playback first.");
                return;
            }
            count = Math.Max(1, Math.Min(20, count));
            if (SendMpv("script-message", "yomi-rehearse", count.ToString(CultureInfo.InvariantCulture)))
            {
                _lastQueueRefreshMs = 0;
                AddActivity("Broadcast", "rehearse next " + count.ToString(CultureInfo.InvariantCulture));
                ShowToast("Broadcast rehearsal", "Preparing next " + count.ToString(CultureInfo.InvariantCulture) + " transitions");
            }
        }

        private void ToggleBroadcastFreeze()
        {
            if (!_running)
            {
                ShowToast("Broadcast Freeze", "Start YOMI playback first.");
                return;
            }
            if (SendMpv("script-message", "yomi-freeze-toggle"))
            {
                _lastQueueRefreshMs = 0;
                AddActivity("Broadcast", "freeze toggle requested");
                ShowToast("Broadcast Freeze", "Toggle requested");
            }
        }

        private void BeginQueueSlotNavigation()
        {
            if (!_queueOpen)
                SetQueueOpen(true, true);
            if (_queueScope != QueueScope.All)
            {
                _queueScope = QueueScope.All;
                ApplyQueueScopeUi();
                if (_queueView != null) _queueView.Refresh();
            }
            _queueSearchBox.Text = "#";
            _queueSearchBox.CaretIndex = _queueSearchBox.Text.Length;
            _queueSearchBox.Focus();
        }

        private void ActivateQueueSearchPlaybackSubset()
        {
            if (_queueView == null || _queueSearchBox == null) return;
            _queueSearchDebounce.Stop();
            ApplyQueueFilterRefresh();
            string query = (_queueSearchBox.Text ?? "").Trim();
            if (query.Length == 0) return;
            var ids = new List<int>();
            foreach (object raw in _queueView)
            {
                QueueRow row = raw as QueueRow;
                if (row != null && row.OccurrenceId > 0) ids.Add(row.OccurrenceId);
            }
            if (ids.Count == 0) return;
            if (!_running)
            {
                ShowToast("Search playlist", "Start playback first, then Listen will restrict playback to these matches.");
                return;
            }
            string csv = String.Join(",", ids.Select(x => x.ToString(CultureInfo.InvariantCulture)).ToArray());
            if (!SendMpv("script-message", "yomi-playback-subset", csv, query)) return;
            _queuePlaybackSubsetActive = true;
            _queuePlaybackSubsetQuery = query;
            if (_queueSearchPlayButton != null) { _queueSearchPlayButton.Content = "Listening"; _queueSearchPlayButton.IsEnabled = false; }
            AddActivity("Search playlist", query + " | " + ids.Count.ToString(CultureInfo.InvariantCulture) + " matches");
        }

        private void ClearQueuePlaybackSubset()
        {
            if (!_queuePlaybackSubsetActive) return;
            if (_running) SendMpv("script-message", "yomi-playback-subset-clear");
            _queuePlaybackSubsetActive = false;
            _queuePlaybackSubsetQuery = "";
            if (_queueSearchPlayButton != null) { _queueSearchPlayButton.Content = "Listen"; _queueSearchPlayButton.IsEnabled = !String.IsNullOrWhiteSpace(_queueSearchBox == null ? "" : _queueSearchBox.Text); }
        }

        private void CompileQueueFilterQuery()
        {
            string q = (_queueSearchBox == null ? "" : (_queueSearchBox.Text ?? "")).Trim();
            _queueQueryText = q;
            _queueQueryA = 0; _queueQueryB = 0;
            _queueQueryKind = q.Length == 0 ? QueueQueryKind.None : QueueQueryKind.Text;
            if (q.Length == 0) return;

            int a, b;
            if (q[0] == '#')
            {
                string slotText = q.Substring(1).Trim();
                int dash = slotText.IndexOf('-');
                if (dash > 0 &&
                    Int32.TryParse(slotText.Substring(0, dash).Trim(), NumberStyles.Integer, CultureInfo.InvariantCulture, out a) &&
                    Int32.TryParse(slotText.Substring(dash + 1).Trim(), NumberStyles.Integer, CultureInfo.InvariantCulture, out b))
                {
                    _queueQueryKind = QueueQueryKind.SlotRange; _queueQueryA = Math.Min(a,b); _queueQueryB = Math.Max(a,b); return;
                }
                if (slotText.StartsWith(">", StringComparison.Ordinal) && Int32.TryParse(slotText.Substring(1).Trim(), NumberStyles.Integer, CultureInfo.InvariantCulture, out a))
                { _queueQueryKind = QueueQueryKind.SlotGreater; _queueQueryA = a; return; }
                if (slotText.StartsWith("<", StringComparison.Ordinal) && Int32.TryParse(slotText.Substring(1).Trim(), NumberStyles.Integer, CultureInfo.InvariantCulture, out a))
                { _queueQueryKind = QueueQueryKind.SlotLess; _queueQueryA = a; return; }
                if (Int32.TryParse(slotText, NumberStyles.Integer, CultureInfo.InvariantCulture, out a))
                { _queueQueryKind = QueueQueryKind.SlotExact; _queueQueryA = a; return; }
            }
            else if (q[0] == '@')
            {
                _queueQueryKind = QueueQueryKind.Channel; _queueQueryText = q.Substring(1).Trim(); return;
            }
            else if (q.StartsWith("id:", StringComparison.OrdinalIgnoreCase) &&
                     Int32.TryParse(q.Substring(3).Trim(), NumberStyles.Integer, CultureInfo.InvariantCulture, out a))
            {
                _queueQueryKind = QueueQueryKind.Occurrence; _queueQueryA = a; return;
            }
        }

        private bool QueueFilter(object item)
        {
            var row = item as QueueRow;
            if (row == null || !QueueScopeAccepts(row)) return false;
            switch (_queueQueryKind)
            {
                case QueueQueryKind.None: return true;
                case QueueQueryKind.Channel: return _queueQueryText.Length == 0 || (row.Channel ?? "").IndexOf(_queueQueryText, StringComparison.OrdinalIgnoreCase) >= 0;
                case QueueQueryKind.SlotExact: return row.Slot == _queueQueryA;
                case QueueQueryKind.SlotRange: return row.Slot >= _queueQueryA && row.Slot <= _queueQueryB;
                case QueueQueryKind.SlotGreater: return row.Slot > _queueQueryA;
                case QueueQueryKind.SlotLess: return row.Slot < _queueQueryA;
                case QueueQueryKind.Occurrence: return row.OccurrenceId == _queueQueryA;
                default: return row.SearchText.IndexOf(_queueQueryText, StringComparison.OrdinalIgnoreCase) >= 0;
            }
        }

        private bool QueueScopeAccepts(QueueRow row)
        {
            if (row == null) return false;
            switch (_queueScope)
            {
                case QueueScope.Upcoming:
                    return row.Status != "PLAYED";
                case QueueScope.Ready:
                    return row.Status == "READY" || row.Status == "AUDIO READY" || row.Status == "POLICY READY" || row.Status == "ISOLATED READY" || row.Status == "PLAYING" || row.Status == "PAUSED";
                case QueueScope.Issues:
                    return row.Status == "BUILDING" || row.Status == "WAITING" || row.Status == "FAILED" || row.Status == "AUDIO READY" || row.Status == "POLICY READY" || row.Status == "ISOLATED READY";
                case QueueScope.History:
                    return row.Status == "PLAYED";
                case QueueScope.NextTen:
                    return row.Slot > _currentSlot && row.Slot <= _currentSlot + 10;
                case QueueScope.Unready:
                    return row.Status == "BUILDING" || row.Status == "WAITING" || row.Status == "QUEUED" || row.Status == "FAILED";
                case QueueScope.Favorites:
                    return row.IsFavorite;
                case QueueScope.Unheard:
                    return row.PlayCount <= 0;
                case QueueScope.Frequent:
                    return row.PlayCount >= 3;
                default:
                    return true;
            }
        }

        private void ApplyQueueFilterRefresh()
        {
            if (_queueView == null) return;
            CompileQueueFilterQuery();
            long started = _clock.ElapsedMilliseconds;
            bool searchEmpty = _queueSearchBox == null || String.IsNullOrWhiteSpace(_queueSearchBox.Text);
            _queueView.Refresh();
            if (_queueSearchPlayButton != null)
            {
                _queueSearchPlayButton.Visibility = searchEmpty ? Visibility.Collapsed : Visibility.Visible;
                _queueSearchPlayButton.IsEnabled = !searchEmpty && !_queuePlaybackSubsetActive && _queueList != null && _queueList.Items.Count > 0;
            }
            PruneHiddenQueueSelection();
            UpdateQueueFilterSummary();
            _queueOverviewIndexDirty = true;
            UpdateQueueOverviewMap();
            if (searchEmpty && _queueFollowCurrent) FollowCurrentQueueRow();
            ScheduleQueueHorizonMarker();
            long elapsed = _clock.ElapsedMilliseconds - started;
            if (elapsed >= 100)
                WriteControllerPerformanceLogAsync("QUEUE FILTER REFRESH " + elapsed.ToString(CultureInfo.InvariantCulture) + "ms rows=" + _queueRows.Count.ToString(CultureInfo.InvariantCulture));
        }

        private void SetQueueScope(QueueScope scope)
        {
            SetQueueScope(scope, true);
        }

        private void SetQueueScope(QueueScope scope, bool announce)
        {
            bool changed = _queueScope != scope;
            _queueScope = scope;
            ApplyQueueScopeUi();
            _queueSearchDebounce.Stop();
            ApplyQueueFilterRefresh();
            if (changed)
                SaveUiState();
            if (announce && changed)
            {
                AddActivity("Queue scope", QueueScopeLabel(scope));
            }
        }

        private void CycleQueueDensity()
        {
            _queueDensity = QueueDensity.Dense;
            ApplyQueueDensity(true);
        }

        private void ApplyQueueDensity(bool save)
        {
            _queueDensity = QueueDensity.Dense;
            double preservedOffset = -1.0;
            if (_queueList != null)
            {
                AttachQueueHorizonScroll();
                if (_queueHorizonScrollViewer != null)
                    preservedOffset = _queueHorizonScrollViewer.VerticalOffset;

                _queueList.Tag = _queueDensity.ToString();

                // R61.94: TABLE is the Queue renderer, not one density among several.
                // Bind it directly and keep old density tokens as migration-only input.
                if (_queueTableItemTemplate != null && !Object.ReferenceEquals(_queueList.ItemTemplate, _queueTableItemTemplate))
                    _queueList.ItemTemplate = _queueTableItemTemplate;
            }
            ApplyQueueTableColumnFit();

            if (_queueDensityButton != null)
            {
                _queueDensityButton.Content = "Table";
                _queueDensityButton.ToolTip = "Queue presentation: Table";
            }
            if (_queueList != null) _queueList.Margin = _queueDensity == QueueDensity.Dense ? new Thickness(4,0,2,2) : new Thickness(6,6,2,5);
            if (_queueSelectionBar != null)
            {
                bool table = _queueDensity == QueueDensity.Dense;
                _queueSelectionBar.Padding = table ? new Thickness(8,4,8,4) : new Thickness(10,8,10,8);
                _queueSelectionBar.Margin = table ? new Thickness(4,0,4,4) : new Thickness(10,0,10,8);
                _queueSelectionBar.CornerRadius = table ? new CornerRadius(2) : new CornerRadius(8);
            }
            ApplyQueueCanvasChrome();

            if (preservedOffset >= 0.0)
            {
                double restore = preservedOffset;
                _window.Dispatcher.BeginInvoke(DispatcherPriority.Loaded, new Action(delegate
                {
                    AttachQueueHorizonScroll();
                    if (_queueHorizonScrollViewer != null)
                        _queueHorizonScrollViewer.ScrollToVerticalOffset(restore);
                    UpdateQueueHorizonMarker();
                    UpdateQueueOverviewMap();
                }));
            }
            if (save) SaveUiState();
        }

        private void ApplyQueueScopeUi()
        {
            _queueFilterAll.IsChecked = _queueScope == QueueScope.All;
            _queueFilterUpcoming.IsChecked = _queueScope == QueueScope.Upcoming;
            _queueFilterReady.IsChecked = _queueScope == QueueScope.Ready;
            _queueFilterIssues.IsChecked = _queueScope == QueueScope.Issues;
            _queueFilterHistory.IsChecked = _queueScope == QueueScope.History;
            _queueFilterNextTen.IsChecked = _queueScope == QueueScope.NextTen;
            _queueFilterUnready.IsChecked = _queueScope == QueueScope.Unready;
            _queueFilterFavorites.IsChecked = _queueScope == QueueScope.Favorites;
            _queueFilterUnheard.IsChecked = _queueScope == QueueScope.Unheard;
            _queueFilterFrequent.IsChecked = _queueScope == QueueScope.Frequent;
            _queueFollowToggle.IsChecked = _queueFollowCurrent;
            ApplyQueueAdvancedFilterVisibility();
        }

        private bool IsAdvancedQueueScope()
        {
            return _queueScope == QueueScope.History || _queueScope == QueueScope.NextTen ||
                   _queueScope == QueueScope.Unready || _queueScope == QueueScope.Favorites ||
                   _queueScope == QueueScope.Unheard || _queueScope == QueueScope.Frequent;
        }

        private void OpenQueueFilterMenu()
        {
            if (_queueAdvancedFiltersToggle == null) return;
            var menu = new ContextMenu();
            Action<string, QueueScope> addScope = delegate(string label, QueueScope scope)
            {
                var item = new MenuItem { Header = label, IsCheckable = true, IsChecked = _queueScope == scope };
                item.Click += delegate { SetQueueScope(scope); };
                menu.Items.Add(item);
            };
            addScope("All", QueueScope.All);
            addScope("Upcoming", QueueScope.Upcoming);
            addScope("Ready", QueueScope.Ready);
            addScope("Issues", QueueScope.Issues);
            menu.Items.Add(new Separator());
            addScope("History", QueueScope.History);
            addScope("Next 10", QueueScope.NextTen);
            addScope("Unready", QueueScope.Unready);
            addScope("Favorites", QueueScope.Favorites);
            addScope("Unheard", QueueScope.Unheard);
            addScope("Frequent", QueueScope.Frequent);
            menu.Items.Add(new Separator());
            var follow = new MenuItem { Header = "Follow current", IsCheckable = true, IsChecked = _queueFollowCurrent };
            follow.Click += delegate { _queueFollowCurrent = !_queueFollowCurrent; ApplyQueueScopeUi(); SaveUiState(); if (_queueFollowCurrent) FollowCurrentQueueRow(); };
            menu.Items.Add(follow);
            menu.PlacementTarget = _queueAdvancedFiltersToggle;
            menu.Placement = System.Windows.Controls.Primitives.PlacementMode.Bottom;
            menu.IsOpen = true;
        }

        private void ApplyQueueAdvancedFilterVisibility()
        {
            if (_queueAdvancedFilterPanel == null || _queueAdvancedFiltersToggle == null) return;
            _queueAdvancedFiltersOpen = false;
            _queueAdvancedFilterPanel.Visibility = Visibility.Collapsed;
            _queueAdvancedFiltersToggle.IsChecked = false;
            _queueAdvancedFiltersToggle.Content = "Filter";
        }

        private void PruneHiddenQueueSelection()
        {
            if (_queueList == null || _queueList.SelectedItems.Count == 0) return;
            var hidden = new List<QueueRow>();
            foreach (var item in _queueList.SelectedItems)
            {
                var row = item as QueueRow;
                if (row != null && !QueueFilter(row)) hidden.Add(row);
            }
            foreach (var row in hidden)
                _queueList.SelectedItems.Remove(row);
            if (hidden.Count > 0) UpdateQueueSelectionBar();
        }

        private void UpdateQueueFilterSummary()
        {
            if (_queueFilterSummaryText == null) return;
            int total = _queueRows.Count;
            int visible = total;
            bool simpleAllView = _queueScope == QueueScope.All && _queueQueryKind == QueueQueryKind.None && String.IsNullOrWhiteSpace(_queueQueryText);
            if (!simpleAllView)
            {
                visible = 0;
                foreach (var row in _queueRows)
                {
                    if (QueueFilter(row)) visible++;
                }
            }
            string scopeLabel = _queueScope == QueueScope.All ? "" : "  " + QueueScopeLabel(_queueScope).ToUpperInvariant();
            int selected = _queueList != null ? _queueList.SelectedItems.Count : 0;
            string selectedLabel = selected > 1 ? "  " + selected.ToString(CultureInfo.InvariantCulture) + " SELECTED" : "";
            _queueFilterSummaryText.Text = (visible == total
                ? total.ToString(CultureInfo.InvariantCulture)
                : visible.ToString(CultureInfo.InvariantCulture) + " / " + total.ToString(CultureInfo.InvariantCulture)) + scopeLabel + selectedLabel;
            if (_queueEmptyState != null)
            {
                bool empty = visible == 0;
                _queueEmptyState.Visibility = empty ? Visibility.Visible : Visibility.Collapsed;
                if (empty && _queueEmptyTitleText != null && _queueEmptyBodyText != null)
                {
                    bool hasSearch = !String.IsNullOrWhiteSpace(_queueSearchBox.Text);
                    _queueEmptyTitleText.Text = hasSearch ? "Nothing matches" : "No tracks in this view";
                    _queueEmptyBodyText.Text = hasSearch
                        ? "Clear the search or choose a broader queue view."
                        : "Choose All or Upcoming to return to the active session.";
                }
            }
        }

        private void AttachQueueHorizonScroll()
        {
            if (_queueList == null || _queueHorizonScrollViewer != null) return;
            var scroller = FindVisualChild<ScrollViewer>(_queueList);
            if (scroller == null) return;
            _queueHorizonScrollViewer = scroller;
            scroller.ScrollChanged += delegate { UpdateQueueHorizonMarker(); };
        }

        private void ScheduleQueueHorizonMarker()
        {
            _queueOverviewIndexDirty = true;
            if (_queueViewportSurface == null) return;
            _window.Dispatcher.BeginInvoke(DispatcherPriority.Background, new Action(delegate
            {
                AttachQueueHorizonScroll();
                UpdateQueueHorizonMarker();
            }));
        }

        private void UpdateQueueHorizonMarker()
        {
            if (_queueCurrentMarker == null || _queueViewportSurface == null || _queueList == null)
                return;

            UpdateQueueOverviewMap();
            _queueCurrentMarker.Opacity = 0;
            if (!_queueOpen || _currentOccurrence <= 0) return;

            QueueRow row;
            if (!_queueByOccurrence.TryGetValue(_currentOccurrence, out row) || row == null || !QueueFilter(row)) return;
            var item = _queueList.ItemContainerGenerator.ContainerFromItem(row) as ListBoxItem;

            if (item != null && item.ActualHeight > 0)
            {
                try
                {
                    Point p = item.TranslatePoint(new Point(0, item.ActualHeight * 0.5), _queueViewportSurface);
                    double y = Math.Round(p.Y);
                    if (y >= 5 && y <= _queueViewportSurface.ActualHeight - 5)
                    {
                        Canvas.SetTop(_queueCurrentMarker, Math.Max(0.0, y - 9.0));
                        _queueCurrentMarker.Opacity = 0.88;
                        return;
                    }
                    // R61.69: never cover table rows with floating current-location chrome.
                    // The persistent Queue > Current control owns navigation.
                    return;
                }
                catch { }
            }

            // Recycling virtualization may mean NOW has no container at all. Because the
            // ListBox explicitly uses logical item scrolling, VerticalOffset/ViewportHeight
            // are trustworthy item-space coordinates for a direction-only continuation cue.
            int viewIndex = _queueList.Items.IndexOf(row);
            if (viewIndex < 0 || _queueHorizonScrollViewer == null) return;
            double first = _queueHorizonScrollViewer.VerticalOffset;
            double lastExclusive = first + Math.Max(1.0, _queueHorizonScrollViewer.ViewportHeight);
            // R61.69: offscreen state remains implicit; Current/Follow are stable toolbar controls.
        }

        private void RecomputeQueueOverviewSemanticIndexes()
        {
            _queueOverviewIndexDirty = false;
            _queueOverviewCurrentIndex = -1;
            _queueOverviewSelectionAverage = -1;
            if (_queueList == null || _queueList.Items.Count <= 0) return;

            var selected = new HashSet<object>();
            foreach (object raw in _queueList.SelectedItems) if (raw != null) selected.Add(raw);
            long selectedIndexSum = 0;
            int selectedHits = 0;
            for (int i = 0; i < _queueList.Items.Count; i++)
            {
                object raw = _queueList.Items[i];
                QueueRow row = raw as QueueRow;
                if (row == null) continue;
                if (row.OccurrenceId == _currentOccurrence) _queueOverviewCurrentIndex = i;
                if (selected.Contains(raw)) { selectedIndexSum += i; selectedHits++; }
            }
            if (selectedHits > 0) _queueOverviewSelectionAverage = (double)selectedIndexSum / selectedHits;
        }

        private void RenderQueueOverviewTopology(double height)
        {
            // R61.67: decorative readiness/favorite topology was intentionally retired.
            // Keep the compatibility canvas empty; the overview now communicates only
            // viewport, current-track and selection position.
            if (_queueOverviewTopologyCanvas != null && _queueOverviewTopologyCanvas.Children.Count > 0)
                _queueOverviewTopologyCanvas.Children.Clear();
        }

        private void UpdateQueueOverviewMap()
        {
            if (_queueOverviewSurface == null || _queueOverviewCanvas == null || _queueOverviewViewport == null || _queueOverviewCurrentNode == null || _queueOverviewSelectionMarker == null || _queueList == null) return;
            _queueOverviewViewport.Opacity = 0;
            _queueOverviewCurrentNode.Opacity = 0;
            _queueOverviewSelectionMarker.Opacity = 0;
            if (!_queueOpen || _queueList.Items.Count <= 0) return;
            AttachQueueHorizonScroll();
            if (_queueHorizonScrollViewer == null) return;
            if (_queueOverviewIndexDirty) RecomputeQueueOverviewSemanticIndexes();

            double height = _queueOverviewCanvas.ActualHeight;
            RenderQueueOverviewTopology(height);
            int count = _queueList.Items.Count;
            if (height < 18 || count <= 0) return;
            // Queue scrolling is logical (CanContentScroll=true), so extent/offset/viewport are item-space values.
            // The overview therefore stays truthful without materializing virtualized rows.
            double extent = Math.Max((double)count, Math.Max(1.0, _queueHorizonScrollViewer.ExtentHeight));
            double first = Math.Max(0.0, _queueHorizonScrollViewer.VerticalOffset);
            double visible = Math.Max(1.0, _queueHorizonScrollViewer.ViewportHeight);
            double viewportHeight = Math.Max(10.0, Math.Min(height, height * Math.Min(1.0, visible / extent)));
            double viewportTop = height * Math.Min(1.0, first / extent);
            viewportTop = Math.Max(0.0, Math.Min(height - viewportHeight, viewportTop));
            _queueOverviewViewport.Height = viewportHeight;
            Canvas.SetTop(_queueOverviewViewport, viewportTop);
            _queueOverviewViewport.Opacity = count > visible + 0.5 ? 0.48 : 0.20;

            if (_queueOverviewCurrentIndex >= 0)
            {
                double y = ((_queueOverviewCurrentIndex + 0.5) / Math.Max(1.0, count)) * height;
                Canvas.SetTop(_queueOverviewCurrentNode, Math.Max(0.0, Math.Min(height - 5.0, y - 2.5)));
                _queueOverviewCurrentNode.Opacity = 0.96;
            }
            if (_queueOverviewSelectionAverage >= 0)
            {
                double y = ((_queueOverviewSelectionAverage + 0.5) / Math.Max(1.0, count)) * height;
                Canvas.SetTop(_queueOverviewSelectionMarker, Math.Max(0.0, Math.Min(height - 3.0, y - 1.5)));
                _queueOverviewSelectionMarker.Opacity = 0.72;
            }
        }

        private void QueueOverviewNavigateAt(double y)
        {
            if (_queueOverviewSurface == null || _queueList == null || _queueList.Items.Count <= 0) return;
            AttachQueueHorizonScroll();
            if (_queueHorizonScrollViewer == null) return;
            double height = Math.Max(1.0, _queueOverviewSurface.ActualHeight);
            double ratio = Math.Max(0.0, Math.Min(1.0, y / height));
            int index = Math.Max(0, Math.Min(_queueList.Items.Count - 1, (int)Math.Round(ratio * (_queueList.Items.Count - 1))));
            double visible = Math.Max(1.0, _queueHorizonScrollViewer.ViewportHeight);
            double targetOffset = Math.Max(0.0, index - (visible * 0.5));
            _queueHorizonScrollViewer.ScrollToVerticalOffset(targetOffset);
            UpdateQueueHorizonMarker();
        }

        private void QueueOverviewMouseDown(object sender, MouseButtonEventArgs e)
        {
            if (_queueOverviewSurface == null) return;
            _queueOverviewDragging = true;
            _queueOverviewSurface.CaptureMouse();
            QueueOverviewNavigateAt(e.GetPosition(_queueOverviewSurface).Y);
            e.Handled = true;
        }

        private void QueueOverviewMouseMove(object sender, MouseEventArgs e)
        {
            if (!_queueOverviewDragging || e.LeftButton != MouseButtonState.Pressed || _queueOverviewSurface == null) return;
            QueueOverviewNavigateAt(e.GetPosition(_queueOverviewSurface).Y);
            e.Handled = true;
        }

        private void QueueOverviewMouseUp(object sender, MouseButtonEventArgs e)
        {
            if (!_queueOverviewDragging) return;
            _queueOverviewDragging = false;
            if (_queueOverviewSurface != null && _queueOverviewSurface.IsMouseCaptured) _queueOverviewSurface.ReleaseMouseCapture();
            e.Handled = true;
        }

        private void UpdateQueueNowAnchor()
        {
            if (_queueNowText == null) return;
            if (_currentOccurrence <= 0 || String.IsNullOrWhiteSpace(_titleText.Text) || _titleText.Text.StartsWith("Waiting", StringComparison.OrdinalIgnoreCase))
            {
                _queueNowText.Text = "Now - waiting for playback";
                if (_queueJumpCurrentButton != null) _queueJumpCurrentButton.IsEnabled = false;
                return;
            }
            string slot = _currentSlot > 0 && _order.Count > 0 ? _currentSlot.ToString(CultureInfo.InvariantCulture) + "/" + _order.Count.ToString(CultureInfo.InvariantCulture) : "";
            string channel = String.IsNullOrWhiteSpace(_channelText.Text) ? "" : "  -  " + _channelText.Text;
            _queueNowText.Text = "Now " + slot + "  -  " + _titleText.Text + channel;
            if (_queueJumpCurrentButton != null) _queueJumpCurrentButton.IsEnabled = true;
        }

        private void SelectQueueOccurrenceWhenReady(int occurrence, bool relaxFilters)
        {
            if (occurrence <= 0) return;
            if (!QueueUiRowsReady)
            {
                _queueUiPendingSelectOccurrence = occurrence;
                _queueUiPendingSelectRelaxFilters = relaxFilters;
                EnsureQueueUiMaterialized("locate");
                return;
            }

            QueueRow row;
            if (!_queueByOccurrence.TryGetValue(occurrence, out row)) return;
            if (relaxFilters)
            {
                if (!QueueFilter(row) && !String.IsNullOrWhiteSpace(_queueSearchBox.Text))
                    _queueSearchBox.Clear();
                if (!QueueFilter(row) && _queueScope != QueueScope.All)
                    SetQueueScope(QueueScope.All, false);
            }
            if (!QueueFilter(row)) return;
            _queueList.SelectedItems.Clear();
            _queueList.SelectedItem = row;
            _queueList.ScrollIntoView(row);
            _queueList.Focus();
            ScheduleQueueHorizonMarker();
        }

        private void JumpQueueToCurrent()
        {
            SelectQueueOccurrenceWhenReady(_currentOccurrence, true);
        }

        private static string QueueScopeLabel(QueueScope scope)
        {
            switch (scope)
            {
                case QueueScope.Upcoming: return "UPCOMING";
                case QueueScope.Ready: return "READY";
                case QueueScope.Issues: return "ISSUES";
                case QueueScope.History: return "HISTORY";
                case QueueScope.NextTen: return "NEXT 10";
                case QueueScope.Unready: return "UNREADY";
                case QueueScope.Favorites: return "FAVORITES";
                case QueueScope.Unheard: return "UNHEARD";
                case QueueScope.Frequent: return "FREQUENT";
                default: return "ALL";
            }
        }

        private void FollowCurrentQueueRow()
        {
            if (!_queueOpen || !_queueFollowCurrent || _currentOccurrence <= 0 || _queueSearchBox.Text.Length != 0)
                return;
            QueueRow current;
            if (_queueByOccurrence.TryGetValue(_currentOccurrence, out current) && QueueFilter(current))
            {
                _queueList.ScrollIntoView(current);
                ScheduleQueueHorizonMarker();
            }
        }

        private static bool IsVisualDescendantOf(DependencyObject source, DependencyObject ancestor)
        {
            DependencyObject current = source;
            while (current != null)
            {
                if (Object.ReferenceEquals(current, ancestor)) return true;
                current = VisualTreeHelper.GetParent(current);
            }
            return false;
        }

        private static T FindVisualParent<T>(DependencyObject source) where T : DependencyObject
        {
            DependencyObject current = source;
            while (current != null)
            {
                var typed = current as T;
                if (typed != null)
                    return typed;
                current = VisualTreeHelper.GetParent(current);
            }
            return null;
        }

        private static T FindVisualChild<T>(DependencyObject source) where T : DependencyObject
        {
            if (source == null) return null;
            int count = VisualTreeHelper.GetChildrenCount(source);
            for (int i = 0; i < count; i++)
            {
                var child = VisualTreeHelper.GetChild(source, i);
                var typed = child as T;
                if (typed != null) return typed;
                var nested = FindVisualChild<T>(child);
                if (nested != null) return nested;
            }
            return null;
        }

        private void SetMediaMode(MediaMode mode, bool restartPreview)
        {
            bool changed = _mediaMode != mode;
            _mediaMode = mode;
            if (changed) SaveUiState();
            ApplyMediaMode(restartPreview);
            QueuePresentationDemandSync(true);
            if (_running && _currentOccurrence > 0)
                SendMpv("script-message", "yomi-prepare", _currentOccurrence.ToString(CultureInfo.InvariantCulture));
            if (_performanceWorkspace) ApplyPerformanceWorkspace(true);
            if (changed) SafeRefresh(true);
        }

        private static bool MediaModeHasArtwork(MediaMode mode)
        {
            return mode == MediaMode.Artwork || mode == MediaMode.Both;
        }

        private static bool MediaModeHasVideo(MediaMode mode)
        {
            return mode == MediaMode.Video || mode == MediaMode.Both;
        }

        private void ToggleMediaModule(bool artwork)
        {
            bool art = MediaModeHasArtwork(_mediaMode);
            bool video = MediaModeHasVideo(_mediaMode);
            if (artwork) art = !art; else video = !video;
            MediaMode next = art ? (video ? MediaMode.Both : MediaMode.Artwork) : (video ? MediaMode.Video : MediaMode.Off);
            // R61.88: a local Thumbnail/Video toggle is not a global presentation restart.
            // ApplyResolvedMedia already stops/starts the affected video/artwork surface selectively;
            // forcing _lastMediaOccurrence=0 here made the next refresh tear down the unrelated
            // visualizer graph as if the track itself had changed.
            SetMediaMode(next, false);
        }

        private bool VideoPreparationEnabled()
        {
            // R61.75: explicit local Video intent overrides background preparation policy.
            if (MediaModeHasVideo(_mediaMode)) return true;
            var config = ReadJsonCached(Path.Combine(_dataRoot, "config.json"));
            string localQuality = GetString(config, "player_video_quality", "Off (audio only)");
            bool localVideo = !localQuality.StartsWith("Off", StringComparison.OrdinalIgnoreCase);
            bool overlayVideo = String.Equals(GetString(config, "app_mode", ""), "Streamer / OBS", StringComparison.OrdinalIgnoreCase) && GetBool(config, "video_enabled", true);
            return localVideo || overlayVideo;
        }

        private void SyncMediaDemand()
        {
            bool art = MediaModeHasArtwork(_mediaMode);
            bool video = MediaModeHasVideo(_mediaMode);
            if (_mediaThumbnailToggle != null) _mediaThumbnailToggle.IsChecked = art;
            if (_mediaVideoToggle != null) _mediaVideoToggle.IsChecked = video;
            QueuePresentationDemandSync(false);
        }

        private void CycleVisualizerPresentation()
        {
            VisualizerPresentation next = _visualizerPresentation == VisualizerPresentation.Compact
                ? VisualizerPresentation.Standard
                : _visualizerPresentation == VisualizerPresentation.Standard
                    ? VisualizerPresentation.Cinema
                    : VisualizerPresentation.Compact;
            SetVisualizerPresentation(next, true);
        }

        private void SetVisualizerEnabled(bool enabled, bool restartPreview)
        {
            if (_visualizerEnabled == enabled) { SyncVisualizerDemand(); return; }
            _visualizerEnabled = enabled;
            _lastVisualizerDemandSent = null;
            SaveUiState();
            QueuePresentationDemandSync(true);
            if (enabled && _running && _currentOccurrence > 0)
                SendMpv("script-message", "yomi-prepare", _currentOccurrence.ToString(CultureInfo.InvariantCulture));
            ApplyVisualizerMode(restartPreview);
            if (_performanceWorkspace) ApplyPerformanceWorkspace(true);
            SafeRefresh(true);
        }

        private void SyncVisualizerDemand()
        {
            QueuePresentationDemandSync(false);
        }

        private void ObservePresentationDemandRuntime(Dictionary<string, object> current, Dictionary<string, object> engine)
        {
            string runtimeId = GetString(engine, "runtime_id", "");
            if (String.IsNullOrWhiteSpace(runtimeId))
            {
                var projected = GetMap(current, "controller_demand");
                runtimeId = GetString(projected, "runtime_id", "");
            }
            if (String.IsNullOrWhiteSpace(runtimeId))
            {
                var protocol = GetMap(current, "state_protocol");
                runtimeId = GetString(protocol, "runtime_id", "");
            }

            _diagnosticRuntimeId = runtimeId ?? "";
            lock (_presentationDemandSync)
            {
                if (!String.Equals(_presentationDemandRuntimeId, runtimeId, StringComparison.Ordinal))
                {
                    _presentationDemandRuntimeId = runtimeId ?? "";
                    _presentationDemandLastAcceptedKey = "";
                    _presentationDemandLastAcceptedMs = -10000;
                    _lastMediaDemandSent = "";
                    _lastVisualizerDemandSent = null;
                }
            }
        }

        private void QueuePresentationDemandSync(bool force)
        {
            bool art = MediaModeHasArtwork(_mediaMode);
            bool video = MediaModeHasVideo(_mediaMode);
            bool viz = _visualizerEnabled;
            if (!_running)
            {
                lock (_presentationDemandSync)
                {
                    _presentationDemandLastAcceptedKey = "";
                    _presentationDemandLastAcceptedMs = -10000;
                    _presentationDemandPendingKey = "";
                }
                return;
            }

            bool startWorker = false;
            lock (_presentationDemandSync)
            {
                string runtime = _presentationDemandRuntimeId ?? "";
                string key = runtime + "|" + (art ? "1" : "0") + (video ? "1" : "0") + (viz ? "1" : "0");
                long now = _clock.ElapsedMilliseconds;
                if (!force && String.Equals(_presentationDemandLastAcceptedKey, key, StringComparison.Ordinal) && now - _presentationDemandLastAcceptedMs < PresentationDemandLeaseMs)
                    return;
                _presentationDemandPendingKey = key;
                _presentationDemandPendingArt = art;
                _presentationDemandPendingVideo = video;
                _presentationDemandPendingViz = viz;
                if (!_presentationDemandWorkerActive)
                {
                    _presentationDemandWorkerActive = true;
                    startWorker = true;
                }
            }
            if (startWorker) ThreadPool.QueueUserWorkItem(delegate(object ignored) { DrainPresentationDemandSync(); });
        }

        private void DrainPresentationDemandSync()
        {
            while (!_disposed)
            {
                string key; string runtime; bool art; bool video; bool viz;
                lock (_presentationDemandSync)
                {
                    key = _presentationDemandPendingKey;
                    runtime = _presentationDemandRuntimeId ?? "";
                    art = _presentationDemandPendingArt;
                    video = _presentationDemandPendingVideo;
                    viz = _presentationDemandPendingViz;
                }
                if (String.IsNullOrWhiteSpace(key))
                {
                    lock (_presentationDemandSync) _presentationDemandWorkerActive = false;
                    return;
                }

                bool accepted = SendMpvAcknowledged("script-message", "yomi-controller-demand", art ? "1" : "0", video ? "1" : "0", viz ? "1" : "0", runtime);
                lock (_presentationDemandSync)
                {
                    if (accepted)
                    {
                        _presentationDemandLastAcceptedKey = key;
                        _presentationDemandLastAcceptedMs = _clock.ElapsedMilliseconds;
                        _lastMediaDemandSent = (art ? "1" : "0") + ":" + (video ? "1" : "0");
                        _lastVisualizerDemandSent = viz;
                    }
                    if (String.Equals(_presentationDemandPendingKey, key, StringComparison.Ordinal))
                    {
                        _presentationDemandWorkerActive = false;
                        return;
                    }
                }
            }
            lock (_presentationDemandSync) _presentationDemandWorkerActive = false;
        }

        private void AddVisualizerPresentationMenuItem(MenuItem parent, string header, VisualizerPresentation presentation)
        {
            var item = new MenuItem { Header = header, IsCheckable = true, Tag = presentation };
            item.Click += delegate { SetVisualizerPresentation(presentation, true); RefreshVisualizerPresentationMenuChecks(parent); };
            parent.Items.Add(item);
        }

        private void RefreshVisualizerPresentationMenuChecks(MenuItem parent)
        {
            foreach (var raw in parent.Items)
            {
                var item = raw as MenuItem;
                if (item != null && item.Tag is VisualizerPresentation) item.IsChecked = (VisualizerPresentation)item.Tag == _visualizerPresentation;
            }
        }

        private void SetVisualizerPresentation(VisualizerPresentation presentation, bool save)
        {
            if (_visualizerPresentation == presentation) return;
            _visualizerPresentation = presentation;
            if (_visualizerSizeButton != null) _visualizerSizeButton.Content = presentation.ToString().ToUpperInvariant();
            ApplyVisualizerPresentation(save);
            if (save) AddActivity("Visualizer", VisualizerPresentationLabel(presentation));
        }

        private void ApplyVisualizerPresentation(bool save)
        {
            if (_visualizerSizeButton != null) _visualizerSizeButton.Content = _visualizerPresentation.ToString().ToUpperInvariant();
            bool surfaceAllowed = _visualizerEnabled && !_miniMode && !_performanceWorkspace;
            if (_visualizerRow != null) { _visualizerRow.MinHeight = 0; _visualizerRow.MaxHeight = 0; _visualizerRow.Height = new GridLength(0); }
            if (_visualizerBottomGapRow != null) _visualizerBottomGapRow.Height = new GridLength(0);
            if (_nowPlayingVisualizerColumn != null) _nowPlayingVisualizerColumn.Width = new GridLength(0);
            if (_nowPlayingVisualizerGapColumn != null) _nowPlayingVisualizerGapColumn.Width = new GridLength(0);
            double shellWidth = _window.ActualWidth > 0 ? _window.ActualWidth : _window.Width;
            double requestedMaxWidth = _visualizerPresentation == VisualizerPresentation.Compact ? 220.0 : (_visualizerPresentation == VisualizerPresentation.Cinema ? 500.0 : 360.0);
            double requestedHeight = _visualizerPresentation == VisualizerPresentation.Compact ? 24.0 : (_visualizerPresentation == VisualizerPresentation.Cinema ? 30.0 : 28.0);
            bool show = surfaceAllowed && shellWidth >= 700.0;
            if (_visualizerSurface != null)
            {
                // Presentation scaling only: the producer raster stays tiny. WPF stretches that
                // raster into whatever width the transport row can spare using NearestNeighbor.
                _visualizerSurface.Width = Double.NaN;
                _visualizerSurface.MinWidth = show ? 96.0 : 0.0;
                _visualizerSurface.MaxWidth = show ? requestedMaxWidth : 0.0;
                _visualizerSurface.Height = requestedHeight;
                _visualizerSurface.Visibility = show ? Visibility.Visible : Visibility.Collapsed;
            }
            if (_visualizerChrome != null) _visualizerChrome.Visibility = Visibility.Collapsed;
            if (save) SaveUiState();
        }

        private static string VisualizerPresentationLabel(VisualizerPresentation presentation)
        {
            switch (presentation)
            {
                case VisualizerPresentation.Compact: return "Compact";
                case VisualizerPresentation.Cinema: return "Cinema";
                default: return "Standard";
            }
        }

