            if (_queueHeaderSurface != null) _queueHeaderSurface.Margin = canvas ? new Thickness(8,3,8,3) : new Thickness(10,5,10,4);
            if (_queueSearchSurface != null) _queueSearchSurface.Margin = new Thickness(0);
