        private void SetQueuePlayerDock(QueuePlayerDock dock, bool save)
        {
            if (_queuePlayerDock == dock)
            {
                ApplyQueueCanvasLayout(true);
                return;
            }
            _queuePlayerDock = dock;
            ApplyQueueCanvasLayout(true);
            if (save)
            {
                SaveUiState();
                AddActivity("Player / Queue order", dock == QueuePlayerDock.Top ? "player above queue" : "queue above player");
            }
        }

        private void ApplyQueueCanvasRowLengths()
        {
            if (_workspaceTopRow == null || _workspaceBottomRow == null || _workspaceSplitRow == null) return;
            _workspaceTopRow.MinHeight = 0;
            _workspaceBottomRow.MinHeight = 0;
            if (!_queueCanvasActive)
            {
                _workspaceTopRow.Height = new GridLength(1, GridUnitType.Star);
                _workspaceSplitRow.Height = new GridLength(0);
                _workspaceBottomRow.Height = new GridLength(0);
                return;
            }

            // R61.94: the old resizable Player/Queue split is gone. The compact Player is
            // content-sized and TABLE receives every remaining pixel in the work plane.
            bool playerAbove = _queuePlayerDock == QueuePlayerDock.Top;
            _workspaceSplitRow.Height = new GridLength(4);
            _workspaceTopRow.Height = playerAbove ? GridLength.Auto : new GridLength(1, GridUnitType.Star);
            _workspaceBottomRow.Height = playerAbove ? new GridLength(1, GridUnitType.Star) : GridLength.Auto;
        }

        private void ApplyQueuePlayerCompressionForCurrentHeight()
        {
            if (!_queueCanvasActive || _mainSurface == null) return;

            if (_footerHint != null) _footerHint.Visibility = Visibility.Collapsed;
            if (_trackContextRail != null) _trackContextRail.Visibility = Visibility.Collapsed;
            if (_technicalText != null) _technicalText.Visibility = Visibility.Collapsed;
            if (_nowPlayingSurface != null) _nowPlayingSurface.Padding = new Thickness(6, 5, 6, 6);

            ApplyMediaMode(false);
            if (_mediaFrame != null && _mediaFrame.Visibility == Visibility.Visible)
                _mediaFrame.Height = Math.Min(_mediaFrame.Height, 116.0);

            // R61.94: Queue never receives a separate visualizer row. The visualizer stays in
            // the upper-right Now Playing lane and TABLE receives every reclaimed vertical pixel.
            ApplyVisualizerPresentation(false);
        }

        private void RestoreFullPlayerPresentationAfterQueueCanvas()
        {
            ApplyAdaptiveLayout(true);
            ApplyVisualizerPresentation(false);
            ApplyQuietSurface(false);
            RefreshEverydayStatusVisibility();
        }

        private void ApplyQueueCanvasLayout(bool force)
        {
            // R61.94: Queue is the primary work plane. The compact real Player remains present,
            // while TABLE consumes all remaining workspace without a splitter or persisted share.
            if (_workspaceTopRow == null || _workspaceSplitRow == null || _workspaceBottomRow == null || _queueDrawer == null || _mainSurface == null || _miniSurface == null || _queuePlayerDockSurface == null) return;
            bool canvas = ShouldUseQueueCanvasLayout();
            if (!force && canvas == _queueCanvasActive)
            {
                if (canvas) ApplyQueuePlayerCompressionForCurrentHeight();
                return;
            }
            bool wasCanvas = _queueCanvasActive;
            _queueCanvasActive = canvas;

            _queueDrawer.BeginAnimation(FrameworkElement.WidthProperty, null);
            _queueDrawer.BeginAnimation(UIElement.OpacityProperty, null);
            if (canvas)
            {
                bool playerAbove = _queuePlayerDock == QueuePlayerDock.Top;
                ApplyQueueCanvasRowLengths();
                _queuePlayerDockSurface.Visibility = Visibility.Collapsed;
                _queuePlayerDockSurface.Margin = new Thickness(0);
                Grid.SetColumn(_mainSurface, 0); Grid.SetColumnSpan(_mainSurface, 2); Grid.SetRow(_mainSurface, playerAbove ? 0 : 2);
                Grid.SetColumn(_queueDrawer, 0); Grid.SetColumnSpan(_queueDrawer, 2); Grid.SetRow(_queueDrawer, playerAbove ? 2 : 0);
                _mainSurface.Visibility = Visibility.Visible;
                _miniSurface.Visibility = Visibility.Collapsed;
                _microSurface.Visibility = Visibility.Collapsed;
                if (_queueDockPositionButton != null) { _queueDockPositionButton.Content = playerAbove ? "Player top" : "Queue top"; _queueDockPositionButton.ToolTip = playerAbove ? "Player is above Queue | click to put Queue above Player" : "Queue is above Player | click to put Player above Queue"; }
                _queueDrawer.Visibility = Visibility.Visible;
                _queueDrawer.HorizontalAlignment = HorizontalAlignment.Stretch;
                _queueDrawer.Width = Double.NaN;
                _queueDrawer.Margin = new Thickness(0);
                _queueDrawer.BorderThickness = new Thickness(0);
                _queueDrawer.Opacity = 1;
                ApplyQueueCanvasChrome();
                ApplyQueuePlayerCompressionForCurrentHeight();
                _window.Dispatcher.BeginInvoke(DispatcherPriority.Loaded, new Action(ApplyQueuePlayerCompressionForCurrentHeight));
                return;
            }

            ApplyQueueCanvasRowLengths();
            _queuePlayerDockSurface.Visibility = Visibility.Collapsed;
            _queuePlayerDockSurface.Margin = new Thickness(0);
            Grid.SetRow(_mainSurface, 0); Grid.SetColumn(_mainSurface, 0); Grid.SetColumnSpan(_mainSurface, 1);
            Grid.SetRow(_miniSurface, 0); Grid.SetColumn(_miniSurface, 0); Grid.SetColumnSpan(_miniSurface, 1);
            Grid.SetRow(_microSurface, 0); Grid.SetColumn(_microSurface, 0); Grid.SetColumnSpan(_microSurface, 1);
            Grid.SetRow(_queueDrawer, 0); Grid.SetColumn(_queueDrawer, 1); Grid.SetColumnSpan(_queueDrawer, 1);
            _miniSurface.Margin = new Thickness(0);
            _queueDrawer.HorizontalAlignment = HorizontalAlignment.Stretch;
            _queueDrawer.Margin = new Thickness(10,0,0,0);
            _queueDrawer.BorderThickness = new Thickness(1,0,0,0);
            if (_queueOpen)
            {
                _queueExpansionWidth = 0; _queueExpansionShiftX = 0;
                _queueDrawer.Width = Double.NaN; _queueDrawer.Opacity = 1; _queueDrawer.Visibility = Visibility.Visible;
            }
            else
            {
                _queueDrawer.Width = 0; _queueDrawer.Opacity = 0; _queueDrawer.Visibility = Visibility.Collapsed;
            }
            _mainSurface.Visibility = !_miniMode ? Visibility.Visible : Visibility.Collapsed;
            _miniSurface.Visibility = (_miniMode && !_microMode) ? Visibility.Visible : Visibility.Collapsed;
            ApplyQueueCanvasChrome();
            _microSurface.Visibility = _microMode ? Visibility.Visible : Visibility.Collapsed;
            if (_miniQueueButton2 != null) _miniQueueButton2.Content = "Queue";
            if (_miniExpandButton2 != null) _miniExpandButton2.Content = "Full";
            if (wasCanvas) RestoreFullPlayerPresentationAfterQueueCanvas();
        }

        private void ApplyAdaptiveLayout(bool force)
        {
            if (_adaptiveLayoutApplying || _miniMode) return;
            AdaptiveLayoutTier tier = ResolveAdaptiveLayoutTier();
            double height = _window.ActualHeight > 0 ? _window.ActualHeight : _window.Height;
            bool heightConstrained = height < 660;
            if (!force && tier == _adaptiveLayoutTier && heightConstrained == _adaptiveHeightConstrained) return;
            _adaptiveLayoutApplying = true;
            try
            {
                _adaptiveLayoutTier = tier;
                _adaptiveHeightConstrained = heightConstrained;
                bool constrained = tier == AdaptiveLayoutTier.Constrained;
                if (_visualizerToggle != null) _visualizerToggle.Content = "Viz";
                if (_visualizerSettingsButton != null) _visualizerSettingsButton.Width = 30;
                if (_mediaQuickControls != null) _mediaQuickControls.Visibility = tier == AdaptiveLayoutTier.Spacious ? Visibility.Visible : Visibility.Collapsed;
                if (_mainVolumeSurface != null) _mainVolumeSurface.Visibility = constrained ? Visibility.Collapsed : Visibility.Visible;
                if (_volumeButton != null) _volumeButton.Visibility = constrained ? Visibility.Visible : Visibility.Collapsed;
                if (_slotSelector != null)
                    _slotSelector.Width = tier == AdaptiveLayoutTier.Constrained ? 104 : (tier == AdaptiveLayoutTier.Standard ? 118 : 132);
                if (_repeatStatePill != null)
                    _repeatStatePill.Visibility = Visibility.Visible;
                if (_nowPlayingSurface != null)
                    _nowPlayingSurface.Padding = tier == AdaptiveLayoutTier.Constrained ? new Thickness(7,4,7,6) : (tier == AdaptiveLayoutTier.Standard ? new Thickness(8,5,8,7) : new Thickness(8,5,8,7));
                if (_trackContextRail != null)
                    _trackContextRail.Visibility = Visibility.Collapsed;
                ApplyMediaMode(false);
            }
            finally { _adaptiveLayoutApplying = false; }
        }

