        private void UpdateRuntimeStateUi(
            string phase,
            Dictionary<string, object> engine,
            Dictionary<string, object> queue,
            Dictionary<string, object> config,
            Dictionary<string, object> current)
        {
            Brush accent = Brush("Accent");
            Brush warning = Brush("Warning");
            Brush danger = Brush("Danger");
            Brush info = Brush("Info");
            Brush muted = Brush("TextMuted");

            bool supervisorStarting = !_running && (_engineLaunchMonitorActive || CachedSupervisorLive());
            bool silentWarmSurface = _startupPrewarmReady || _startupPrewarmInFlight || (_engineLaunchMonitorActive && _engineLaunchPrewarm);

            if (_startupPrewarmInFlight || (_engineLaunchMonitorActive && _engineLaunchPrewarm))
            {
                _headerStateText.Text = "Loading";
                _headerStateText.Foreground = muted;
                _headerStateDot.Fill = muted;
                _headerStatePill.Background = Brush("SurfaceRaised");
                _headerStatePill.BorderBrush = Brush("Border");
                _headerStatePill.ToolTip = "Loading playback…";
                _runtimeText.Text = "";
                _runtimeText.Foreground = muted;
                _runtimePill.Background = Brushes.Transparent;
                _runtimePill.BorderBrush = Brushes.Transparent;
                _systemStatusText.Text = "";
                _playGlyph.Visibility = Visibility.Visible;
                _pauseGlyph.Visibility = Visibility.Collapsed;
            }
            else if (supervisorStarting)
            {
                _headerStateText.Text = "Loading";
                _headerStateText.Foreground = muted;
                _headerStateDot.Fill = muted;
                _headerStatePill.Background = Brush("SurfaceRaised");
                _headerStatePill.BorderBrush = Brush("Border");
                _headerStatePill.ToolTip = "Loading playback…";
                _runtimeText.Text = "";
                _runtimeText.Foreground = muted;
                _runtimePill.Background = Brushes.Transparent;
                _runtimePill.BorderBrush = Brushes.Transparent;
                _systemStatusText.Text = "";
                _playGlyph.Visibility = Visibility.Visible;
                _pauseGlyph.Visibility = Visibility.Collapsed;
            }
            else if (!_running)
            {
                _headerStateText.Text = "Stopped";
                _headerStateText.Foreground = muted;
                _headerStateDot.Fill = muted;
                _headerStatePill.Background = Brush("SurfaceRaised");
                _headerStatePill.BorderBrush = Brush("Border");
                _headerStatePill.ToolTip = "Playback is stopped. Press Play or Space to start YOMI.";
                _runtimeText.Text = "Player offline";
                _runtimeText.Foreground = muted;
                _runtimePill.Background = Brush("SurfaceRaised");
                _runtimePill.BorderBrush = Brush("Border");
                _systemStatusText.Text = "Ready. Press Play or Space to start.";
                _playGlyph.Visibility = Visibility.Visible;
                _pauseGlyph.Visibility = Visibility.Collapsed;
            }
            else if (phase == "paused" && _audioActive)
            {
                _headerStateText.Text = "Paused";
                _headerStateText.Foreground = warning;
                _headerStateDot.Fill = warning;
                _headerStatePill.Background = Brush("WarningSoft");
                _headerStatePill.BorderBrush = warning;
                _headerStatePill.ToolTip = "Playback is paused. Prepared queue and cached media remain available.";
                _runtimeText.Text = "Player ready";
                _runtimeText.Foreground = accent;
                _runtimePill.Background = Brush("AccentSoft");
                _runtimePill.BorderBrush = Brush("AccentBorder");
                _systemStatusText.Text = FriendlyRuntimeStatus("paused");
            }
            else if (phase == "preparing")
            {
                _headerStateText.Text = "Ready";
                _headerStateText.Foreground = muted;
                _headerStateDot.Fill = muted;
                _headerStatePill.Background = Brush("SurfaceRaised");
                _headerStatePill.BorderBrush = Brush("Border");
                _headerStatePill.ToolTip = "YOMI is ready.";
                _runtimeText.Text = "";
                _runtimeText.Foreground = muted;
                _runtimePill.Background = Brushes.Transparent;
                _runtimePill.BorderBrush = Brushes.Transparent;
                _systemStatusText.Text = "";
            }
            else if (phase == "starting")
            {
                _headerStateText.Text = "Ready";
                _headerStateText.Foreground = muted;
                _headerStateDot.Fill = muted;
                _headerStatePill.Background = Brush("SurfaceRaised");
                _headerStatePill.BorderBrush = Brush("Border");
                _headerStatePill.ToolTip = "YOMI is ready.";
                _runtimeText.Text = "";
                _runtimeText.Foreground = muted;
                _runtimePill.Background = Brushes.Transparent;
                _runtimePill.BorderBrush = Brushes.Transparent;
                _systemStatusText.Text = "";
            }
            else if (phase == "advancing")
            {
                _headerStateText.Text = "Ready";
                _headerStateText.Foreground = muted;
                _headerStateDot.Fill = muted;
                _headerStatePill.Background = Brush("SurfaceRaised");
                _headerStatePill.BorderBrush = Brush("Border");
