            CloseOperatorDeck();
            StartOperatorIntent(BuildFocusPlayerIntent("operator deck"));
        }

        private void RunOperatorVisualShow()
        {
            CloseOperatorDeck();
            StartOperatorIntent(BuildVisualShowIntent("operator deck"));
        }

