        private void RefreshIntentFabricUi()
        {
            if (_intentActiveText == null) return;
            if (_activeIntent == null)
            {
                _intentActiveText.Text = "NO ACTIVE INTENT  |  operator lease idle";
                _intentAbortButton.IsEnabled = false;
            }
            else
            {
                string caps = _activeIntent.Capabilities == null ? "" : String.Join(", ", _activeIntent.Capabilities.ToArray());
                string step = _activeIntent.StepIndex >= 0 && _activeIntent.StepIndex < _activeIntent.Steps.Count
                    ? _activeIntent.Steps[_activeIntent.StepIndex].Name : "terminal";
                string stepId = _activeIntent.StepIndex >= 0 && _activeIntent.StepIndex < _activeIntent.Steps.Count ? _activeIntent.Steps[_activeIntent.StepIndex].Id : "-";
                _intentActiveText.Text = _activeIntent.State + "  |  " + _activeIntent.PlanName + "  |  " + ShortIntentId(_activeIntent.Id) +
                    "  |  STEP " + stepId + " " + step + "  |  DONE " + _activeIntent.CompletedStepIds.Count.ToString(CultureInfo.InvariantCulture) + "/" + _activeIntent.Steps.Count.ToString(CultureInfo.InvariantCulture) +
                    (String.IsNullOrWhiteSpace(caps) ? "" : "  |  LEASE " + caps);
                _intentAbortButton.IsEnabled = !IsTerminalIntentState(_activeIntent.State);
            }
            _intentChainText.Text = (_intentJournalHealthy ? "CHAIN VERIFIED" : "RECOVERY CHAIN") +
                "  |  SEQ " + _intentJournalSequence.ToString(CultureInfo.InvariantCulture) +
                "  |  HEAD " + ShortHash(_intentJournalHeadHash) +
                (String.IsNullOrWhiteSpace(_intentJournalRecoveryReason) ? "" : "  |  " + _intentJournalRecoveryReason);
            UpdateIntentRailChip();
        }

        private void CopyIntentTrace()
        {
            try
            {
                var lines = new List<string>();
                lines.Add("YOMI DEV13.37.2 INTENT FABRIC");
                lines.Add(_intentActiveText.Text ?? "");
                lines.Add(_intentChainText.Text ?? "");
                lines.Add("");
                foreach (var row in _intentRows.Take(30))
                    lines.Add(row.SequenceText + "  " + row.State + "  " + row.Plan + "  " + row.Step + "  " + row.Reason + "  " + row.HashShort);
                Clipboard.SetText(String.Join(Environment.NewLine, lines.ToArray()));
                ShowToast("Intent trace copied", "Latest operator provenance copied to clipboard");
            }
            catch { }
        }

        private void LoadIntentJournal()
        {
            Directory.CreateDirectory(_stateRoot);
            _intentJournalPath = IntentJournalDefaultPath;
            long persistedSequence = 0;
            string persistedHash = "GENESIS";
            bool headExists = false;
            try
            {
                var head = ReadJsonCached(IntentJournalHeadPath);
                headExists = head != null && head.Count > 0;
                string journalFile = GetString(head, "journal_file", "");
                persistedSequence = GetInt(head, "sequence", 0);
                persistedHash = GetString(head, "head_hash", "GENESIS");
                _intentJournalRecoveryReason = GetString(head, "recovery_reason", "");
                if (!String.IsNullOrWhiteSpace(journalFile))
                {
                    string candidate = Path.Combine(_stateRoot, Path.GetFileName(journalFile));
                    _intentJournalPath = candidate;
                }
            }
            catch { }

            string detail;
            if (File.Exists(_intentJournalPath))
            {
                if (!VerifyIntentJournalFile(_intentJournalPath, true, out detail))
                {
                    EnterIntentRecoveryChain("journal verification failed | " + detail);
                    return;
                }

                // Reconcile the separately persisted head against the durable journal.
                // Tail-newer-than-head is crash-compatible only when the historical head
                // hash can be proven at the persisted sequence. Head-newer-than-tail or
                // same-sequence/different-hash is inconsistent and is preserved as evidence.
                if (headExists)
                {
                    if (persistedSequence > _intentJournalSequence)
                    {
                        EnterIntentRecoveryChain("head ahead of durable journal tail");
                        return;
                    }
                    if (persistedSequence == _intentJournalSequence &&
                        !String.Equals(persistedHash, _intentJournalHeadHash, StringComparison.OrdinalIgnoreCase))
                    {
                        EnterIntentRecoveryChain("head/tail hash disagreement at sequence " + persistedSequence.ToString(CultureInfo.InvariantCulture));
                        return;
                    }
                    if (persistedSequence < _intentJournalSequence)
                    {
                        string proven = ReadIntentHashAtSequence(_intentJournalPath, persistedSequence);
                        bool provenHead = persistedSequence == 0
                            ? String.Equals(persistedHash, "GENESIS", StringComparison.OrdinalIgnoreCase) || (persistedHash ?? "").StartsWith("RECOVERY:", StringComparison.OrdinalIgnoreCase)
                            : !String.IsNullOrWhiteSpace(proven) && String.Equals(proven, persistedHash, StringComparison.OrdinalIgnoreCase);
                        if (!provenHead)
                        {
                            EnterIntentRecoveryChain("lagging head could not be proven inside durable chain");
                            return;
                        }
                        _intentJournalRecoveryReason = "crash-lagging head reconciled to durable tail";
                        PersistIntentHead();
                    }
                }
                else
                {
                    PersistIntentHead();
                }
            }
            else
            {
                if (headExists && persistedSequence > 0)
                {
                    _intentJournalSequence = persistedSequence;
                    _intentJournalHeadHash = persistedHash;
                    EnterIntentRecoveryChain("persisted head exists but journal file is missing");
                    return;
                }
                _intentJournalSequence = 0;
                _intentJournalHeadHash = headExists && !String.IsNullOrWhiteSpace(persistedHash) ? persistedHash : "GENESIS";
                PersistIntentHead();
            }

            ReconcileOrphanedJournalIntent();
        }

        private void ReconcileOrphanedJournalIntent()
        {
            if (String.IsNullOrWhiteSpace(_lastJournalIntentId) || IsTerminalIntentState(_lastJournalState)) return;
            var orphan = new IntentExecution
            {
                Id = _lastJournalIntentId,
                Trigger = _lastJournalTrigger,
                PlanName = String.IsNullOrWhiteSpace(_lastJournalPlan) ? "Recovered operator intent" : _lastJournalPlan,
                PlanFingerprint = _lastJournalFingerprint,
                State = _lastJournalState,
                Capabilities = new List<string>()
            };
            string terminal = String.Equals(_lastJournalState, "AWAITING_AUTHORITY", StringComparison.OrdinalIgnoreCase)
                ? "INDETERMINATE" : "ABANDONED";
            string reason = terminal == "INDETERMINATE"
                ? "controller restart occurred while awaiting engine authority; automatic replay/compensation prohibited"
                : "controller restart interrupted a non-authority operator plan; prior lease considered expired";
            AppendIntentTransition(orphan, terminal, String.IsNullOrWhiteSpace(_lastJournalStep) ? "startup recovery" : _lastJournalStep, reason);
            AddActivity("Intent recovery", orphan.PlanName + " -> " + terminal);
        }

        private string ReadIntentHashAtSequence(string path, long wantedSequence)
        {
            if (wantedSequence <= 0) return "GENESIS";
            try
            {
                foreach (string raw in File.ReadLines(path, Encoding.UTF8))
                {
                    string line = (raw ?? "").Trim();
                    if (line.Length == 0) continue;
                    var map = _json.Deserialize<Dictionary<string, object>>(line);
                    long sequence = GetInt(map, "sequence", 0);
                    if (sequence == wantedSequence) return GetString(map, "entry_hash", "");
                    if (sequence > wantedSequence) break;
                }
            }
            catch { }
            return "";
        }

        private bool VerifyIntentJournalFile(string path, bool loadRows, out string detail)
        {
            detail = "empty";
            if (String.IsNullOrWhiteSpace(path) || !File.Exists(path))
            {
                _intentJournalSequence = 0;
                _intentJournalHeadHash = "GENESIS";
                return true;
            }
            long lastSequence = 0;
            string previousHash = null;
            int records = 0;
            var loaded = new List<IntentDisplayRow>();
            try
            {
                foreach (string raw in File.ReadLines(path, Encoding.UTF8))
                {
                    string line = (raw ?? "").Trim();
                    if (line.Length == 0) continue;
                    var map = _json.Deserialize<Dictionary<string, object>>(line);
                    long seq = GetInt(map, "sequence", 0);
                    string utc = GetString(map, "utc", "");
                    string intentId = GetString(map, "intent_id", "");
                    string trigger = GetString(map, "trigger", "recovery");
                    string plan = GetString(map, "plan", "");
                    string fingerprint = GetString(map, "plan_fingerprint", "");
                    string state = GetString(map, "state", "");
                    string step = GetString(map, "step", "");
                    string reason = GetString(map, "reason", "");
                    string prev = GetString(map, "prev_hash", "");
                    string hash = GetString(map, "entry_hash", "");
                    if (seq <= 0 || (records > 0 && seq != lastSequence + 1))
                    {
                        _intentJournalSequence = lastSequence;
                        _intentJournalHeadHash = records > 0 ? previousHash : "GENESIS";
                        detail = "sequence discontinuity at " + seq.ToString(CultureInfo.InvariantCulture);
                        return false;
                    }
                    if (records > 0 && !String.Equals(prev, previousHash, StringComparison.OrdinalIgnoreCase))
                    {
                        _intentJournalSequence = lastSequence;
                        _intentJournalHeadHash = previousHash ?? "GENESIS";
                        detail = "previous-hash mismatch at " + seq.ToString(CultureInfo.InvariantCulture);
                        return false;
                    }
                    string expected = ComputeIntentJournalHash(seq, utc, intentId, plan, fingerprint, state, step, reason, prev);
                    if (!String.Equals(expected, hash, StringComparison.OrdinalIgnoreCase))
                    {
                        _intentJournalSequence = lastSequence;
                        _intentJournalHeadHash = records > 0 ? previousHash : "GENESIS";
                        detail = "entry-hash mismatch at " + seq.ToString(CultureInfo.InvariantCulture);
                        return false;
                    }
                    lastSequence = seq;
                    previousHash = hash;
                    records++;
                    _lastJournalIntentId = intentId;
                    _lastJournalTrigger = trigger;
                    _lastJournalPlan = plan;
                    _lastJournalFingerprint = fingerprint;
                    _lastJournalState = state;
                    _lastJournalStep = step;
                    loaded.Add(new IntentDisplayRow(seq, utc, state, plan, step, reason, hash));
                }
                _intentJournalSequence = lastSequence;
                _intentJournalHeadHash = records > 0 ? previousHash : "GENESIS";
                if (loadRows)
                {
                    _intentRows.Clear();
                    foreach (var row in loaded.AsEnumerable().Reverse().Take(80)) _intentRows.Add(row);
                }
                detail = records.ToString(CultureInfo.InvariantCulture) + " records | head " + ShortHash(_intentJournalHeadHash);
                return true;
            }
            catch (Exception ex)
            {
                detail = "parse failure | " + ex.GetType().Name;
                return false;
            }
        }

        private void VerifyIntentJournalInteractive()
        {
            string detail;
            bool ok = VerifyIntentJournalFile(_intentJournalPath, false, out detail);
            if (ok)
            {
                _intentJournalHealthy = true;
                _intentJournalRecoveryReason = "";
                PersistIntentHead();
            }
            else
            {
                EnterIntentRecoveryChain("interactive verification failed | " + detail);
            }
            RefreshIntentFabricUi();
            ShowToast(ok ? "Intent chain verified" : "Intent recovery chain opened", detail);
            AddActivity("Intent", (ok ? "chain verified | " : "recovery chain | ") + detail);
        }

        private void EnterIntentRecoveryChain(string reason)
        {
            string ancestor = _intentJournalHeadHash ?? "GENESIS";
            _intentJournalHealthy = false;
            _intentJournalRecoveryReason = reason ?? "prior journal invalid";
            string suffix = DateTime.UtcNow.ToString("yyyyMMdd-HHmmssfff", CultureInfo.InvariantCulture);
            _intentJournalPath = Path.Combine(_stateRoot, "controller-intent-journal-recovery-" + suffix + ".jsonl");
            _intentJournalSequence = 0;
            _intentJournalHeadHash = "RECOVERY:" + ShortHash(ancestor);
            PersistIntentHead();
        }

        private void PersistIntentHead()
        {
            try
            {
                var head = new Dictionary<string, object>();
                head["schema"] = 1;
                head["sequence"] = _intentJournalSequence;
                head["head_hash"] = _intentJournalHeadHash ?? "GENESIS";
                head["journal_file"] = Path.GetFileName(_intentJournalPath ?? IntentJournalDefaultPath);
                head["healthy"] = _intentJournalHealthy;
                head["recovery_reason"] = _intentJournalRecoveryReason ?? "";
                head["updated_utc"] = DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture);
                WriteUtf8NoBom(IntentJournalHeadPath, _json.Serialize(head));
            }
            catch { }
        }

        private void AppendIntentTransition(IntentExecution run, string state, string step, string reason)
        {
            if (run == null) return;
            Directory.CreateDirectory(_stateRoot);
            long sequence = _intentJournalSequence + 1;
            string utc = DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture);
            string prev = _intentJournalHeadHash ?? "GENESIS";
            string hash = ComputeIntentJournalHash(sequence, utc, run.Id, run.PlanName, run.PlanFingerprint, state, step, reason, prev);
            var map = new Dictionary<string, object>();
            map["schema"] = 1;
            map["sequence"] = sequence;
            map["utc"] = utc;
            map["intent_id"] = run.Id;
            map["trigger"] = run.Trigger;
            map["plan"] = run.PlanName;
            map["plan_fingerprint"] = run.PlanFingerprint;
            map["state"] = state;
            map["step"] = step ?? "";
            map["reason"] = reason ?? "";
            map["session_id"] = _sessionId ?? "";
            map["order_revision"] = _orderRevision;
            map["process_id"] = Process.GetCurrentProcess().Id;
            map["capabilities"] = run.Capabilities == null ? "" : String.Join(",", run.Capabilities.ToArray());
            map["prev_hash"] = prev;
            map["entry_hash"] = hash;
            try
            {
                File.AppendAllText(_intentJournalPath, _json.Serialize(map) + Environment.NewLine, new UTF8Encoding(false));
                _intentJournalSequence = sequence;
                _intentJournalHeadHash = hash;
                PersistIntentHead();
                _intentRows.Insert(0, new IntentDisplayRow(sequence, utc, state, run.PlanName, step, reason, hash));
                while (_intentRows.Count > 80) _intentRows.RemoveAt(_intentRows.Count - 1);
            }
            catch
            {
                _intentJournalHealthy = false;
                _intentJournalRecoveryReason = "append failure";
            }
            run.State = state;
            run.LastReason = reason ?? "";
            RefreshIntentFabricUi();
        }

        private string ComputeIntentJournalHash(long sequence, string utc, string intentId, string plan, string fingerprint, string state, string step, string reason, string prev)
        {
            return Sha256Hex(String.Join("\u001f", new[]
            {
                sequence.ToString(CultureInfo.InvariantCulture), utc ?? "", intentId ?? "", plan ?? "", fingerprint ?? "",
                state ?? "", step ?? "", reason ?? "", prev ?? ""
            }));
        }

        private static string Sha256Hex(string text)
        {
            using (var sha = SHA256.Create())
            {
                byte[] hash = sha.ComputeHash(Encoding.UTF8.GetBytes(text ?? ""));
                var sb = new StringBuilder(hash.Length * 2);
                foreach (byte b in hash) sb.Append(b.ToString("x2", CultureInfo.InvariantCulture));
                return sb.ToString();
            }
        }

        private static string ShortHash(string hash)
        {
            if (String.IsNullOrWhiteSpace(hash)) return "-";
            return hash.Length <= 12 ? hash.ToUpperInvariant() : hash.Substring(0, 12).ToUpperInvariant();
        }

        private static string ShortIntentId(string id)
        {
            if (String.IsNullOrWhiteSpace(id)) return "-";
            return id.Length <= 10 ? id : id.Substring(id.Length - 10);
        }

        private bool TryAcquireIntentLease()
        {
            if (_intentLeaseHeld) return true;
            try
            {
                _intentLeaseHeld = _intentLeaseMutex.WaitOne(0);
            }
            catch (AbandonedMutexException)
            {
                _intentLeaseHeld = true;
            }
            return _intentLeaseHeld;
        }

        private void ReleaseIntentLease()
        {
            if (!_intentLeaseHeld) return;
            try { _intentLeaseMutex.ReleaseMutex(); } catch { }
            _intentLeaseHeld = false;
        }

        private bool CheckIntentAdmission(IntentExecution run, out string reason)
        {
            reason = "admitted";
            var queue = ReadJsonCached(Path.Combine(_stateRoot, "queue-runtime.json"));
            string governor = GetString(GetMap(queue, "resource"), "governor_mode", "-").ToUpperInvariant();
            string service = GetString(GetMap(queue, "service_level"), "state", "-").ToUpperInvariant();
            string buffer = GetString(queue, "buffer_health", "-").ToUpperInvariant();
            string oracle = GetString(GetMap(queue, "oracle"), "verdict", "-").ToUpperInvariant();
            run.AdmissionSnapshot = "runtime=" + (_running ? (_paused ? "PAUSED" : "LIVE") : "OFFLINE") +
                ";session=" + (String.IsNullOrWhiteSpace(_sessionId) ? "-" : _sessionId.Substring(0, Math.Min(8, _sessionId.Length))) +
                ";order=R" + _orderRevision.ToString(CultureInfo.InvariantCulture) +
                ";pending_order=" + (OrderMutationBusy ? "YES" : "NO") +
                ";buffer=" + buffer + ";service=" + service + ";oracle=" + oracle + ";governor=" + governor;

            if (run.RequiresRunning && !_running)
            {
                reason = "active playback runtime required | " + run.AdmissionSnapshot;
                return false;
            }
            if (run.RequiresStableOrder && OrderMutationBusy)
            {
                reason = "authoritative order mutation is still pending | " + run.AdmissionSnapshot;
                return false;
            }
            if (run.BroadcastSensitive && (governor == "EMERGENCY" || governor == "SAFE_MODE"))
            {
                reason = "Aegis " + governor + " blocks optional broadcast orchestration | " + run.AdmissionSnapshot;
                return false;
            }
            reason = "policy admitted | " + run.AdmissionSnapshot;
            return true;
        }

        private void StartOperatorIntent(IntentExecution run)
        {
            if (run == null) return;
            long now = _clock.ElapsedMilliseconds;
            if (_activeIntent != null && !IsTerminalIntentState(_activeIntent.State))
            {
                ShowToast("Operator intent busy", _activeIntent.PlanName + " is already " + _activeIntent.State + ".");
                return;
            }
            if (String.Equals(_lastIntentPlan, run.PlanName, StringComparison.OrdinalIgnoreCase) && now - _lastIntentStartMs < 750)
            {
                ShowToast("Intent deduplicated", run.PlanName + " was just requested.");
                return;
            }
            _lastIntentPlan = run.PlanName;
            _lastIntentStartMs = now;
            AppendIntentTransition(run, "PLANNED", "admission", "plan constructed | fingerprint " + ShortHash(run.PlanFingerprint));
            string admissionReason;
            if (!CheckIntentAdmission(run, out admissionReason))
            {
                AppendIntentTransition(run, "REJECTED", "admission", admissionReason);
                ShowToast(run.PlanName + " rejected", admissionReason);
                AddActivity("Intent", run.PlanName + " rejected | " + admissionReason);
                return;
            }
            if (!TryAcquireIntentLease())
            {
                AppendIntentTransition(run, "REJECTED", "capability lease", "operator intent lease unavailable");
                ShowToast(run.PlanName + " rejected", "Operator capability lease is held elsewhere.");
                return;
            }
            _activeIntent = run;
            AppendIntentTransition(run, "ADMITTED", "admission", "capability lease acquired | " + admissionReason);
            AddActivity("Intent", run.PlanName + " admitted | " + ShortIntentId(run.Id));
            AdvanceActiveIntent();
        }

        private void AdvanceActiveIntent()
        {
            var run = _activeIntent;
            if (run == null || IsTerminalIntentState(run.State)) return;
            if (run.CancelRequested)
            {
                CompleteIntent(run, run.AuthorityCommandOutstanding ? "INDETERMINATE" : "CANCELLED", "operator cancellation requested", !run.AuthorityCommandOutstanding);
                return;
            }
            if (run.StepIndex >= run.Steps.Count)
            {
                CompleteIntent(run, "COMMITTED", "all dependency-graph nodes committed", false);
                return;
            }
            if (run.StepIndex < 0)
            {
                CompleteIntent(run, "FAILED", "dependency graph has no runnable node", true);
                return;
            }

            var step = run.Steps[run.StepIndex];
            if (!run.StepBegun)
            {
                run.StepBegun = true;
                run.StepStartedMs = _clock.ElapsedMilliseconds;
                AppendIntentTransition(run, "EXECUTING", step.Id + " " + step.Name, "begin | capability " + step.Capability + (step.DependsOn.Count > 0 ? " | deps " + String.Join(",", step.DependsOn.ToArray()) : " | root"));
                try
                {
                    if (step.Begin != null) step.Begin(run);
                    if (step.AuthorityBound) run.AuthorityCommandOutstanding = true;
                }
                catch (Exception ex)
                {
                    CompleteIntent(run, "FAILED", step.Name + " threw " + ex.GetType().Name, true);
                    return;
                }
            }

            IntentStepVerdict verdict = IntentStepVerdict.Succeeded;
            try
            {
                if (step.Observe != null) verdict = step.Observe(run);
            }
            catch
            {
                verdict = IntentStepVerdict.Failed;
            }

            if (verdict == IntentStepVerdict.Succeeded)
            {
                if (step.AuthorityBound) run.AuthorityCommandOutstanding = false;
                run.CompletedSteps.Add(step);
                run.CompletedStepIds.Add(step.Id);
                AppendIntentTransition(run, "EXECUTING", step.Id + " " + step.Name, step.AuthorityBound ? "authority confirmed" : "step committed");
                run.StepIndex = ResolveNextIntentStepIndex(run);
                run.StepBegun = false;
                ScheduleUiAction(1, AdvanceActiveIntent);
                return;
            }
            if (verdict == IntentStepVerdict.Failed)
            {
                CompleteIntent(run, "FAILED", step.Name + " reported failure", !step.AuthorityBound);
                return;
            }
            if (verdict == IntentStepVerdict.Indeterminate)
            {
                CompleteIntent(run, "INDETERMINATE", step.Name + " authority became ambiguous", false);
                return;
            }

            long elapsed = _clock.ElapsedMilliseconds - run.StepStartedMs;
            if (step.TimeoutMs > 0 && elapsed > step.TimeoutMs)
            {
                string terminal = step.AuthorityBound ? "INDETERMINATE" : "FAILED";
                CompleteIntent(run, terminal, step.Name + " timeout after " + step.TimeoutMs.ToString(CultureInfo.InvariantCulture) + "ms", !step.AuthorityBound);
                return;
            }
            if (!String.Equals(run.State, "AWAITING_AUTHORITY", StringComparison.Ordinal))
                AppendIntentTransition(run, "AWAITING_AUTHORITY", step.Id + " " + step.Name, "waiting for observable commit evidence");
            ScheduleUiAction(200, AdvanceActiveIntent);
        }

        private void CompleteIntent(IntentExecution run, string terminalState, string reason, bool compensate)
        {
            if (run == null) return;
            if (compensate && run.CompletedSteps.Count > 0)
            {
                AppendIntentTransition(run, "COMPENSATING", "rollback", "reverting safe shell-side effects");
                for (int i = run.CompletedSteps.Count - 1; i >= 0; i--)
                {
                    var step = run.CompletedSteps[i];
                    if (step.Compensate == null) continue;
                    try { step.Compensate(run); }
                    catch { }
                }
            }
            AppendIntentTransition(run, terminalState, "terminal", reason);
            _lastOperatorAction = run.PlanName.ToUpperInvariant();
            AddActivity("Intent", run.PlanName + " " + terminalState.ToLowerInvariant() + " | " + reason);
            ReleaseIntentLease();
            _activeIntent = null;
            RefreshIntentFabricUi();
            ShowToast(run.PlanName + " | " + terminalState, reason);
        }

        private void RequestCancelActiveIntent(string reason)
        {
            if (_activeIntent == null || IsTerminalIntentState(_activeIntent.State))
            {
                ShowToast("Operator intent", "No active intent to abort.");
                return;
            }
            _activeIntent.CancelRequested = true;
            AppendIntentTransition(_activeIntent, "CANCELLING", "operator", reason ?? "cancel requested");
            ScheduleUiAction(1, AdvanceActiveIntent);
        }

        private static bool IsTerminalIntentState(string state)
        {
            return state == "COMMITTED" || state == "FAILED" || state == "CANCELLED" || state == "INDETERMINATE" || state == "REJECTED" || state == "ABANDONED";
        }

        private IntentExecution NewIntent(string planName, string trigger, bool requiresRunning, bool stableOrder, bool broadcastSensitive, params IntentStepDefinition[] steps)
        {
            var list = new List<IntentStepDefinition>(steps ?? new IntentStepDefinition[0]);
            for (int i = 0; i < list.Count; i++)
            {
                if (String.IsNullOrWhiteSpace(list[i].Id)) list[i].Id = "S" + (i + 1).ToString("00", CultureInfo.InvariantCulture);
                if (i > 0 && (list[i].DependsOn == null || list[i].DependsOn.Count == 0))
                    list[i].DependsOn = new List<string> { list[i - 1].Id };
            }
            string graphReason;
            if (!ValidateIntentDependencyGraph(list, out graphReason))
                throw new InvalidOperationException("Intent plan dependency graph invalid: " + graphReason);

            string spec = planName + "|" + String.Join("|", list.Select(s => s.Id + ":" + s.Name + ":" + s.Capability + ":deps=" + String.Join(",", s.DependsOn.ToArray()) + ":" + s.TimeoutMs.ToString(CultureInfo.InvariantCulture) + ":" + s.AuthorityBound).ToArray());
            var run = new IntentExecution();
            run.Id = "INT-" + DateTime.UtcNow.ToString("yyyyMMddHHmmssfff", CultureInfo.InvariantCulture) + "-" + Guid.NewGuid().ToString("N").Substring(0, 8).ToUpperInvariant();
            run.PlanName = planName;
            run.Trigger = trigger ?? "unknown";
            run.PlanFingerprint = Sha256Hex(spec);
            run.RequiresRunning = requiresRunning;
            run.RequiresStableOrder = stableOrder;
            run.BroadcastSensitive = broadcastSensitive;
            run.Steps = list;
            run.Capabilities = list.Select(s => s.Capability).Where(s => !String.IsNullOrWhiteSpace(s)).Distinct(StringComparer.OrdinalIgnoreCase).OrderBy(s => s).ToList();
            run.Snapshot = CaptureShellSnapshot();
            run.StepIndex = ResolveNextIntentStepIndex(run);
            return run;
        }

        private bool ValidateIntentDependencyGraph(List<IntentStepDefinition> steps, out string reason)
        {
            reason = "valid";
            if (steps == null || steps.Count == 0) { reason = "plan contains no steps"; return false; }
            var byId = new Dictionary<string, IntentStepDefinition>(StringComparer.OrdinalIgnoreCase);
            foreach (var step in steps)
            {
                if (step == null || String.IsNullOrWhiteSpace(step.Id)) { reason = "step id missing"; return false; }
                if (byId.ContainsKey(step.Id)) { reason = "duplicate step id " + step.Id; return false; }
                if (String.IsNullOrWhiteSpace(step.Capability)) { reason = "capability missing for " + step.Id; return false; }
                if (step.AuthorityBound && step.TimeoutMs <= 0) { reason = "authority step lacks timeout " + step.Id; return false; }
                if (step.AuthorityBound && step.Compensate != null) { reason = "authority step cannot declare blind compensation " + step.Id; return false; }
                byId[step.Id] = step;
            }
            foreach (var step in steps)
            {
                foreach (string dep in step.DependsOn ?? new List<string>())
                {
                    if (!byId.ContainsKey(dep)) { reason = step.Id + " depends on missing " + dep; return false; }
                    if (String.Equals(step.Id, dep, StringComparison.OrdinalIgnoreCase)) { reason = step.Id + " self-dependency"; return false; }
                }
            }

            var visiting = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            var visited = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            Func<string, bool> visit = null;
            visit = delegate(string id)
            {
                if (visited.Contains(id)) return true;
                if (!visiting.Add(id)) return false;
                foreach (string dep in byId[id].DependsOn ?? new List<string>())
                    if (!visit(dep)) return false;
                visiting.Remove(id);
                visited.Add(id);
                return true;
            };
            foreach (string id in byId.Keys)
            {
                if (!visit(id)) { reason = "dependency cycle involving " + id; return false; }
            }
            return true;
        }

        private int ResolveNextIntentStepIndex(IntentExecution run)
        {
            if (run == null || run.Steps == null) return -1;
            for (int i = 0; i < run.Steps.Count; i++)
            {
                var step = run.Steps[i];
                if (run.CompletedStepIds.Contains(step.Id)) continue;
                bool ready = true;
                foreach (string dep in step.DependsOn ?? new List<string>())
                    if (!run.CompletedStepIds.Contains(dep)) { ready = false; break; }
                if (ready) return i;
            }
            return run.CompletedStepIds.Count == run.Steps.Count ? run.Steps.Count : -1;
        }

        private ShellSnapshot CaptureShellSnapshot()
        {
            return new ShellSnapshot
            {
                Workspace = _workspaceProfile,
                Media = _mediaMode,
                Visualizer = _visualizerPresentation,
                VisualizerEnabled = _visualizerEnabled,
                QueueOpen = _queueOpen,
                QueueScope = _queueScope,
                InspectorOpen = _inspectorOpen
            };
        }

        private void RestoreShellSnapshot(ShellSnapshot snapshot)
        {
            if (snapshot == null) return;
            bool previousApplying = _applyingWorkspaceProfile;
            _applyingWorkspaceProfile = true;
            try
            {
                if (snapshot.Workspace != WorkspaceProfile.Custom) ApplyWorkspaceProfile(snapshot.Workspace, false);
                SetMediaMode(snapshot.Media, false);
                SetVisualizerPresentation(snapshot.Visualizer, false);
                SetVisualizerEnabled(snapshot.VisualizerEnabled, false);
                SetQueueOpen(snapshot.QueueOpen, false);
                SetQueueScope(snapshot.QueueScope);
                SetInspectorOpen(snapshot.InspectorOpen, false);
                _workspaceProfile = snapshot.Workspace;
            }
            finally
            {
                _applyingWorkspaceProfile = previousApplying;
            }
            SaveUiState();
        }

        private IntentStepDefinition ShellStep(string name, string capability, Action<IntentExecution> begin, Action<IntentExecution> compensate = null)
        {
            return new IntentStepDefinition { Name = name, Capability = capability, TimeoutMs = 0, AuthorityBound = false, Begin = begin, Observe = delegate { return IntentStepVerdict.Succeeded; }, Compensate = compensate };
        }

        private IntentStepDefinition AuthorityStep(string name, string capability, Action<IntentExecution> begin, Func<IntentExecution, IntentStepVerdict> observe, int timeoutMs)
        {
            return new IntentStepDefinition { Name = name, Capability = capability, TimeoutMs = timeoutMs, AuthorityBound = true, Begin = begin, Observe = observe };
        }

        private IntentExecution BuildPrimeBroadcastIntent(string trigger)
        {
            return NewIntent("Prime Broadcast", trigger, true, true, true,
                ShellStep("Checkpoint authoritative order", "shell.queue-checkpoint", delegate { SaveQueueCheckpoint(); }),
                ShellStep("Enter Broadcast workspace", "shell.workspace", delegate { ApplyWorkspaceProfile(WorkspaceProfile.Broadcast, true); }, delegate(IntentExecution r) { RestoreShellSnapshot(r.Snapshot); }),
                AuthorityStep("Rehearse next 10", "engine.rehearsal", delegate { StartBroadcastRehearsal(10); }, delegate
                {
                    var q = ReadJsonCached(Path.Combine(_stateRoot, "queue-runtime.json"));
                    var reh = GetMap(q, "rehearsal");
                    return GetBool(reh, "active", false) && GetInt(reh, "target", 0) >= 10 ? IntentStepVerdict.Succeeded : IntentStepVerdict.Pending;
                }, 4500));
        }

        private IntentExecution BuildLockWindowIntent(string trigger)
        {
            return NewIntent("Lock Broadcast Window", trigger, true, true, true,
                ShellStep("Checkpoint authoritative order", "shell.queue-checkpoint", delegate { SaveQueueCheckpoint(); }),
                ShellStep("Enter Broadcast workspace", "shell.workspace", delegate { ApplyWorkspaceProfile(WorkspaceProfile.Broadcast, true); }, delegate(IntentExecution r) { RestoreShellSnapshot(r.Snapshot); }),
                AuthorityStep("Establish rehearsal window", "engine.rehearsal", delegate { StartBroadcastRehearsal(10); }, delegate
                {
                    var q = ReadJsonCached(Path.Combine(_stateRoot, "queue-runtime.json"));
                    var reh = GetMap(q, "rehearsal");
                    return GetBool(reh, "active", false) && GetInt(reh, "target", 0) >= 10 ? IntentStepVerdict.Succeeded : IntentStepVerdict.Pending;
                }, 4500),
                AuthorityStep("Commit Broadcast Freeze", "engine.freeze", delegate(IntentExecution r)
                {
                    if (!IsBroadcastFreezeActive()) ToggleBroadcastFreeze();
                }, delegate
                {
                    return IsBroadcastFreezeActive() ? IntentStepVerdict.Succeeded : IntentStepVerdict.Pending;
                }, 3500));
        }

