        public bool SelfTestShellFidelity()
        {
            _selfTestFailureDetail = "";
            try
            {
                var chrome = System.Windows.Shell.WindowChrome.GetWindowChrome(_window);
                if (chrome == null || Math.Abs(chrome.CaptionHeight - 30) > 0.01) return SelfTestFail(chrome == null ? "WindowChrome was not attached to the loaded window" :
                    "WindowChrome caption expected 30; actual " + chrome.CaptionHeight.ToString(CultureInfo.InvariantCulture));
                if (Math.Abs(chrome.ResizeBorderThickness.Left - 4) > 0.01 || Math.Abs(chrome.ResizeBorderThickness.Top - 4) > 0.01 ||
                    Math.Abs(chrome.ResizeBorderThickness.Right - 4) > 0.01 || Math.Abs(chrome.ResizeBorderThickness.Bottom - 4) > 0.01)
                    return SelfTestFail("WindowChrome resize border expected 4 on every edge; actual " + chrome.ResizeBorderThickness.ToString());
                if (_window.MinWidth + 0.01 < MicroPlayerMinWidth || _window.MinHeight + 0.01 < MicroPlayerMinHeight) return SelfTestFail("adaptive shell minimum mismatch; expected Micro floor >=" +
                    MicroPlayerMinWidth.ToString(CultureInfo.InvariantCulture) + "x" + MicroPlayerMinHeight.ToString(CultureInfo.InvariantCulture) + "; actual " +
                    _window.MinWidth.ToString(CultureInfo.InvariantCulture) + "x" + _window.MinHeight.ToString(CultureInfo.InvariantCulture));
                if (_statusBarSurface == null || _hoverStatusText == null || _statusPlaybackText == null || _statusObsText == null || _statusVolumeText == null)
                    return SelfTestFail("adaptive shell status bar is incomplete");
                var titleBar = Find<Border>("TitleBar");
                if (titleBar.ActualHeight > 0 && Math.Abs(titleBar.ActualHeight - 30) > 1.1) return SelfTestFail("title bar expected 30px; actual " + titleBar.ActualHeight.ToString(CultureInfo.InvariantCulture));
                if (_classicMenu == null || Math.Abs(_classicMenu.Height - 24) > 0.01) return SelfTestFail("classic menu height expected 24; actual " + (_classicMenu == null ? "<null>" : _classicMenu.Height.ToString(CultureInfo.InvariantCulture)));
                Visibility oldMenuVisibility = _classicMenuBar == null ? Visibility.Collapsed : _classicMenuBar.Visibility;
                try
                {
                    // Realize the popup template deliberately. The normal Player profile keeps the
                    // classic menu collapsed, and a collapsed control is not a valid template probe.
                    if (_classicMenuBar != null) _classicMenuBar.Visibility = Visibility.Visible;
                    _window.UpdateLayout();
                    _fileMenu.ApplyTemplate();
                    if (_fileMenu.Template == null || _fileMenu.Template.FindName("PART_Popup", _fileMenu) == null)
                        return SelfTestFail("File menu template did not realize PART_Popup after explicit layout");
                }
                finally
                {
                    if (_classicMenuBar != null) _classicMenuBar.Visibility = oldMenuVisibility;
                }
                if (_window.TryFindResource("WindowChromeButton") == null || _window.TryFindResource("CloseWindowChromeButton") == null) return SelfTestFail("window chrome button styles did not resolve");

                var playerVideo = new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase)
                {
                    { "app_mode", "Streamer / OBS" },
                    { "video_enabled", true },
                    { "player_video_quality", "360p" },
                    { "overlay_video_quality", "240p" }
                };
                if (!String.Equals(EffectiveControllerVideoQuality(playerVideo), "360p", StringComparison.Ordinal)) return SelfTestFail("effective video quality mismatch: player360/overlay240");
                playerVideo["player_video_quality"] = "240p";
                playerVideo["overlay_video_quality"] = "360p";
                if (!String.Equals(EffectiveControllerVideoQuality(playerVideo), "360p", StringComparison.Ordinal)) return SelfTestFail("effective video quality mismatch: player240/overlay360");
                playerVideo["player_video_quality"] = "Off (audio only)";
                if (!String.Equals(EffectiveControllerVideoQuality(playerVideo), "360p", StringComparison.Ordinal)) return SelfTestFail("effective video quality mismatch: player off/overlay360");
                playerVideo["app_mode"] = "Player";
                if (!String.IsNullOrEmpty(EffectiveControllerVideoQuality(playerVideo))) return SelfTestFail("Player mode with player video off should request no video");
                playerVideo["player_video_quality"] = "240p";
                if (!String.Equals(EffectiveControllerVideoQuality(playerVideo), "240p", StringComparison.Ordinal)) return SelfTestFail("Player mode 240p should request 240p");

                Visibility oldVideoFrame = _videoFrameHost == null ? Visibility.Collapsed : _videoFrameHost.Visibility;
                Visibility oldVizFrame = _visualizerFrameHost == null ? Visibility.Collapsed : _visualizerFrameHost.Visibility;
                bool handled = false;
                WindowMessageHook(IntPtr.Zero, 0x0231, IntPtr.Zero, IntPtr.Zero, ref handled);
                if (!_liveResize) return SelfTestFail("interactive-resize enter did not set resize state");
                if (_videoHost.Visibility != Visibility.Collapsed || _visualizerHost.Visibility != Visibility.Collapsed) return SelfTestFail("retired MediaElement preview hosts were resurrected during resize");
                if (_videoPreviewReady && _videoFrameHost != null && _videoFrameHost.Visibility != Visibility.Visible) return SelfTestFail("WPF video frame disappeared during resize");
                if (_visualizerEnabled && _visualizerPreviewReady && _visualizerFrameHost != null && _visualizerFrameHost.Visibility != Visibility.Visible) return SelfTestFail("WPF visualizer frame disappeared during resize");
                WindowMessageHook(IntPtr.Zero, 0x0232, IntPtr.Zero, IntPtr.Zero, ref handled);
                if (_liveResize) return SelfTestFail("interactive-resize exit did not clear resize state");
                if (_videoHost.Visibility != Visibility.Collapsed || _visualizerHost.Visibility != Visibility.Collapsed) return SelfTestFail("retired MediaElement preview hosts changed after resize");
                if (!_videoPreviewReady && _videoFrameHost != null && _videoFrameHost.Visibility != oldVideoFrame) return SelfTestFail("idle video frame visibility changed across resize");
                if ((!_visualizerEnabled || !_visualizerPreviewReady) && _visualizerFrameHost != null && _visualizerFrameHost.Visibility != oldVizFrame) return SelfTestFail("idle visualizer frame visibility changed across resize");

                if (_settingsBroadcastCustomizeExpander == null || _playlistEditorOverlay == null || _playlistEditorBox == null || _playlistEditorSaveButton == null)
                    return SelfTestFail("R61.36 progressive-disclosure/native-text controls are missing");
                if (!(_inspectorTrackTitle is TextBox) || !(_inspectorRuntimeText is TextBox))
                    return SelfTestFail("Inspector content is not selectable text");
                if (_playbackSummaryText != null && _playbackSummaryText.Visibility != Visibility.Collapsed)
                    return SelfTestFail("redundant playback summary telemetry is visible");
                if (_favoritePill != null && _favoritePill.Visibility != Visibility.Collapsed)
                    return SelfTestFail("duplicate favorite badge is visible");
                ApplyHeaderSignalVisibility("playing", false);
                if (_headerStatePill != null && _headerStatePill.Visibility != Visibility.Collapsed)
                    return SelfTestFail("normal PLAYING state leaked into title-bar chrome");
                ApplyHeaderSignalVisibility("error", false);
                if (_headerStatePill != null && _headerStatePill.Visibility != Visibility.Visible)
                    return SelfTestFail("error state did not surface in title-bar chrome");
                ApplyHeaderSignalVisibility("playing", false);
                SetContextState(_nextUpStateText, "READY", Brush("Accent"), false);
                if (_nextUpStateText != null && _nextUpStateText.Visibility != Visibility.Collapsed)
                    return SelfTestFail("healthy NEXT readiness leaked into player chrome");
                bool oldQuiet = _quietSurface; string oldRepeat = _repeatMode; InformationDensity oldDensity = _informationDensity;
                try
                {
                    _quietSurface = true; _informationDensity = InformationDensity.Clean; _repeatMode = "all"; ApplyQuietSurface(false);
                    if (_footerHint != null && _footerHint.Visibility != Visibility.Collapsed) return SelfTestFail("quiet surface leaked shortcut wallpaper");
                    if (_repeatStatePill != null && _repeatStatePill.Visibility != Visibility.Visible) return SelfTestFail("Repeat control disappeared in quiet transport chrome");
                    if (_miniRepeatButton2 != null && !String.Equals(Convert.ToString(_miniRepeatButton2.Content, CultureInfo.InvariantCulture), "Repeat All", StringComparison.Ordinal)) return SelfTestFail("compact repeat affordance did not project Repeat All");
                    _repeatMode = "one"; UpdateRepeatPill();
                    if (_repeatStatePill != null && _repeatStatePill.Visibility != Visibility.Visible) return SelfTestFail("non-default repeat mode failed to surface");
                }
                finally
                {
                    _quietSurface = oldQuiet; _repeatMode = oldRepeat; _informationDensity = oldDensity; ApplyQuietSurface(false);
                }
                return true;
            }
            catch (Exception ex) { return SelfTestFail("shell-fidelity exception: " + ex.GetType().Name + ": " + ex.Message); }
        }

