    internal sealed class FfmpegFramePreview : IDisposable
    {
        private readonly string _ffmpeg;
        private readonly string _arguments;
        private readonly Image _target;
        private readonly int _width;
        private readonly int _height;
        private readonly double _fps;
        private readonly double _startMediaTime;
        private readonly bool _lowPriority;
        private readonly Func<Process, bool> _processOwner;
        private readonly Action _firstFrame;
        private readonly Action<string> _failed;
        private readonly Action<PreviewCadenceMetrics> _cadenceMeasured;
        private readonly Dispatcher _dispatcher;
        private readonly WriteableBitmap _bitmap;
        private readonly object _clockSync = new object();
        private readonly object _frameSync = new object();
        private double _clockMediaTime;
        private long _clockStamp;
        private bool _clockPaused;
        private Process _process;
        private Thread _worker;
        private volatile bool _stopping;
        private int _failureSent;
        private bool _deliveredFirstFrame;
        private readonly StringBuilder _errors = new StringBuilder();
        private readonly object _errorSync = new object();
        private byte[] _mailboxFrame;
        private readonly byte[] _presentFrame;
        private long _mailboxVersion;
        private long _paintedVersion;
        private EventHandler _renderHandler;
        private DispatcherTimer _presentationTimer;
        private readonly double _presentationFps;
        private long _nextPresentationStamp;
        private long _lastPresentationStamp;
        private long _measureStartedStamp;
        private int _measureFrames;
        private int _measureDecodedFrames;
        private int _measureMailboxOverwrites;
        private int _measureMissedDeadlines;
        private readonly double[] _intervalErrors = new double[180];
        private int _intervalErrorCount;
        private int _intervalErrorCursor;
        private double _intervalErrorSquareSum;
        private double _intervalSumMs;
        private double _maxIntervalErrorMs;
        private readonly long _periodTicks;

        public FfmpegFramePreview(string ffmpeg, string arguments, Image target, int width, int height, double fps, double startMediaTime, bool lowPriority, Action<PreviewCadenceMetrics> cadenceMeasured, Func<Process, bool> processOwner, Action firstFrame, Action<string> failed)
        {
            _ffmpeg = ffmpeg;
            _arguments = arguments;
            _target = target;
            _width = width;
            _height = height;
            _fps = Math.Max(1.0, fps);
            // R61.94: visualizer local preview is intentionally capped at a coalescing 30-FPS
            // dispatcher pump. OBS output keeps its independent configured cadence.
            _presentationFps = lowPriority ? Math.Min(30.0, _fps) : _fps;
            _startMediaTime = Math.Max(0, startMediaTime);
            _lowPriority = lowPriority;
            _cadenceMeasured = cadenceMeasured;
            _clockMediaTime = _startMediaTime;
            _clockStamp = Stopwatch.GetTimestamp();
            _processOwner = processOwner;
            _firstFrame = firstFrame;
            _failed = failed;
            _dispatcher = target.Dispatcher;
            _bitmap = new WriteableBitmap(width, height, 96, 96, PixelFormats.Bgra32, null);
            _mailboxFrame = new byte[Math.Max(1, width * height * 4)];
            _presentFrame = new byte[_mailboxFrame.Length];
            _periodTicks = Math.Max(1, (long)Math.Round(Stopwatch.Frequency / _presentationFps));
            _measureStartedStamp = Stopwatch.GetTimestamp();
        }

        public bool CanCoalesce
        {
            get
            {
                if (_stopping || Volatile.Read(ref _failureSent) != 0) return false;
                Thread worker = _worker;
                return worker == null || worker.IsAlive;
            }
        }

        public int ProcessId
        {
            get { try { Process process = _process; return process != null && !process.HasExited ? process.Id : 0; } catch { return 0; } }
        }

        public double TargetFps { get { return _fps; } }
        public bool IsRunning
        {
            get { try { Process process = _process; return !_stopping && process != null && !process.HasExited; } catch { return false; } }
        }
        public double LastPresentationAgeMs
        {
            get
            {
                long stamp = Interlocked.Read(ref _lastPresentationStamp);
                if (stamp <= 0) return -1.0;
                return Math.Max(0.0, (Stopwatch.GetTimestamp() - stamp) * 1000.0 / Stopwatch.Frequency);
            }
        }

        public void UpdateClock(double mediaTime, bool paused)
        {
            lock (_clockSync)
            {
                bool wasPaused = _clockPaused;
                _clockMediaTime = Math.Max(0, mediaTime);
                _clockPaused = paused;
                _clockStamp = Stopwatch.GetTimestamp();
                if (wasPaused != paused)
                {
                    _nextPresentationStamp = 0;
                    _lastPresentationStamp = 0;
                }
            }
        }

        private bool ClockPaused()
        {
            lock (_clockSync) return _clockPaused;
        }

        private double CurrentTargetMediaTime()
        {
            lock (_clockSync)
            {
                double target = _clockMediaTime;
                if (!_clockPaused && _clockStamp > 0)
                    target += Math.Max(0, (Stopwatch.GetTimestamp() - _clockStamp) / (double)Stopwatch.Frequency);
                return target;
            }
        }

        public void Start()
        {
            if (_stopping) return;
            try
            {
                _dispatcher.BeginInvoke(DispatcherPriority.Render, new Action(delegate
                {
                    if (_stopping) return;
                    if (_lowPriority)
                    {
                        // Visualizer: one bounded DispatcherTimer tick can consume at most the
                        // newest mailbox frame. Dispatcher pressure therefore drops obsolete
                        // frames instead of building a CompositionTarget/Render callback backlog.
                        if (_presentationTimer != null) return;
                        _presentationTimer = new DispatcherTimer(DispatcherPriority.Render, _dispatcher);
                        _presentationTimer.Interval = TimeSpan.FromMilliseconds(1000.0 / _presentationFps);
                        _presentationTimer.Tick += delegate { PresentLatestFrameOnComposition(); };
                        _presentationTimer.Start();
                    }
                    else
                    {
                        if (_renderHandler != null) return;
                        _renderHandler = delegate(object sender, EventArgs e) { PresentLatestFrameOnComposition(); };
                        CompositionTarget.Rendering += _renderHandler;
                    }
                }));
            }
            catch { }
            _worker = new Thread(Run)
            {
                IsBackground = true,
                Name = "YOMI preview decoder " + _fps.ToString("0.###", CultureInfo.InvariantCulture) + "fps",
                Priority = _lowPriority ? ThreadPriority.BelowNormal : ThreadPriority.Normal
            };
            _worker.Start();
        }

        private void Run()
        {
            try
            {
                if (_stopping) return;
                var psi = new ProcessStartInfo
                {
                    FileName = _ffmpeg,
                    Arguments = _arguments,
                    UseShellExecute = false,
                    CreateNoWindow = true,
                    RedirectStandardOutput = true,
                    RedirectStandardError = true,
                    WorkingDirectory = Path.GetDirectoryName(_ffmpeg)
                };
                var process = new Process { StartInfo = psi, EnableRaisingEvents = false };
                process.ErrorDataReceived += delegate(object sender, DataReceivedEventArgs e)
                {
                    if (String.IsNullOrWhiteSpace(e.Data)) return;
                    lock (_errorSync)
                    {
                        if (_errors.Length < 4096) _errors.AppendLine(e.Data);
                    }
                };
                if (!process.Start()) throw new InvalidOperationException("FFmpeg process did not start.");
                _process = process;
                if (_stopping)
                {
                    try { if (!process.HasExited) process.Kill(); } catch { }
                    return;
                }
                if (_processOwner != null && !_processOwner(process))
                {
                    try { process.Kill(); } catch { }
                    throw new InvalidOperationException("YOMI could not establish crash-safe ownership of the preview decoder.");
                }
                process.BeginErrorReadLine();
                try
                {
                    process.PriorityClass = _lowPriority ? ProcessPriorityClass.BelowNormal : ProcessPriorityClass.Normal;
                    if (_lowPriority) process.PriorityBoostEnabled = false;
                }
                catch { }
                ReadFrames(process);
            }
            catch (Exception ex)
            {
                if (!_stopping) Fail(ex.Message);
            }
            finally
            {
                Process process = _process;
                try { if (process != null && !process.HasExited) process.Kill(); } catch { }
                try { if (process != null) process.Dispose(); } catch { }
                _process = null;
            }
        }

        private void ReadFrames(Process process)
        {
            int stride = _width * 4;
            int size = stride * _height;
            byte[] readBuffer = new byte[size];
            double frameSeconds = 1.0 / _fps;
            long frameIndex = 0;
            Stream stdout = process.StandardOutput.BaseStream;

            while (!_stopping)
            {
                while (!_stopping && ClockPaused()) Thread.Sleep(10);
                if (_stopping) break;
                if (!ReadExact(stdout, readBuffer, size)) break;

                double frameMediaTime = _startMediaTime + frameIndex * frameSeconds;
                bool stale = false;
                while (!_stopping)
                {
                    if (ClockPaused())
                    {
                        Thread.Sleep(10);
                        continue;
                    }
                    double targetMediaTime = CurrentTargetMediaTime();
                    double delta = frameMediaTime - targetMediaTime;
                    if (delta < -(frameSeconds * 1.25))
                    {
                        stale = true;
                        break;
                    }
                    // Decoder lead is bounded, while final presentation cadence belongs to the
                    // coalescing dispatcher/composition presenter. The worker only prevents FFmpeg from racing
                    // arbitrarily far ahead of the authoritative audio clock.
                    // R61.80: keep roughly one decoded frame ready ahead of the audio clock.
                    // The old half-frame lead routinely missed the next WPF composition boundary
                    // after even modest dispatcher work. Final presentation is still clock-gated
                    // by the presenter clock, so this does not let preview run ahead.
                    if (delta <= frameSeconds * 1.05) break;
                    double remainingMs = Math.Max(0.0, (delta - frameSeconds * 0.75) * 1000.0);
                    if (remainingMs > 5.0) Thread.Sleep((int)Math.Min(5.0, Math.Max(1.0, remainingMs - 2.0)));
                    else { Thread.SpinWait(120); Thread.Yield(); }
                }
                if (_stopping) break;
                if (stale)
                {
                    frameIndex++;
                    continue;
                }

                lock (_frameSync)
                {
                    if (_mailboxVersion > _paintedVersion) Interlocked.Increment(ref _measureMailboxOverwrites);
                    Buffer.BlockCopy(readBuffer, 0, _mailboxFrame, 0, size);
                    _mailboxVersion++;
                    Interlocked.Increment(ref _measureDecodedFrames);
                }
                frameIndex++;
            }

            if (!_stopping && !_deliveredFirstFrame)
            {
                string detail = GetErrorText();
                if (String.IsNullOrWhiteSpace(detail)) detail = "FFmpeg exited before producing a preview frame.";
                Fail(detail);
            }
        }

        private void PresentLatestFrameOnComposition()
        {
            if (_stopping || ClockPaused()) return;
            long now = Stopwatch.GetTimestamp();
            if (_nextPresentationStamp <= 0) _nextPresentationStamp = now;
            // WPF only presents on composition boundaries. Choose the nearest boundary at or
            // after the ideal deadline instead of flooding DispatcherPriority.Render callbacks.
            if (now + Math.Max(1, _periodTicks / 8) < _nextPresentationStamp) return;

            long version;
            lock (_frameSync) version = _mailboxVersion;
            if (version <= 0 || version == _paintedVersion) return;

            long latenessTicks = Math.Max(0, now - _nextPresentationStamp);
            if (latenessTicks > _periodTicks) _measureMissedDeadlines += (int)Math.Min(1000, latenessTicks / _periodTicks);
            int stride = _width * 4;
            try
            {
                lock (_frameSync)
                {
                    version = _mailboxVersion;
                    if (version == _paintedVersion) return;
                    Buffer.BlockCopy(_mailboxFrame, 0, _presentFrame, 0, _presentFrame.Length);
                    _paintedVersion = version;
                }
                // Keep WPF bitmap upload outside the decoder mailbox lock. A slow composition
                // copy must never prevent FFmpeg from publishing the next latest frame.
                _bitmap.WritePixels(new Int32Rect(0, 0, _width, _height), _presentFrame, stride, 0);
                RecordPresentationCadence(now);
                if (!_deliveredFirstFrame)
                {
                    _target.Source = _bitmap;
                    _target.Visibility = Visibility.Visible;
                    _deliveredFirstFrame = true;
                    if (_firstFrame != null) _firstFrame();
                }
            }
            catch (Exception ex) { Fail(ex.Message); }
            finally
            {
                // Advance from the ideal timeline rather than from actual paint time. This prevents
                // one late composition callback from permanently phase-shifting every later frame.
                if (_nextPresentationStamp <= 0) _nextPresentationStamp = now + _periodTicks;
                else
                {
                    do { _nextPresentationStamp += _periodTicks; }
                    while (_nextPresentationStamp < now - _periodTicks);
                }
            }
        }

        private void RecordPresentationCadence(long now)
        {
            if (_lastPresentationStamp > 0)
            {
                double intervalMs = (now - _lastPresentationStamp) * 1000.0 / Stopwatch.Frequency;
                double idealMs = 1000.0 / _presentationFps;
                double error = Math.Abs(intervalMs - idealMs);
                if (_intervalErrorCount < _intervalErrors.Length) _intervalErrorCount++;
                else
                {
                    double old = _intervalErrors[_intervalErrorCursor];
                    _intervalErrorSquareSum -= old * old;
                }
                _intervalErrors[_intervalErrorCursor] = error;
                _intervalErrorCursor = (_intervalErrorCursor + 1) % _intervalErrors.Length;
                _intervalErrorSquareSum += error * error;
                _intervalSumMs += intervalMs;
                if (error > _maxIntervalErrorMs) _maxIntervalErrorMs = error;
            }
            _lastPresentationStamp = now;
            _measureFrames++;

            double elapsed = (now - _measureStartedStamp) / (double)Stopwatch.Frequency;
            if (elapsed < 2.0) return;
            var metrics = new PreviewCadenceMetrics();
            metrics.Frames = _measureFrames;
            metrics.DecodedFrames = Interlocked.Exchange(ref _measureDecodedFrames, 0);
            metrics.MailboxOverwrites = Interlocked.Exchange(ref _measureMailboxOverwrites, 0);
            metrics.DeliveredFps = _measureFrames / Math.Max(0.001, elapsed);
            metrics.MeanIntervalMs = _measureFrames > 1 ? _intervalSumMs / (_measureFrames - 1) : 0;
            metrics.JitterRmsMs = _intervalErrorCount > 0 ? Math.Sqrt(Math.Max(0, _intervalErrorSquareSum) / _intervalErrorCount) : 0;
            metrics.MaxIntervalErrorMs = _maxIntervalErrorMs;
            metrics.MissedDeadlines = _measureMissedDeadlines;
            if (_intervalErrorCount > 0)
            {
                double[] sorted = new double[_intervalErrorCount];
                for (int i = 0; i < _intervalErrorCount; i++) sorted[i] = _intervalErrors[i];
                Array.Sort(sorted);
                int p95 = Math.Max(0, Math.Min(sorted.Length - 1, (int)Math.Ceiling(sorted.Length * 0.95) - 1));
                metrics.P95IntervalErrorMs = sorted[p95];
            }
            if (_cadenceMeasured != null) _cadenceMeasured(metrics);
            _measureStartedStamp = now;
            _measureFrames = 0;
            _measureMissedDeadlines = 0;
            _intervalErrorCount = 0;
            _intervalErrorCursor = 0;
            _intervalErrorSquareSum = 0;
            _intervalSumMs = 0;
            _maxIntervalErrorMs = 0;
        }

        private static bool ReadExact(Stream stream, byte[] buffer, int count)
        {
            int offset = 0;
            while (offset < count)
            {
                int read = stream.Read(buffer, offset, count - offset);
                if (read <= 0) return false;
                offset += read;
            }
            return true;
        }

        private string GetErrorText()
        {
            lock (_errorSync) return _errors.ToString().Trim();
        }

        private void Fail(string reason)
        {
            if (_stopping || Interlocked.Exchange(ref _failureSent, 1) != 0) return;
            string detail = String.IsNullOrWhiteSpace(reason) ? GetErrorText() : reason;
            try
            {
                _dispatcher.BeginInvoke(DispatcherPriority.Background, new Action(delegate
                {
                    if (!_stopping && _failed != null) _failed(detail);
                }));
            }
            catch { }
        }

        public void Dispose()
        {
            if (_stopping) return;
            _stopping = true;
            try
            {
                Action unsubscribe = delegate
                {
                    if (_presentationTimer != null)
                    {
                        try { _presentationTimer.Stop(); } catch { }
                        _presentationTimer = null;
                    }
                    if (_renderHandler != null)
                    {
                        try { CompositionTarget.Rendering -= _renderHandler; } catch { }
                        _renderHandler = null;
                    }
                };
                if (_dispatcher.CheckAccess()) unsubscribe();
                else if (!_dispatcher.HasShutdownStarted && !_dispatcher.HasShutdownFinished) _dispatcher.BeginInvoke(DispatcherPriority.Send, unsubscribe);
            }
            catch { }
            Process process = _process;
            if (process != null)
            {
                ThreadPool.QueueUserWorkItem(delegate(object ignored)
                {
                    try { if (!process.HasExited) process.Kill(); } catch { }
                });
            }
        }
    }

