        public SlotRecord()
        {
            Id = ""; Name = ""; SourceKind = "Playlist"; PoolName = ""; BroadcastPreset = "Keep current"; CreatedUtc = ""; UpdatedUtc = ""; LastUsedUtc = "";
        }

        public string ListSubtitle
        {
            get
            {
                string source = String.IsNullOrWhiteSpace(SourceKind) ? "Playlist" : SourceKind;
                if (String.Equals(source, "Pool", StringComparison.OrdinalIgnoreCase) && !String.IsNullOrWhiteSpace(PoolName)) source += " | " + PoolName;
                string count = TrackCount.ToString("N0", CultureInfo.InvariantCulture) + " tracks";
                string bookmark = BookmarkOccurrence > 0 ? "item " + BookmarkOccurrence.ToString(CultureInfo.InvariantCulture) : "not started";
                return (IsActive ? "Current | " : "") + source + " | " + count + " | " + bookmark + (Paused ? " | paused" : "");
            }
        }

        public string BroadcastSubtitle
        {
            get { return "Preferred layout: " + (String.IsNullOrWhiteSpace(BroadcastPreset) ? "Keep current" : BroadcastPreset); }
        }

        public SlotRecord Clone()
        {
            return new SlotRecord
            {
                Id = Id, Name = Name, SourceKind = SourceKind, PoolName = PoolName, TrackCount = TrackCount,
                BookmarkOccurrence = BookmarkOccurrence, BookmarkSeconds = BookmarkSeconds, Paused = Paused, BroadcastPreset = BroadcastPreset, IsActive = IsActive,
                CreatedUtc = CreatedUtc, UpdatedUtc = UpdatedUtc, LastUsedUtc = LastUsedUtc
            };
        }
    }

